def utc_now() -> datetime:
    return datetime.now(timezone.utc)


def utc_now_iso() -> str:
    return utc_now().replace(microsecond=0).isoformat()


def _dict_factory(cursor: sqlite3.Cursor, row: tuple) -> dict:
    """Row factory that returns plain dicts so .get() works everywhere."""
    return {col[0]: row[idx] for idx, col in enumerate(cursor.description)}


def open_db() -> sqlite3.Connection:
    conn = sqlite3.connect(str(DB_PATH))
    conn.row_factory = _dict_factory
    # Sprint-mega Bug C: busy_timeout is the primary backstop for write
    # contention. Combined with WAL mode (enabled at bootstrap below) this
    # makes 'database is locked' errors effectively impossible under normal
    # dashboard load. retry_on_lock() is a secondary belt-and-suspenders.
    try:
        conn.execute("PRAGMA busy_timeout = 5000")
    except Exception:  # pragma: no cover
        pass
    return conn


# Bootstrap: enable WAL mode once per process start so all `open_db()`
# connections share the WAL. Safe to call repeatedly.
try:
    from src.db.retry import enable_wal_mode as _enable_wal_mode
    _enable_wal_mode(DB_PATH)
except Exception as _exc:  # pragma: no cover
    logging.getLogger(__name__).warning("WAL mode bootstrap failed: %s", _exc)

# Bootstrap: ensure every versioned table has a ``version INTEGER DEFAULT 1``
# column so optimistic-concurrency checks on POST handlers don't fail with
# a schema error against old DBs. Safe to call repeatedly.
try:
    from src.db.optimistic import ensure_all_version_columns as _ensure_versions
    with sqlite3.connect(str(DB_PATH)) as _boot_conn:
        _migrated = _ensure_versions(_boot_conn)
        if _migrated:
            logging.getLogger(__name__).info(
                "added version column to tables: %s", ", ".join(_migrated),
            )
except Exception as _exc:  # pragma: no cover
    logging.getLogger(__name__).warning("version-column bootstrap failed: %s", _exc)


def normalize_text(value: Any) -> str:
    if value is None:
        return ""
    return str(value).strip()


def normalize_optional_text(value: Any) -> str | None:
    text = normalize_text(value)
    return text if text else None


def normalize_amount_input(value: Any) -> float | None:
    text = normalize_text(value)
    if not text:
        return None
    try:
        return round(float(text.replace(",", "")), 2)
    except Exception:
        return None


def normalize_key(value: Any) -> str:
    return " ".join(normalize_text(value).casefold().split())


def get_user_lang(user: dict[str, Any] | None) -> str:
    """Return the user's preferred language (``'fr'`` or ``'en'``).

    Falls back to ``'fr'`` (Quebec default) for unauthenticated requests or
    rows that have no ``language`` column yet.
    """
    if not user:
        return "fr"
    lang = normalize_text(user.get("language") or "fr")
    return lang if lang in ("fr", "en") else "fr"


