def safe_json_loads(value: Any) -> dict[str, Any]:
    if value is None:
        return {}
    if isinstance(value, dict):
        return value
    try:
        loaded = json.loads(str(value))
        return loaded if isinstance(loaded, dict) else {}
    except Exception:
        return {}


def esc(value: Any) -> str:
    return html.escape("" if value is None else str(value), quote=True)


def urlquote(value: Any) -> str:
    return urllib.parse.quote("" if value is None else str(value), safe="")


def _preview_banner(feature_name: str, note: str = "",
                     expected_ready_date: str = "2026-05-15") -> str:
    """Yellow "not CPA-ready" banner inserted at the top of incomplete
    feature pages. Inventoried in Sprint D and shipped in Sprint E Phase 1
    so a CPA using the dashboard cannot mistake a planning view for a
    submission-ready document.
    """
    safe_feature = esc(feature_name)
    safe_note = esc(note) if note else ""
    safe_date = esc(expected_ready_date)
    note_html = f"<br>{safe_note}" if safe_note else ""
    return (
        '<div role="alert" style="background:#FFF3CD;border:1px solid #FFC107;'
        'padding:12px 16px;margin:10px 0 18px;border-radius:6px;color:#856404;'
        'font-size:13px;line-height:1.5;">'
        '<strong>&#9888;&#65039; PREVIEW &mdash; do not submit to clients or regulators</strong>'
        f'<br><strong>{safe_feature}</strong> is in development. '
        f'Expected production-ready: {safe_date}.{note_html}'
        '<br><small>Numbers shown here must not be used for official '
        'filings or professional work product.</small>'
        '</div>'
    )


def _match_transaction_to_document(conn, client_code, amount, date, merchant_name):
    """Find best candidate document for a bank transaction.

    Uses the sliding-scale match policy from src/engines/bank_match_tolerance.
    Returns a dict:
      {
        "document_id":      str or None,
        "confidence_tier":  "auto" | "review_required" | "manual_only" | None,
        "auto_apply":       bool,       # False for high-amount or ambiguous
        "breakdown":        dict,       # amount_diff / date_diff / vendor_sim
        "reason":           str,        # why we chose / didn't auto-apply
        "candidate_count":  int,
      }

    Legacy callers that just want the matched document_id can still read
    result["document_id"]. The old return type (str | None) is preserved
    via the `_match_transaction_to_document_id` wrapper below.
    """
    from datetime import datetime, timedelta
    from src.engines.bank_match_tolerance import (  # noqa: PLC0415
        policy_for_amount,
        score_candidate,
    )

    try:
        txn_date = datetime.strptime(date, '%Y-%m-%d').date()
    except Exception:
        return {
            "document_id": None, "confidence_tier": None, "auto_apply": False,
            "breakdown": None, "reason": "invalid_tx_date", "candidate_count": 0,
        }

    policy = policy_for_amount(amount)
    date_from = (txn_date - timedelta(days=policy.date_window_days)).isoformat()
    date_to = (txn_date + timedelta(days=policy.date_window_days)).isoformat()

    candidates = conn.execute('''
        SELECT document_id, vendor, amount, document_date
        FROM documents
        WHERE client_code = ?
        AND ABS(COALESCE(amount, 0) - ?) <= ?
        AND document_date BETWEEN ? AND ?
        AND matched_bank_transaction IS NULL
        AND COALESCE(review_status,'') != 'Ignored'
    ''', (client_code, abs(amount), policy.amount_tol, date_from, date_to)).fetchall()

    if not candidates:
        return {
            "document_id": None, "confidence_tier": None,
            "auto_apply": False, "breakdown": None,
            "reason": "no_candidates", "candidate_count": 0,
        }

    # Score each candidate so the UI can show breakdown on high-value matches.
    tx_day = txn_date.toordinal()
    scored: list[tuple[Any, Any]] = []
    for c in candidates:
        doc_id = c[0] if not hasattr(c, "keys") else c["document_id"]
        vendor = c[1] if not hasattr(c, "keys") else c["vendor"]
        doc_amount = c[2] if not hasattr(c, "keys") else c["amount"]
        doc_date = c[3] if not hasattr(c, "keys") else c["document_date"]
        try:
            d_day = datetime.strptime(doc_date, "%Y-%m-%d").date().toordinal()
        except Exception:
            d_day = tx_day
        score = score_candidate(
            tx_amount=amount,
            tx_date_days=tx_day,
            tx_merchant=merchant_name,
            doc_amount=doc_amount or 0.0,
            doc_date_days=d_day,
            doc_vendor=vendor,
            policy=policy,
        )
        scored.append((doc_id, score))

    # Keep only candidates whose vendor similarity clears the tier's floor.
    passing = [(d, s) for d, s in scored if s.vendor_ok]
    # If vendor threshold is 0 (small-amount tier) every candidate passes.

    if len(passing) == 0:
        # No candidate met the vendor-similarity bar for this amount.
        return {
            "document_id": None, "confidence_tier": policy.confidence_tier,
            "auto_apply": False,
            "breakdown": scored[0][1].as_dict() if scored else None,
            "reason": "vendor_name_too_different_for_amount",
            "candidate_count": len(candidates),
        }

    # Ambiguous multiple matches — never auto-pick; flag for manual review.
    if len(passing) > 1:
        best_doc, best_score = max(passing, key=lambda t: t[1].vendor_similarity)
        return {
            "document_id": best_doc, "confidence_tier": "review_required",
            "auto_apply": False, "breakdown": best_score.as_dict(),
            "reason": "multiple_candidates_require_cpa_selection",
            "candidate_count": len(passing),
        }

    doc_id, score = passing[0]
    tier = policy.confidence_tier
    reason = "single_candidate_match"
    return {
        "document_id": doc_id, "confidence_tier": tier,
        "auto_apply": policy.auto_apply, "breakdown": score.as_dict(),
        "reason": reason, "candidate_count": 1,
    }


def _match_transaction_to_document_id(conn, client_code, amount, date, merchant_name):
    """Backwards-compatible shim used by callers that only need the doc_id
    and want the old 'auto-apply-if-match-found' behaviour. The richer
    policy-aware dict is available from _match_transaction_to_document.
    """
    res = _match_transaction_to_document(conn, client_code, amount, date, merchant_name)
    if res.get("auto_apply"):
        return res.get("document_id")
    return None


def _save_and_match_bank_txs(client_code: str, plaid_txs: list) -> tuple[int, int]:
    """Save Plaid transactions and auto-match to documents.

    Uses _match_transaction_to_document for candidate selection. Updates
    documents.matched_bank_transaction and bank_transactions.matched_document_id.
    Returns (inserted_count, matched_count).
    """
    inserted = 0
    matched = 0
    with open_db() as conn:
        for tx in plaid_txs:
            plaid_tx_id = getattr(tx, "transaction_id", None) or ""
            if not plaid_tx_id:
                continue
            existing = conn.execute(
                "SELECT id, matched_document_id FROM bank_transactions WHERE plaid_transaction_id=?",
                (plaid_tx_id,),
            ).fetchone()
            tx_date = getattr(tx, "date", None)
            tx_date_str = tx_date.isoformat() if hasattr(tx_date, "isoformat") else str(tx_date or "")
            tx_amount = float(getattr(tx, "amount", 0) or 0)
            description = getattr(tx, "name", "") or ""
            merchant = getattr(tx, "merchant_name", "") or ""
            category_list = getattr(tx, "category", None) or []
            category = ", ".join(category_list) if isinstance(category_list, list) else str(category_list)
            account_id = getattr(tx, "account_id", "") or ""
            pending = 1 if getattr(tx, "pending", False) else 0

            match_result = _match_transaction_to_document(
                conn, client_code, tx_amount, tx_date_str, merchant or description,
            )
            match_doc_id = match_result.get("document_id")
            match_tier = match_result.get("confidence_tier") or "auto"
            auto_apply = bool(match_result.get("auto_apply"))
            try:
                match_score_json = json.dumps(match_result.get("breakdown") or {})
            except Exception:
                match_score_json = None

            if existing:
                tx_row_id = existing["id"]
                if match_doc_id and not existing["matched_document_id"]:
                    conn.execute(
                        "UPDATE bank_transactions SET matched_document_id=?, "
                        "reconciled=?, match_confidence_tier=?, match_score_json=? "
                        "WHERE id=?",
                        (match_doc_id, 1 if auto_apply else 0, match_tier,
                         match_score_json, tx_row_id),
                    )
                    if auto_apply:
                        conn.execute(
                            "UPDATE documents SET matched_bank_transaction=? WHERE document_id=?",
                            (tx_row_id, match_doc_id),
                        )
                    matched += 1
                continue

            row_id = secrets.token_hex(16)
            conn.execute(
                "INSERT INTO bank_transactions (id, client_code, plaid_transaction_id,"
                " account_id, date, amount, description, merchant_name, category, pending,"
                " matched_document_id, reconciled, match_confidence_tier, match_score_json)"
                " VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?)",
                (row_id, client_code, plaid_tx_id, account_id, tx_date_str, tx_amount,
                 description, merchant, category, pending, match_doc_id,
                 1 if (match_doc_id and auto_apply) else 0,
                 match_tier, match_score_json),
            )
            inserted += 1
            if match_doc_id and auto_apply:
                conn.execute(
                    "UPDATE documents SET matched_bank_transaction=? WHERE document_id=?",
                    (row_id, match_doc_id),
                )
                matched += 1
        conn.commit()
    return inserted, matched


def parse_form_body(raw: bytes) -> dict[str, str]:
    try:
        parsed = urllib.parse.parse_qs(raw.decode("utf-8"), keep_blank_values=True)
    except (UnicodeDecodeError, ValueError):
        # Multipart uploads contain binary image/PDF data that isn't valid UTF-8.
        # Return empty dict — the multipart parser handles these requests instead.
        return {}
    return {k: v[0] if v else "" for k, v in parsed.items()}


def _parse_multipart_simple(
    raw: bytes, content_type: str
) -> tuple[dict[str, str], bytes, str]:
    """Minimal multipart/form-data parser. Returns (fields, file_bytes, filename)."""
    fields: dict[str, str] = {}
    file_bytes = b""
    filename = ""

    boundary_str = ""
    for part in content_type.split(";"):
        part = part.strip()
        if part.startswith("boundary="):
            boundary_str = part[len("boundary="):].strip().strip('"')
            break
    if not boundary_str:
        return fields, file_bytes, filename

    boundary = ("--" + boundary_str).encode()
    parts = raw.split(boundary)

    for chunk in parts[1:]:
        if chunk in (b"--\r\n", b"--", b"--\r\n--"):
            continue
        if chunk.startswith(b"--"):
            continue
        if b"\r\n\r\n" not in chunk:
            continue
        header_block, body = chunk.split(b"\r\n\r\n", 1)
        if body.endswith(b"\r\n"):
            body = body[:-2]

        headers_raw = header_block.decode("utf-8", errors="replace")
        disp = ""
        for line in headers_raw.splitlines():
            if line.lower().startswith("content-disposition"):
                disp = line
        if 'filename="' in disp:
            fn_start = disp.index('filename="') + len('filename="')
            fn_end = disp.index('"', fn_start)
            filename = disp[fn_start:fn_end]
            file_bytes = body
        elif 'name="' in disp:
            n_start = disp.index('name="') + len('name="')
            n_end = disp.index('"', n_start)
            name = disp[n_start:n_end]
            fields[name] = body.decode("utf-8", errors="replace")

    return fields, file_bytes, filename


def _parse_multipart_files(
    raw: bytes, content_type: str
) -> tuple[dict[str, str], list[tuple[str, bytes]]]:
    """Multipart parser that returns (fields, [(filename, file_bytes), ...])."""
    fields: dict[str, str] = {}
    files: list[tuple[str, bytes]] = []

    boundary_str = ""
    for part in content_type.split(";"):
        part = part.strip()
        if part.startswith("boundary="):
            boundary_str = part[len("boundary="):].strip().strip('"')
            break
    if not boundary_str:
        return fields, files

    boundary = ("--" + boundary_str).encode()
    parts = raw.split(boundary)

    for chunk in parts[1:]:
        if chunk in (b"--\r\n", b"--", b"--\r\n--") or chunk.startswith(b"--"):
            continue
        if b"\r\n\r\n" not in chunk:
            continue
        header_block, body = chunk.split(b"\r\n\r\n", 1)
        if body.endswith(b"\r\n"):
            body = body[:-2]

        headers_raw = header_block.decode("utf-8", errors="replace")
        disp = ""
        for line in headers_raw.splitlines():
            if line.lower().startswith("content-disposition"):
                disp = line
        if 'filename="' in disp:
            fn_start = disp.index('filename="') + len('filename="')
            fn_end = disp.index('"', fn_start)
            fname = disp[fn_start:fn_end]
            if fname and body:
                files.append((fname, body))
        elif 'name="' in disp:
            n_start = disp.index('name="') + len('name="')
            n_end = disp.index('"', n_start)
            name = disp[n_start:n_end]
            fields[name] = body.decode("utf-8", errors="replace")

    return fields, files


def hash_password(password: str) -> str:
    return bcrypt.hashpw(password.encode(), bcrypt.gensalt()).decode()


def verify_password(password: str, stored_hash: str) -> bool:
    """Verify password against stored hash. Supports bcrypt and legacy SHA-256."""
    if stored_hash.startswith(("$2b$", "$2a$", "$2y$")):
        return bcrypt.checkpw(password.encode(), stored_hash.encode())
    # Legacy SHA-256 fallback (transition only)
    return hashlib.sha256(password.encode()).hexdigest() == stored_hash


# ---------------------------------------------------------------------------
# Signed set-password / forgot-password links
# ---------------------------------------------------------------------------

import hmac as _hmac

PASSWORD_LINK_SECRET_FILE = str(ROOT_DIR / "data" / "password_link_secret")


def _get_password_link_secret() -> str:
    if not os.path.exists(PASSWORD_LINK_SECRET_FILE):
        os.makedirs(os.path.dirname(PASSWORD_LINK_SECRET_FILE), exist_ok=True)
        with open(PASSWORD_LINK_SECRET_FILE, "w") as f:
            f.write(secrets.token_urlsafe(48))
        try:
            os.chmod(PASSWORD_LINK_SECRET_FILE, 0o600)
        except Exception:
            pass
    with open(PASSWORD_LINK_SECRET_FILE) as f:
        return f.read().strip()


def _generate_password_link(username: str, expires_hours: int = 72) -> str:
    """Returns signed URL-safe token: base64(username.expiry.hmac)."""
    expiry = int(time.time()) + (expires_hours * 3600)
    payload = f"{username}.{expiry}"
    sig = _hmac.new(
        _get_password_link_secret().encode(),
        payload.encode(),
        hashlib.sha256,
    ).hexdigest()[:32]
    token = base64.urlsafe_b64encode(f"{payload}.{sig}".encode()).decode().rstrip("=")
    return token


def _verify_password_link(token: str) -> str | None:
    """Returns username if token is valid and not expired, else None."""
    try:
        padded = token + "=" * (4 - len(token) % 4)
        decoded = base64.urlsafe_b64decode(padded).decode()
        parts = decoded.rsplit(".", 2)
        if len(parts) != 3:
            return None
        username, expiry, sig = parts
        if int(expiry) < int(time.time()):
            return None
        payload = f"{username}.{expiry}"
        expected = _hmac.new(
            _get_password_link_secret().encode(),
            payload.encode(),
            hashlib.sha256,
        ).hexdigest()[:32]
        if not _hmac.compare_digest(sig, expected):
            return None
        return username
    except Exception:
        return None


def _resolve_firm_from_ingest_key(api_key: str) -> dict | None:
    """Return the firm row whose ``ingest_api_key`` matches (constant-
    time per row). None if no match or key is empty/None."""
    if not api_key:
        return None
    try:
        with open_db() as conn:
            rows = conn.execute(
                "SELECT firm_code, ingest_api_key FROM firms "
                "WHERE ingest_api_key IS NOT NULL AND ingest_api_key != ''",
            ).fetchall()
    except sqlite3.OperationalError:
        return None
    for row in rows:
        if isinstance(row, dict):
            stored = row.get("ingest_api_key")
            fc = row.get("firm_code")
        elif isinstance(row, sqlite3.Row):
            stored = row["ingest_api_key"]
            fc = row["firm_code"]
        else:
            stored = row[1]
            fc = row[0]
        if stored and _hmac.compare_digest(stored.encode(), api_key.encode()):
            return {"firm_code": fc}
    return None


def _rotate_firm_ingest_key(firm_code: str) -> str | None:
    """Generate a new ingest_api_key for the firm and return it.
    Returns None if the firm doesn't exist."""
    new_key = secrets.token_urlsafe(32)
    with open_db() as conn:
        cur = conn.execute(
            "UPDATE firms SET ingest_api_key = ? WHERE firm_code = ?",
            (new_key, firm_code),
        )
        if cur.rowcount == 0:
            return None
        conn.commit()
    return new_key


def _password_reset_token_hash(token: str) -> str:
    """Hash a password-reset token with the shared link secret. Storing
    the hash (not the raw token) means a DB leak can't be replayed, and
    we still get constant-time equality via hmac.compare_digest."""
    return _hmac.new(
        _get_password_link_secret().encode(),
        b"pwreset-used:" + token.encode(),
        hashlib.sha256,
    ).hexdigest()


def _password_reset_token_already_used(token: str) -> bool:
    """Return True if the token's hash has been recorded as consumed."""
    h = _password_reset_token_hash(token)
    try:
        with open_db() as conn:
            row = conn.execute(
                "SELECT 1 FROM password_reset_used WHERE token_hash = ?",
                (h,),
            ).fetchone()
        return row is not None
    except sqlite3.OperationalError:
        # Table missing on a minimal DB → treat as "not used yet" so the
        # reset can proceed; the bootstrap migration creates it.
        return False


def _password_reset_token_mark_used(token: str, username: str) -> None:
    """Record the token hash so a second /set-password with the same
    token is refused."""
    h = _password_reset_token_hash(token)
    try:
        with open_db() as conn:
            conn.execute(
                "INSERT OR IGNORE INTO password_reset_used "
                "(token_hash, username, used_at) VALUES (?, ?, ?)",
                (h, username, utc_now_iso()),
            )
            # Lazy cleanup: purge entries older than 7 days so the table
            # doesn't grow forever. Rate-limited by the cutoff itself.
            cutoff = (utc_now() - timedelta(days=7)).replace(
                microsecond=0,
            ).isoformat()
            conn.execute(
                "DELETE FROM password_reset_used WHERE used_at < ?",
                (cutoff,),
            )
            conn.commit()
    except sqlite3.OperationalError:
        # Table missing — bootstrap hasn't run. Non-fatal; subsequent
        # reuse attempt will find the table absent and pass through.
        pass


def _validate_password_strength(new_pw: str, confirm_pw: str) -> str:
    """Returns an error string, or '' if the password is acceptable."""
    if not new_pw or len(new_pw) < 10:
        return "Minimum 10 caract\u00e8res / Minimum 10 characters"
    if new_pw != confirm_pw:
        return "Les mots de passe ne correspondent pas / Passwords don't match"
    if not re.search(r"[A-Za-z]", new_pw):
        return "Au moins 1 lettre / At least 1 letter"
    if not re.search(r"[0-9]", new_pw):
        return "Au moins 1 chiffre / At least 1 digit"
    return ""


_FORGOT_MAX_PER_HOUR = 3


def _forgot_rate_limited(identifier: str) -> bool:
    cutoff = (utc_now() - timedelta(hours=1)).replace(microsecond=0).isoformat()
    with open_db() as conn:
        row = conn.execute(
            "SELECT COUNT(*) AS c FROM forgot_password_attempts"
            " WHERE identifier=? AND attempted_at >= ?",
            (identifier, cutoff),
        ).fetchone()
        c = row["c"] if row else 0
    return c >= _FORGOT_MAX_PER_HOUR


def _record_forgot_attempt(identifier: str) -> None:
    with open_db() as conn:
        conn.execute(
            "INSERT INTO forgot_password_attempts (identifier, attempted_at) VALUES (?, ?)",
            (identifier, utc_now_iso()),
        )
        # Opportunistic cleanup: drop entries older than 24h.
        old = (utc_now() - timedelta(hours=24)).replace(microsecond=0).isoformat()
        conn.execute(
            "DELETE FROM forgot_password_attempts WHERE attempted_at < ?",
            (old,),
        )
        conn.commit()


# ---------------------------------------------------------------------------
# Schema bootstrap
# ---------------------------------------------------------------------------

def bootstrap_schema() -> None:
    with open_db() as conn:
        # Auth tables
        conn.execute("""
            CREATE TABLE IF NOT EXISTS dashboard_users (
                username      TEXT PRIMARY KEY,
                password_hash TEXT NOT NULL,
                role          TEXT NOT NULL DEFAULT 'employee',
                display_name  TEXT,
                active        INTEGER NOT NULL DEFAULT 1,
                language      TEXT NOT NULL DEFAULT 'fr',
                created_at    TEXT
            )
        """)
        conn.execute("""
            CREATE TABLE IF NOT EXISTS dashboard_sessions (
                session_token TEXT PRIMARY KEY,
                username      TEXT NOT NULL,
                expires_at    TEXT NOT NULL,
                created_at    TEXT
            )
        """)
        # Document assignment tracking
        conn.execute("""
            CREATE TABLE IF NOT EXISTS document_assignments (
                document_id TEXT PRIMARY KEY,
                assigned_to TEXT,
                assigned_by TEXT,
                assigned_at TEXT,
                updated_at  TEXT,
                note        TEXT
            )
        """)
        # Posting jobs (QBO/Sage/Acomba). The home + queue SQL LEFT JOINs
        # this table; a brand-new firm with no QBO activity would 500 on
        # the dashboard home before this was added. Idempotent.
        conn.execute("""
            CREATE TABLE IF NOT EXISTS posting_jobs (
                posting_id      TEXT PRIMARY KEY,
                document_id     TEXT NOT NULL,
                target_system   TEXT NOT NULL,
                entry_kind      TEXT NOT NULL,
                posting_status  TEXT NOT NULL,
                approval_state  TEXT NOT NULL,
                reviewer        TEXT,
                external_id     TEXT,
                payload_json    TEXT NOT NULL DEFAULT '{}',
                error_text      TEXT,
                created_at      TEXT NOT NULL,
                updated_at      TEXT NOT NULL
            )
        """)
        # Portfolio assignments
        conn.execute("""
            CREATE TABLE IF NOT EXISTS user_portfolios (
                username    TEXT NOT NULL,
                client_code TEXT NOT NULL,
                assigned_by TEXT,
                assigned_at TEXT,
                PRIMARY KEY (username, client_code)
            )
        """)
        conn.commit()

        # Add columns to documents if missing. ``get_document`` SELECTs
        # every column below, so a pre-existing ``documents`` table that
        # was created without one of them would crash every document
        # read. Idempotent for DBs that already have them.
        existing = {row["name"] for row in conn.execute("PRAGMA table_info(documents)").fetchall()}
        # TEXT columns used by ``get_document`` / queue / reads. Every
        # SELECTed column below must exist or the read crashes.
        for col in ("file_name", "file_path", "doc_type", "gl_account",
                    "tax_code", "category", "review_status", "raw_result",
                    "client_note", "submitted_by",
                    "assigned_to", "manual_hold_reason", "manual_hold_by",
                    "manual_hold_at", "matched_bank_transaction",
                    "raw_ocr_text", "fraud_flags", "substance_flags"):
            if col not in existing:
                conn.execute(f"ALTER TABLE documents ADD COLUMN {col} TEXT")
        # INTEGER/REAL columns with sane defaults.
        for col, ddl in (
            ("amount",                  "REAL"),
            ("confidence",              "REAL"),
            ("hallucination_suspected", "INTEGER DEFAULT 0"),
            ("correction_count",        "INTEGER DEFAULT 0"),
            ("has_line_items",          "INTEGER DEFAULT 0"),
            ("lines_reconciled",        "INTEGER DEFAULT 0"),
            ("line_total_sum",          "REAL"),
            ("invoice_total_gap",       "REAL"),
            ("deposit_allocated",       "INTEGER DEFAULT 0"),
            # /health/page counts ai_used; missing column → 500.
            ("ai_used",                 "INTEGER DEFAULT 0"),
        ):
            if col not in existing:
                conn.execute(f"ALTER TABLE documents ADD COLUMN {col} {ddl}")
        # Fundamental TEXT columns the dashboard SELECTs in many places.
        for col in ("document_date", "ingest_source", "created_at",
                    "updated_at", "vendor", "client_code"):
            if col not in existing:
                conn.execute(f"ALTER TABLE documents ADD COLUMN {col} TEXT")
        # Multi-user portal uploader tracking.
        for col, ddl in (
            ("uploaded_by_portal_user_id", "INTEGER"),
            ("uploader_name",              "TEXT"),
            ("uploader_email",             "TEXT"),
            # Channel the document arrived on ('portal', 'whatsapp',
            # 'email', 'api', 'manual'). Defaulting to 'portal' keeps
            # existing reports correct for pre-WhatsApp rows.
            ("uploaded_via_channel",       "TEXT DEFAULT 'portal'"),
        ):
            if col not in existing:
                try:
                    conn.execute(
                        f"ALTER TABLE documents ADD COLUMN {col} {ddl}"
                    )
                except sqlite3.OperationalError:
                    pass
        conn.commit()

        # Add must_reset_password / language columns to dashboard_users if missing
        user_cols = {row["name"] for row in conn.execute("PRAGMA table_info(dashboard_users)").fetchall()}
        if "language" not in user_cols:
            conn.execute("ALTER TABLE dashboard_users ADD COLUMN language TEXT NOT NULL DEFAULT 'fr'")
            conn.commit()
        if "must_reset_password" not in user_cols:
            conn.execute("ALTER TABLE dashboard_users ADD COLUMN must_reset_password INTEGER NOT NULL DEFAULT 0")
            # Force all existing users to reset — their hashes may be legacy SHA-256
            conn.execute("UPDATE dashboard_users SET must_reset_password = 1")
            conn.commit()
            print("  [bootstrap] must_reset_password=1 set for all existing users (bcrypt migration)")
        if "totp_secret" not in user_cols:
            conn.execute("ALTER TABLE dashboard_users ADD COLUMN totp_secret TEXT")
            conn.commit()
        if "totp_enabled" not in user_cols:
            conn.execute("ALTER TABLE dashboard_users ADD COLUMN totp_enabled INTEGER DEFAULT 0")
            conn.commit()
        if "email" not in user_cols:
            conn.execute("ALTER TABLE dashboard_users ADD COLUMN email TEXT")
            conn.commit()
        if "whatsapp_number" not in user_cols:
            conn.execute("ALTER TABLE dashboard_users ADD COLUMN whatsapp_number TEXT")
            conn.commit()
        if "firm_code" not in user_cols:
            conn.execute("ALTER TABLE dashboard_users ADD COLUMN firm_code TEXT")
            # Existing users (owner + legacy staff) belong to the OWNER firm.
            conn.execute("UPDATE dashboard_users SET firm_code='OWNER' WHERE firm_code IS NULL OR firm_code=''")
            conn.commit()

        # CPA firms (tier 2). 'OWNER' is reserved for the platform owner.
        conn.execute("""
            CREATE TABLE IF NOT EXISTS firms (
                firm_code              TEXT PRIMARY KEY,
                firm_name              TEXT NOT NULL,
                contact_email          TEXT,
                contact_phone          TEXT,
                billing_email          TEXT,
                language               TEXT DEFAULT 'fr',
                plan                   TEXT DEFAULT 'basic',
                active                 INTEGER DEFAULT 1,
                stripe_customer_id     TEXT,
                stripe_subscription_id TEXT,
                subscription_status    TEXT DEFAULT 'none',
                subscription_plan      TEXT,
                current_period_end     INTEGER,
                created_at             TEXT DEFAULT (datetime('now'))
            )
        """)
        # Idempotent migration for pre-existing installs whose firms table was
        # created before the Stripe billing columns existed. _provision_firm_
        # from_stripe + /billing + _handle_stripe_event all need these columns.
        firm_cols = {row["name"] for row in conn.execute("PRAGMA table_info(firms)").fetchall()}
        # Full set of columns expected by the INSERT + handlers below. A
        # pre-existing ``firms`` table created by a test fixture or
        # earlier migration may be missing any subset of these; we
        # ALTER-add anything missing so the INSERT at the bottom always
        # succeeds.
        for col, ddl in (
            ("firm_name",              "TEXT"),
            ("contact_email",          "TEXT"),
            ("contact_phone",          "TEXT"),
            ("billing_email",          "TEXT"),
            ("language",               "TEXT DEFAULT 'fr'"),
            ("plan",                   "TEXT DEFAULT 'basic'"),
            ("active",                 "INTEGER DEFAULT 1"),
            ("stripe_customer_id",     "TEXT"),
            ("stripe_subscription_id", "TEXT"),
            ("subscription_status",    "TEXT DEFAULT 'none'"),
            ("subscription_plan",      "TEXT"),
            ("current_period_end",     "INTEGER"),
            ("created_at",             "TEXT"),
            # OpenClaw ingest shared secret (X-API-Key header).
            ("ingest_api_key",         "TEXT"),
        ):
            if col not in firm_cols:
                try:
                    conn.execute(f"ALTER TABLE firms ADD COLUMN {col} {ddl}")
                except sqlite3.OperationalError:
                    # Happens if the pk_column already exists under a
                    # different case or if the DB is read-only.
                    pass
        conn.execute(
            "INSERT OR IGNORE INTO firms (firm_code, firm_name, language, plan) VALUES ('OWNER','OtoCPA (Owner)','fr','owner')"
        )
        # Backfill ingest_api_key for every firm that doesn't have one.
        # A firm without a key would be unable to ingest; rather than
        # failing startup, mint one per row. Row shape depends on
        # connection row_factory (_dict_factory or sqlite3.Row).
        try:
            empty_keys = conn.execute(
                "SELECT firm_code FROM firms "
                "WHERE ingest_api_key IS NULL OR ingest_api_key = ''",
            ).fetchall()
            for row in empty_keys:
                if isinstance(row, dict):
                    fc = row.get("firm_code")
                elif isinstance(row, sqlite3.Row):
                    fc = row["firm_code"]
                else:
                    fc = row[0]
                if not fc:
                    continue
                conn.execute(
                    "UPDATE firms SET ingest_api_key = ? WHERE firm_code = ?",
                    (secrets.token_urlsafe(32), fc),
                )
        except sqlite3.OperationalError:
            pass
        conn.commit()

        # Clients firm_code (tier 3 belongs to a firm). Plus the full set
        # of columns the dashboard reads from clients — render_clients_page
        # SELECTs whatsapp_number, contact_email, language, active, etc.
        # A pre-existing minimal clients table missing any of these
        # would 500 the /clients page.
        client_cols = {row["name"] for row in conn.execute("PRAGMA table_info(clients)").fetchall()}
        if "firm_code" not in client_cols:
            conn.execute("ALTER TABLE clients ADD COLUMN firm_code TEXT")
            conn.execute("UPDATE clients SET firm_code='OWNER' WHERE firm_code IS NULL OR firm_code=''")
            conn.commit()
        for _ccol, _cdef in (
            ("client_name",                 "TEXT"),
            ("contact_email",               "TEXT"),
            ("language",                    "TEXT DEFAULT 'fr'"),
            ("active",                      "INTEGER DEFAULT 1"),
            ("whatsapp_number",             "TEXT"),
            ("portal_token",                "TEXT"),
            ("portal_token_created_at",     "TEXT"),
            ("portal_token_rotated_count",  "INTEGER DEFAULT 0"),
            ("created_at",                  "TEXT"),
            # Multi-user portal: dual-mode flag. 'single' keeps the
            # existing anonymous QR/link flow; 'multi' opts the client
            # into invitation-based personal links (see
            # client_portal_users + client_portal_invitations below).
            ("portal_mode",                 "TEXT DEFAULT 'single'"),
            # Hybrid assignment model: client has a primary employee
            # (auto-assignee for new docs) + optional secondary as
            # fallback when primary is inactive. Owner/firm_admin always
            # see everything regardless. NULL = unassigned (firm pool).
            ("primary_employee_email",      "TEXT"),
            ("secondary_employee_email",    "TEXT"),
            ("assignment_updated_at",       "TEXT"),
            ("assignment_updated_by",       "TEXT"),
        ):
            if _ccol not in client_cols:
                try:
                    conn.execute(f"ALTER TABLE clients ADD COLUMN {_ccol} {_cdef}")
                except sqlite3.OperationalError:
                    pass
        # Indexes for fast "who's assigned to which clients" lookups.
        try:
            conn.execute(
                "CREATE INDEX IF NOT EXISTS idx_clients_primary_employee "
                "ON clients(firm_code, primary_employee_email)"
            )
            conn.execute(
                "CREATE INDEX IF NOT EXISTS idx_clients_secondary_employee "
                "ON clients(firm_code, secondary_employee_email)"
            )
        except sqlite3.OperationalError:
            pass
        # Audit trail for client-level assignment changes. Independent
        # of review_workflow_audit (which tracks per-document state).
        conn.execute("""
            CREATE TABLE IF NOT EXISTS client_assignment_history (
                id                  INTEGER PRIMARY KEY AUTOINCREMENT,
                firm_code           TEXT NOT NULL,
                client_code         TEXT NOT NULL,
                action              TEXT NOT NULL,
                previous_primary    TEXT,
                new_primary         TEXT,
                previous_secondary  TEXT,
                new_secondary       TEXT,
                reason              TEXT,
                changed_by          TEXT,
                changed_at          TEXT DEFAULT (datetime('now'))
            )
        """)
        try:
            conn.execute(
                "CREATE INDEX IF NOT EXISTS idx_client_assign_hist_client "
                "ON client_assignment_history(firm_code, client_code, changed_at DESC)"
            )
        except sqlite3.OperationalError:
            pass
        conn.commit()

        # Bank connections firm_code (denormalized for fast firm-scoped reads).
        # Guard: bank_connections is optional in minimal bootstraps (some
        # tests/fresh installs skip it); only migrate if the table exists.
        bc_exists = conn.execute(
            "SELECT name FROM sqlite_master WHERE type='table' AND name='bank_connections'",
        ).fetchone()
        if bc_exists:
            bank_cols = {row["name"] for row in conn.execute("PRAGMA table_info(bank_connections)").fetchall()}
            if "firm_code" not in bank_cols:
                conn.execute("ALTER TABLE bank_connections ADD COLUMN firm_code TEXT")
                conn.execute(
                    "UPDATE bank_connections SET firm_code = COALESCE("
                    "(SELECT firm_code FROM clients WHERE clients.client_code = bank_connections.client_code), 'OWNER')"
                    " WHERE firm_code IS NULL OR firm_code=''"
                )
                conn.commit()

        # Sliding-scale match telemetry: remember which tier each bank
        # transaction match fell into so the reconciliation UI can badge
        # high-value matches and show their score breakdown.
        # Only run when bank_transactions already exists — some tests boot
        # from a DB that doesn't include optional tables, and this
        # migration is strictly additive.
        bt_table = conn.execute(
            "SELECT name FROM sqlite_master WHERE type='table' AND name='bank_transactions'"
        ).fetchone()
        if bt_table:
            bt_cols = {row["name"] for row in conn.execute(
                "PRAGMA table_info(bank_transactions)"
            ).fetchall()}
            if "match_confidence_tier" not in bt_cols:
                conn.execute(
                    "ALTER TABLE bank_transactions ADD COLUMN match_confidence_tier TEXT DEFAULT 'auto'"
                )
            if "match_score_json" not in bt_cols:
                conn.execute("ALTER TABLE bank_transactions ADD COLUMN match_score_json TEXT")
            conn.commit()

        # Rate limit /forgot requests (prevents enumeration + spam)
        conn.execute("""
            CREATE TABLE IF NOT EXISTS forgot_password_attempts (
                identifier  TEXT NOT NULL,
                attempted_at TEXT NOT NULL
            )
        """)
        conn.execute("CREATE INDEX IF NOT EXISTS idx_forgot_identifier ON forgot_password_attempts(identifier)")
        # Password-reset single-use registry. We store a hash of the
        # token so a DB leak can't reconstruct a live reset token.
        conn.execute("""
            CREATE TABLE IF NOT EXISTS password_reset_used (
                token_hash TEXT PRIMARY KEY,
                username   TEXT NOT NULL,
                used_at    TEXT NOT NULL
            )
        """)
        conn.commit()

        # Pending 2FA tokens (issued after password ok, before TOTP verified)
        conn.execute("""
            CREATE TABLE IF NOT EXISTS dashboard_pending_2fa (
                token      TEXT PRIMARY KEY,
                username   TEXT NOT NULL,
                expires_at TEXT NOT NULL,
                created_at TEXT
            )
        """)
        # Plaid bank connections
        conn.execute("""
            CREATE TABLE IF NOT EXISTS bank_connections (
                id TEXT PRIMARY KEY,
                client_code TEXT NOT NULL,
                plaid_access_token TEXT NOT NULL,
                plaid_item_id TEXT NOT NULL,
                institution_name TEXT,
                account_name TEXT,
                account_type TEXT,
                last_sync TEXT,
                active INTEGER DEFAULT 1,
                created_at TEXT DEFAULT (datetime('now')),
                firm_code TEXT
            )
        """)
        # Idempotent backfill: if the table existed before firm_code was
        # baked into the CREATE above, ALTER it now. Earlier in
        # bootstrap_schema we already tried this for *pre-existing*
        # bank_connections; this handles the freshly-created table.
        bc_cols = {row["name"] for row in conn.execute(
            "PRAGMA table_info(bank_connections)").fetchall()}
        if "firm_code" not in bc_cols:
            conn.execute("ALTER TABLE bank_connections ADD COLUMN firm_code TEXT")
        # Plaid bank transactions (imported via /bank/sync, then matched to documents)
        conn.execute("""
            CREATE TABLE IF NOT EXISTS bank_transactions (
                id TEXT PRIMARY KEY,
                client_code TEXT NOT NULL,
                plaid_transaction_id TEXT UNIQUE,
                account_id TEXT,
                date TEXT,
                amount REAL,
                description TEXT,
                merchant_name TEXT,
                category TEXT,
                pending INTEGER DEFAULT 0,
                matched_document_id TEXT,
                reconciled INTEGER DEFAULT 0,
                created_at TEXT DEFAULT (datetime('now'))
            )
        """)
        conn.execute("CREATE INDEX IF NOT EXISTS idx_bank_tx_client ON bank_transactions(client_code)")
        conn.execute("CREATE INDEX IF NOT EXISTS idx_bank_tx_date ON bank_transactions(date)")
        conn.commit()

        # Per-client QuickBooks Online OAuth connections (Sprint 3)
        # Replaces the single-realm data/qbo_config.json approach so each
        # (firm_code, client_code) pair owns its own tokens + realm.
        conn.execute("""
            CREATE TABLE IF NOT EXISTS qbo_connections (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                firm_code TEXT NOT NULL,
                client_code TEXT NOT NULL,
                realm_id TEXT NOT NULL,
                access_token TEXT NOT NULL,
                refresh_token TEXT NOT NULL,
                expires_at INTEGER NOT NULL,
                connected_at TEXT DEFAULT (datetime('now')),
                connected_by TEXT,
                last_refreshed_at TEXT,
                last_error TEXT,
                status TEXT DEFAULT 'active',
                UNIQUE(firm_code, client_code)
            )
        """)
        conn.execute(
            "CREATE INDEX IF NOT EXISTS idx_qbo_firm_client "
            "ON qbo_connections(firm_code, client_code)"
        )
        conn.commit()

        # QBO bidirectional-sync schema (qbo_sync_state + entity caches +
        # webhook queue + per-run log). Kept in a dedicated module so test
        # fixtures can apply the same DDL without importing this dashboard.
        from src.integrations.qbo_schema import apply_qbo_sync_schema
        apply_qbo_sync_schema(conn)

        # Smart-bank-source schema: clients.bank_source + multi-source
        # columns on bank_transactions + bank_tx_dedup audit table.
        from src.integrations.bank_source_schema import apply_bank_source_schema
        apply_bank_source_schema(conn)

        # Gap-1: onboarding checklist + welcome modal state on
        # dashboard_users + user_events audit trail. Applied via the
        # already-open bootstrap connection so the transaction stays
        # consistent with the other migrations above.
        _oc_cols = {r['name'] if hasattr(r, 'keys') else r[1]
                    for r in conn.execute("PRAGMA table_info(dashboard_users)").fetchall()}
        for _col, _ddl in [
            ('getting_started_completed', 'INTEGER DEFAULT 0'),
            ('getting_started_dismissed_at', 'TEXT'),
            ('first_login_at', 'TEXT'),
            ('welcome_seen_at', 'TEXT'),
            ('tour_completed_at', 'TEXT'),
        ]:
            if _col not in _oc_cols:
                conn.execute(f"ALTER TABLE dashboard_users ADD COLUMN {_col} {_ddl}")
        conn.execute("""
            CREATE TABLE IF NOT EXISTS user_events (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                username TEXT,
                firm_code TEXT,
                event_type TEXT,
                event_data TEXT,
                created_at TEXT DEFAULT (datetime('now'))
            )
        """)
        conn.execute(
            "CREATE INDEX IF NOT EXISTS idx_user_events_user "
            "ON user_events(username, event_type)"
        )

        # Gap-2: review queue workflow state machine (assign / submit /
        # approve / reject / escalate) with an append-only audit table.
        conn.execute("""
            CREATE TABLE IF NOT EXISTS review_workflow (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                firm_code TEXT NOT NULL,
                entity_type TEXT NOT NULL,
                entity_id TEXT NOT NULL,
                status TEXT NOT NULL,
                assigned_to_email TEXT,
                submitted_by_email TEXT,
                reviewed_by_email TEXT,
                priority TEXT DEFAULT 'normal',
                assigned_at TEXT,
                submitted_at TEXT,
                reviewed_at TEXT,
                review_notes TEXT,
                rejection_reason TEXT,
                version INTEGER DEFAULT 1,
                UNIQUE(firm_code, entity_type, entity_id)
            )
        """)
        conn.execute(
            "CREATE INDEX IF NOT EXISTS idx_review_workflow_assignee "
            "ON review_workflow(assigned_to_email, status)"
        )
        conn.execute(
            "CREATE INDEX IF NOT EXISTS idx_review_workflow_reviewer "
            "ON review_workflow(firm_code, status)"
        )
        conn.execute("""
            CREATE TABLE IF NOT EXISTS review_workflow_audit (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                workflow_id INTEGER,
                actor_email TEXT,
                actor_role TEXT,
                action TEXT,
                from_status TEXT,
                to_status TEXT,
                notes TEXT,
                created_at TEXT DEFAULT (datetime('now'))
            )
        """)

        # Gap-4: month-end close wizard state + accounting periods.
        conn.execute("""
            CREATE TABLE IF NOT EXISTS close_wizard_state (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                firm_code TEXT NOT NULL,
                client_code TEXT NOT NULL,
                period TEXT NOT NULL,
                step TEXT NOT NULL,
                step_status TEXT NOT NULL DEFAULT 'pending',
                step_data TEXT,
                started_at TEXT,
                completed_at TEXT,
                actor_email TEXT,
                UNIQUE(firm_code, client_code, period, step)
            )
        """)
        conn.execute(
            "CREATE INDEX IF NOT EXISTS idx_close_wizard_scope "
            "ON close_wizard_state(firm_code, client_code, period)"
        )
        conn.execute("""
            CREATE TABLE IF NOT EXISTS accounting_periods (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                firm_code TEXT NOT NULL,
                client_code TEXT NOT NULL,
                period TEXT NOT NULL,
                status TEXT NOT NULL DEFAULT 'open',
                locked_by TEXT,
                locked_at TEXT,
                UNIQUE(firm_code, client_code, period)
            )
        """)

        # Gap-5: client portal notifications + threaded messaging.
        conn.execute("""
            CREATE TABLE IF NOT EXISTS client_notifications (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                client_code TEXT NOT NULL,
                kind TEXT NOT NULL,
                title TEXT,
                body TEXT,
                document_id TEXT,
                created_at TEXT DEFAULT (datetime('now')),
                read_at TEXT
            )
        """)
        conn.execute(
            "CREATE INDEX IF NOT EXISTS idx_client_notifications_client "
            "ON client_notifications(client_code, read_at)"
        )
        conn.execute("""
            CREATE TABLE IF NOT EXISTS client_message_threads (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                firm_code TEXT,
                client_code TEXT,
                subject TEXT,
                document_id TEXT,
                created_at TEXT DEFAULT (datetime('now'))
            )
        """)
        conn.execute("""
            CREATE TABLE IF NOT EXISTS client_message_posts (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                thread_id INTEGER NOT NULL,
                sender_type TEXT NOT NULL,
                sender_id TEXT,
                body TEXT,
                attachment_url TEXT,
                read_at TEXT,
                created_at TEXT DEFAULT (datetime('now'))
            )
        """)
        conn.execute(
            "CREATE INDEX IF NOT EXISTS idx_cm_posts_thread "
            "ON client_message_posts(thread_id, created_at)"
        )
        conn.commit()

        # Sprint 4: client portal via QR token.
        # portal_token gives a client direct, cookieless-until-first-hit access
        # to their own upload/documents/bank/messages page. Tokens are long,
        # random, and stored per client; rotating issues a fresh one and the
        # old one stops resolving immediately.
        client_cols_s4 = {
            row["name"] for row in conn.execute("PRAGMA table_info(clients)").fetchall()
        }
        if "portal_token" not in client_cols_s4:
            conn.execute("ALTER TABLE clients ADD COLUMN portal_token TEXT")
        if "portal_token_created_at" not in client_cols_s4:
            conn.execute("ALTER TABLE clients ADD COLUMN portal_token_created_at TEXT")
        if "portal_token_rotated_count" not in client_cols_s4:
            conn.execute(
                "ALTER TABLE clients ADD COLUMN portal_token_rotated_count INTEGER DEFAULT 0"
            )
        # Unique index on portal_token (NULLs allowed; one-shot idempotent).
        conn.execute(
            "CREATE UNIQUE INDEX IF NOT EXISTS idx_clients_portal_token "
            "ON clients(portal_token) WHERE portal_token IS NOT NULL"
        )
        conn.commit()

        # Backfill portal_token for every client missing one.
        missing = conn.execute(
            "SELECT client_code FROM clients WHERE portal_token IS NULL OR portal_token=''"
        ).fetchall()
        for _row in missing:
            _tok = secrets.token_urlsafe(32)
            conn.execute(
                "UPDATE clients SET portal_token=?, portal_token_created_at=datetime('now'), "
                "portal_token_rotated_count=COALESCE(portal_token_rotated_count,0) "
                "WHERE client_code=?",
                (_tok, _row["client_code"]),
            )
        if missing:
            conn.commit()

        conn.execute("""
            CREATE TABLE IF NOT EXISTS client_messages (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                client_code TEXT NOT NULL,
                firm_code TEXT NOT NULL,
                direction TEXT NOT NULL,
                sender_name TEXT,
                sender_type TEXT NOT NULL,
                body TEXT NOT NULL,
                related_document_id TEXT,
                read_at TEXT,
                sender_portal_user_id INTEGER,
                target_portal_user_id INTEGER,
                created_at TEXT DEFAULT (datetime('now'))
            )
        """)
        # Multi-user: add identity columns to legacy rows too.
        _cm_cols = {r["name"] for r in conn.execute(
            "PRAGMA table_info(client_messages)").fetchall()}
        if "sender_portal_user_id" not in _cm_cols:
            try:
                conn.execute(
                    "ALTER TABLE client_messages ADD COLUMN sender_portal_user_id INTEGER"
                )
            except sqlite3.OperationalError:
                pass
        if "target_portal_user_id" not in _cm_cols:
            try:
                conn.execute(
                    "ALTER TABLE client_messages ADD COLUMN target_portal_user_id INTEGER"
                )
            except sqlite3.OperationalError:
                pass
        conn.execute(
            "CREATE INDEX IF NOT EXISTS idx_client_messages_client "
            "ON client_messages(client_code)"
        )
        conn.execute("""
            CREATE TABLE IF NOT EXISTS client_portal_access (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                client_code TEXT NOT NULL,
                firm_code TEXT NOT NULL,
                portal_token_prefix TEXT,
                ip TEXT,
                user_agent TEXT,
                action TEXT,
                created_at TEXT DEFAULT (datetime('now'))
            )
        """)

        # Multi-user portal: personal user accounts per client.
        conn.execute("""
            CREATE TABLE IF NOT EXISTS client_portal_users (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                firm_code TEXT NOT NULL,
                client_code TEXT NOT NULL,
                email TEXT NOT NULL,
                full_name TEXT,
                role TEXT NOT NULL,
                user_token TEXT UNIQUE NOT NULL,
                status TEXT DEFAULT 'invited',
                invited_by TEXT,
                invited_at TEXT,
                accepted_at TEXT,
                last_active_at TEXT,
                upload_count INTEGER DEFAULT 0,
                suspended_at TEXT,
                removed_at TEXT,
                version INTEGER DEFAULT 1,
                first_tour_completed_at TEXT,
                whatsapp_number TEXT,
                whatsapp_verified INTEGER DEFAULT 0,
                whatsapp_verified_at TEXT,
                UNIQUE(firm_code, client_code, email)
            )
        """)
        # Idempotent migration for older DBs — add the tour column
        # without losing existing rows.
        _cpu_cols = {r['name'] for r in conn.execute(
            "PRAGMA table_info(client_portal_users)").fetchall()}
        if 'first_tour_completed_at' not in _cpu_cols:
            try:
                conn.execute(
                    "ALTER TABLE client_portal_users "
                    "ADD COLUMN first_tour_completed_at TEXT"
                )
            except sqlite3.OperationalError:
                pass
        # WhatsApp identity columns: each portal user may tie one
        # E.164 number so inbound Twilio media can be attributed.
        for _col, _typedef in (
            ('whatsapp_number', 'TEXT'),
            ('whatsapp_verified', 'INTEGER DEFAULT 0'),
            ('whatsapp_verified_at', 'TEXT'),
        ):
            if _col not in _cpu_cols:
                try:
                    conn.execute(
                        f"ALTER TABLE client_portal_users "
                        f"ADD COLUMN {_col} {_typedef}"
                    )
                except sqlite3.OperationalError:
                    pass
        # Partial unique index keeps the number unique inside a firm
        # without penalising rows that never register one.
        conn.execute(
            "CREATE UNIQUE INDEX IF NOT EXISTS idx_cpu_whatsapp_firm "
            "ON client_portal_users(firm_code, whatsapp_number) "
            "WHERE whatsapp_number IS NOT NULL"
        )
        conn.execute(
            "CREATE INDEX IF NOT EXISTS idx_cpu_token "
            "ON client_portal_users(user_token)"
        )
        conn.execute(
            "CREATE INDEX IF NOT EXISTS idx_cpu_client "
            "ON client_portal_users(firm_code, client_code, status)"
        )

        # Pending invitations (separate from users: a user row only exists
        # once someone has accepted; an invitation is the signed link sent
        # to an email before acceptance).
        conn.execute("""
            CREATE TABLE IF NOT EXISTS client_portal_invitations (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                firm_code TEXT NOT NULL,
                client_code TEXT NOT NULL,
                email TEXT NOT NULL,
                full_name TEXT,
                invited_role TEXT NOT NULL,
                invitation_token TEXT UNIQUE NOT NULL,
                invited_by TEXT,
                invited_at TEXT,
                expires_at TEXT,
                accepted_at TEXT,
                status TEXT DEFAULT 'pending',
                invited_language TEXT,
                whatsapp_number TEXT
            )
        """)
        # Idempotent: old DBs get the invited_language column too.
        _cpi_cols = {r['name'] for r in conn.execute(
            "PRAGMA table_info(client_portal_invitations)").fetchall()}
        if 'invited_language' not in _cpi_cols:
            try:
                conn.execute(
                    "ALTER TABLE client_portal_invitations "
                    "ADD COLUMN invited_language TEXT"
                )
            except sqlite3.OperationalError:
                pass
        # Item 5: client_request_id lets the POST handler de-dupe
        # rapid double-clicks without minting two invitation tokens.
        if 'client_request_id' not in _cpi_cols:
            try:
                conn.execute(
                    "ALTER TABLE client_portal_invitations "
                    "ADD COLUMN client_request_id TEXT"
                )
            except sqlite3.OperationalError:
                pass
        # WhatsApp number staged on the invitation row; copied onto
        # the user row on acceptance so the invitee doesn't have to
        # re-register their own number.
        if 'whatsapp_number' not in _cpi_cols:
            try:
                conn.execute(
                    "ALTER TABLE client_portal_invitations "
                    "ADD COLUMN whatsapp_number TEXT"
                )
            except sqlite3.OperationalError:
                pass
        # Partial unique index on client_request_id so NULL rows don't
        # collide. Scoped to firm + client so the same request_id can
        # (in theory) be reused across different clients, though the
        # frontend always mints fresh ones.
        conn.execute(
            "CREATE UNIQUE INDEX IF NOT EXISTS "
            "idx_cpi_client_request "
            "ON client_portal_invitations(firm_code, client_code, client_request_id) "
            "WHERE client_request_id IS NOT NULL"
        )
        conn.execute(
            "CREATE INDEX IF NOT EXISTS idx_cpi_token "
            "ON client_portal_invitations(invitation_token)"
        )
        conn.execute(
            "CREATE INDEX IF NOT EXISTS idx_cpi_client "
            "ON client_portal_invitations(firm_code, client_code, status)"
        )

        # Item 2 (final cleanup): per-user UI filter preferences.
        conn.execute("""
            CREATE TABLE IF NOT EXISTS user_ui_preferences (
                user_email TEXT NOT NULL,
                firm_code TEXT NOT NULL,
                preference_key TEXT NOT NULL,
                preference_value TEXT,
                updated_at TEXT,
                PRIMARY KEY (user_email, firm_code, preference_key)
            )
        """)

        # Per-user rate limit + audit log (Phase 7).
        conn.execute("""
            CREATE TABLE IF NOT EXISTS client_portal_user_audit (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                portal_user_id INTEGER,
                firm_code TEXT,
                client_code TEXT,
                actor_email TEXT,
                action TEXT NOT NULL,
                detail TEXT,
                ip TEXT,
                user_agent TEXT,
                created_at TEXT DEFAULT (datetime('now'))
            )
        """)
        conn.execute(
            "CREATE INDEX IF NOT EXISTS idx_cpu_audit_user "
            "ON client_portal_user_audit(portal_user_id, created_at)"
        )
        conn.execute(
            "CREATE INDEX IF NOT EXISTS idx_portal_access_client "
            "ON client_portal_access(client_code, created_at)"
        )
        conn.commit()

        # Warn once if a legacy single-connection data/qbo_config.json exists
        # but no per-client rows have been seeded. We intentionally do NOT
        # auto-assign the legacy realm to an arbitrary client — the firm
        # must reconnect each client so tokens land in the right realm.
        try:
            legacy_cfg = ROOT_DIR / "data" / "qbo_config.json"
            has_rows = conn.execute(
                "SELECT 1 FROM qbo_connections LIMIT 1"
            ).fetchone() is not None
            if legacy_cfg.exists() and not has_rows:
                print(
                    "  [bootstrap] Legacy data/qbo_config.json detected but "
                    "qbo_connections is empty. Per-client reconnection required."
                )
        except Exception:
            pass

        # Seed a default admin account if no users exist
        count = list(conn.execute("SELECT COUNT(*) FROM dashboard_users").fetchone().values())[0]
        if count == 0:
            conn.execute(
                "INSERT INTO dashboard_users (username, password_hash, role, display_name, active, must_reset_password, created_at) VALUES (?,?,?,?,1,1,?)",
                ("sam", hash_password("admin123"), "owner", "Sam", utc_now_iso()),
            )
            conn.commit()
            print("  [bootstrap] Default user created: sam / admin123  <-- CHANGE THIS PASSWORD")

        # Login attempt tracking (brute-force protection)
        conn.execute("""
            CREATE TABLE IF NOT EXISTS login_attempts (
                id           INTEGER PRIMARY KEY AUTOINCREMENT,
                ip_address   TEXT NOT NULL,
                username     TEXT NOT NULL,
                attempted_at TEXT NOT NULL,
                success      INTEGER NOT NULL DEFAULT 0
            )
        """)
        conn.execute("""
            CREATE TABLE IF NOT EXISTS contact_leads (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                name TEXT NOT NULL,
                firm TEXT NOT NULL,
                email TEXT NOT NULL,
                phone TEXT,
                clients TEXT,
                message TEXT,
                source TEXT,
                diagnostic_data TEXT,
                created_at TEXT DEFAULT (datetime('now')),
                contacted INTEGER DEFAULT 0
            )
        """)
        _lead_cols = {row["name"] for row in conn.execute("PRAGMA table_info(contact_leads)").fetchall()}
        if "archived" not in _lead_cols:
            conn.execute("ALTER TABLE contact_leads ADD COLUMN archived INTEGER DEFAULT 0")
        if "notes" not in _lead_cols:
            conn.execute("ALTER TABLE contact_leads ADD COLUMN notes TEXT DEFAULT ''")
        conn.commit()

        # Client communications table
        _client_comms.ensure_comms_table(conn)

        # Audit tables (working papers, evidence, trial balance, engagements)
        _audit.ensure_audit_tables(conn)
        _audit.seed_chart_of_accounts(conn)

        # CAS tables (materiality, risk assessments)
        _cas.ensure_cas_tables(conn)

        # Reconciliation tables
        _ensure_recon_tables(conn)

        # Fixed assets table
        _fa.ensure_fixed_assets_table(conn)

        # AR invoices table
        _aging.ensure_ar_invoices_table(conn)

        # Performance indexes for document queries. Each index is
        # best-effort — a minimal bootstrap may be missing the underlying
        # table, and a CREATE INDEX on a nonexistent table should not
        # block startup.
        def _try_index(sql: str) -> None:
            try:
                conn.execute(sql)
            except sqlite3.OperationalError:
                pass
        _try_index('CREATE INDEX IF NOT EXISTS idx_documents_created_at ON documents(created_at DESC)')
        _try_index('CREATE INDEX IF NOT EXISTS idx_documents_status ON documents(review_status)')
        _try_index('CREATE INDEX IF NOT EXISTS idx_documents_client ON documents(client_code)')
        _try_index('CREATE INDEX IF NOT EXISTS idx_documents_vendor ON documents(vendor)')
        _try_index('CREATE INDEX IF NOT EXISTS idx_documents_updated_at ON documents(updated_at DESC)')
        _try_index('CREATE INDEX IF NOT EXISTS idx_posting_jobs_document_id ON posting_jobs(document_id)')
        _try_index('CREATE INDEX IF NOT EXISTS idx_document_assignments_document_id ON document_assignments(document_id)')
        conn.commit()

        # Backfill GL classification columns on invoice_lines (idempotent).
        # The source of truth for the table definition is
        # src/engines/line_item_engine.py::_ensure_invoice_lines_table; this
        # block exists so legacy DBs picked up by the dashboard get migrated
        # without needing a manual ALTER TABLE.
        try:
            il_cols = {row["name"] for row in conn.execute("PRAGMA table_info(invoice_lines)").fetchall()}
            for _il_col, _il_def in (
                ("gl_account",   "TEXT"),
                ("category",     "TEXT"),
                ("is_capital",   "INTEGER DEFAULT 0"),
                ("capital_notes","TEXT"),
            ):
                if _il_col not in il_cols:
                    conn.execute(f"ALTER TABLE invoice_lines ADD COLUMN {_il_col} {_il_def}")
            conn.commit()
        except sqlite3.OperationalError:
            # invoice_lines may not exist yet on a brand-new DB; the engine
            # will create it on first use.
            pass

        # Version-column migration for every versioned table. The module
        # ran this once at import against the original DB_PATH; call it
        # again inside bootstrap_schema so a restored-from-backup DB or
        # a test that monkeypatches DB_PATH also gets the columns.
        try:
            from src.db.optimistic import (  # noqa: PLC0415
                ensure_all_version_columns as _ensure_versions_here,
            )
            _ensure_versions_here(conn)
        except Exception:
            # Don't block startup on version-migration errors; the
            # versioned helpers have their own lazy fallbacks.
            pass

    # Gap 1-5 schemas: onboarding, review workflow, close wizard,
    # client status/messaging, impersonation audit, notification queue,
    # and feedback. Each helper is idempotent.
    try:
        _gap_routes.ensure_all_gap_schemas(DB_PATH)
    except Exception:
        logging.exception("ensure_all_gap_schemas failed")


# ---------------------------------------------------------------------------
# Auth helpers
# ---------------------------------------------------------------------------

def create_session(username: str) -> str:
    token = secrets.token_hex(32)
    expires = (utc_now() + timedelta(hours=SESSION_DURATION_HOURS)).isoformat()
    with open_db() as conn:
        conn.execute(
            "INSERT INTO dashboard_sessions (session_token, username, expires_at, created_at) VALUES (?,?,?,?)",
            (token, username, expires, utc_now_iso()),
        )
        conn.commit()
    return token


def delete_session(token: str) -> None:
    with open_db() as conn:
        conn.execute("DELETE FROM dashboard_sessions WHERE session_token = ?", (token,))
        conn.commit()


def create_pending_2fa(username: str) -> str:
    """Issue a short-lived token after password verification, before TOTP check."""
    token = secrets.token_hex(32)
    expires = (utc_now() + timedelta(minutes=5)).isoformat()
    with open_db() as conn:
        conn.execute(
            "INSERT INTO dashboard_pending_2fa (token, username, expires_at, created_at) VALUES (?,?,?,?)",
            (token, username, expires, utc_now_iso()),
        )
        conn.commit()
    return token


def consume_pending_2fa(token: str) -> str | None:
    """Return username for a valid pending-2FA token, or None. Does not delete."""
    if not token:
        return None
    with open_db() as conn:
        row = conn.execute(
            "SELECT username, expires_at FROM dashboard_pending_2fa WHERE token=?",
            (token,),
        ).fetchone()
    if not row:
        return None
    if row["expires_at"] < utc_now_iso():
        return None
    return row["username"]


def delete_pending_2fa(token: str) -> None:
    with open_db() as conn:
        conn.execute("DELETE FROM dashboard_pending_2fa WHERE token=?", (token,))
        conn.commit()


def verify_totp_code(secret: str, code: str) -> bool:
    if not pyotp or not secret or not code:
        return False
    try:
        return pyotp.TOTP(secret).verify(code.strip(), valid_window=1)
    except Exception:
        return False


def generate_totp_qr_base64(secret: str, username: str) -> str:
    """Return base64-encoded PNG for a provisioning URI."""
    if not pyotp or not qrcode:
        return ""
    uri = pyotp.TOTP(secret).provisioning_uri(name=username, issuer_name='OtoCPA')
    img = qrcode.make(uri)
    buf = io.BytesIO()
    img.save(buf, format='PNG')
    return base64.b64encode(buf.getvalue()).decode()


def get_pending_2fa_token_from_cookie(handler: BaseHTTPRequestHandler) -> str:
    cookie = handler.headers.get("Cookie", "")
    for part in cookie.split(";"):
        part = part.strip()
        if part.startswith("pending_2fa="):
            return part[len("pending_2fa="):]
    return ""


# ---------------------------------------------------------------------------
# Brute-force / rate-limit helpers
# ---------------------------------------------------------------------------

_RATE_LIMIT_WINDOW_MIN   = 15
_RATE_LIMIT_MAX_FAILURES = 5
_RATE_LIMIT_MSG = (
    "Trop de tentatives. Réessayez dans 15 minutes / "
    "Too many attempts. Try again in 15 minutes."
)


def _get_client_ip(handler: BaseHTTPRequestHandler) -> str:
    """Return the real client IP, honouring CF-Connecting-IP / X-Forwarded-For."""
    for hdr in ("CF-Connecting-IP", "X-Forwarded-For"):
        val = handler.headers.get(hdr, "").split(",")[0].strip()
        if val:
            return val
    return handler.client_address[0]


def _is_https(handler: BaseHTTPRequestHandler) -> bool:
    """Detect HTTPS via X-Forwarded-Proto (set by Cloudflare)."""
    return handler.headers.get("X-Forwarded-Proto", "").lower() == "https"


def _session_cookie_attrs(handler: BaseHTTPRequestHandler) -> str:
    """Return cookie security attributes appropriate for the current context."""
    if _is_https(handler):
        return "Secure; SameSite=Strict"
    return "SameSite=Lax"


# ---------------------------------------------------------------------------
# Contact form rate limiting (per-IP, 5 submissions / hour)
# ---------------------------------------------------------------------------

_contact_form_rate: dict[str, list[float]] = {}
_contact_form_rate_lock = threading.Lock()
_CONTACT_FORM_LIMIT = 5
_CONTACT_FORM_WINDOW_SEC = 3600


def _contact_form_rate_limited(ip: str) -> bool:
    """Return True if this IP has hit the contact form ≥5 times in the last hour."""
    now = time.time()
    cutoff = now - _CONTACT_FORM_WINDOW_SEC
    with _contact_form_rate_lock:
        timestamps = [t for t in _contact_form_rate.get(ip, []) if t > cutoff]
        if len(timestamps) >= _CONTACT_FORM_LIMIT:
            _contact_form_rate[ip] = timestamps
            return True
        timestamps.append(now)
        _contact_form_rate[ip] = timestamps
        return False


# ---------------------------------------------------------------------------
# CSRF Origin/Referer check for state-changing POST routes
# ---------------------------------------------------------------------------

# Webhooks and cross-origin entry points that authenticate by other means
# (signature header, API key, CORS allowlist, per-route rate limiting, or
# pre-auth routes where CSRF adds no protection).
_CSRF_EXEMPT_POSTS = frozenset({
    # Webhooks / machine-to-machine callers with their own auth
    "/stripe/webhook",       # Stripe-Signature verified in handler
    "/qbo/webhook",          # Intuit-Signature verified in handler
    "/ingest/openclaw",      # API key auth
    "/api/contact",          # CORS-bound public form + per-IP rate limit
    "/bank/callback",        # Plaid public-token exchange
    # Pre-auth entry points (no authenticated session to hijack)
    "/login",
    "/login/totp",
    "/logout",
    "/forgot",
    "/signup",
    "/signup/checkout",
    "/signup/success",
    # Public uploads (auth by client_code + rate limit)
    "/upload",
    # Language toggle (cookie-only)
    "/set_language",
})


def _csrf_path_exempt(path: str) -> bool:
    """Return True if this path is exempt from the CSRF Origin/Referer check."""
    if path in _CSRF_EXEMPT_POSTS:
        return True
    # Portal routes (/c/<token>/...) — the URL-embedded token is the auth.
    if path.startswith("/c/"):
        return True
    # Multi-user portal personal links (/cp/<user_token>/...) and
    # invitation acceptance (/invite/<token>) use the same URL-token
    # auth model as /c/*, so CSRF check doesn't add protection.
    if path.startswith("/cp/") or path.startswith("/invite/"):
        return True
    return False


def _csrf_check(handler: BaseHTTPRequestHandler) -> bool:
    """Return True if this POST's Origin/Referer matches our own host.

    State-changing POSTs must either carry an Origin header matching the
    server host (or an allowlisted otocpa domain), or — when Origin is
    absent — a Referer with a matching origin. Missing both = reject.
    """
    origin = handler.headers.get("Origin", "")
    referer = handler.headers.get("Referer", "")
    host = handler.headers.get("Host", "")

    allowed_origins = {
        f"https://{host}",
        f"http://{host}",
        "https://app.otocpa.com",
        "https://otocpa.com",
    }

    if origin:
        return origin in allowed_origins

    if referer:
        try:
            parsed = urllib.parse.urlparse(referer)
            ref_origin = f"{parsed.scheme}://{parsed.netloc}"
            return ref_origin in allowed_origins
        except Exception:
            return False

    # No Origin AND no Referer on a state-changing POST = reject.
    return False


# ---------------------------------------------------------------------------
# Dummy bcrypt hash — used to equalise login timing for unknown users so
# attackers cannot enumerate accounts by response-time differences.
# ---------------------------------------------------------------------------
try:
    _DUMMY_BCRYPT_HASH = bcrypt.hashpw(b"otocpa_timing_equalizer", bcrypt.gensalt()).decode()
except Exception:
    _DUMMY_BCRYPT_HASH = "$2b$12$" + "a" * 53


def record_login_attempt(ip: str, username: str, success: bool) -> None:
    """Record a login attempt in the login_attempts table."""
    with open_db() as conn:
        conn.execute(
            "INSERT INTO login_attempts (ip_address, username, attempted_at, success)"
            " VALUES (?,?,?,?)",
            (ip, username, utc_now_iso(), 1 if success else 0),
        )
        conn.commit()


def is_rate_limited(ip: str) -> bool:
    """Return True if this IP has ≥5 failed attempts in the last 15 minutes."""
    window_start = (
        utc_now() - timedelta(minutes=_RATE_LIMIT_WINDOW_MIN)
    ).replace(microsecond=0).isoformat()
    with open_db() as conn:
        row = conn.execute(
            "SELECT COUNT(*) FROM login_attempts"
            " WHERE ip_address=? AND success=0 AND attempted_at>=?",
            (ip, window_start),
        ).fetchone()
    return (list(row.values())[0] if row else 0) >= _RATE_LIMIT_MAX_FAILURES


def get_session_user(handler: BaseHTTPRequestHandler) -> dict[str, Any] | None:
    cookie = handler.headers.get("Cookie", "")
    token = None
    for part in cookie.split(";"):
        part = part.strip()
        if part.startswith("session_token="):
            token = part[len("session_token="):]
            break
    if not token:
        return None

    with open_db() as conn:
        session = conn.execute(
            "SELECT * FROM dashboard_sessions WHERE session_token = ?", (token,)
        ).fetchone()
        if not session:
            return None
        if session["expires_at"] < utc_now_iso():
            return None
        user = conn.execute(
            "SELECT * FROM dashboard_users WHERE username = ? AND active = 1",
            (session["username"],),
        ).fetchone()
        return dict(user) if user else None


def get_token_from_cookie(handler: BaseHTTPRequestHandler) -> str:
    cookie = handler.headers.get("Cookie", "")
    for part in cookie.split(";"):
        part = part.strip()
        if part.startswith("session_token="):
            return part[len("session_token="):]
    return ""


def get_all_active_users() -> list[dict[str, Any]]:
    with open_db() as conn:
        rows = conn.execute(
            "SELECT username, role, display_name FROM dashboard_users WHERE active = 1 ORDER BY username"
        ).fetchall()
    return [dict(r) for r in rows]


def get_available_usernames() -> list[str]:
    return [u["username"] for u in get_all_active_users()]


# ---------------------------------------------------------------------------
# Portfolio & user context
# ---------------------------------------------------------------------------

def get_portfolio_clients(username: str) -> list[str]:
    try:
        with open_db() as conn:
            rows = conn.execute(
                "SELECT client_code FROM user_portfolios WHERE username = ? ORDER BY client_code",
                (normalize_key(username),),
            ).fetchall()
        return [r["client_code"] for r in rows]
    except Exception:
        return []


def get_hybrid_assigned_clients(firm_code: str, email: str) -> list[str]:
    """Return clients where the user is primary or secondary employee.

    Hybrid assignment: an employee can be a client's primary (gets
    auto-routed new docs) or secondary (covers when primary is out).
    Either role makes the client visible in the employee's portfolio.
    """
    if not email or not firm_code:
        return []
    try:
        with open_db() as conn:
            rows = conn.execute(
                "SELECT DISTINCT client_code FROM clients "
                "WHERE firm_code = ? AND ("
                "  LOWER(primary_employee_email)   = LOWER(?) OR "
                "  LOWER(secondary_employee_email) = LOWER(?)"
                ") ORDER BY client_code",
                (firm_code, email, email),
            ).fetchall()
        return [r["client_code"] for r in rows]
    except sqlite3.OperationalError:
        # primary_employee_email column may be missing on bootstraps
        # that pre-date the hybrid migration.
        return []


def get_all_portfolios() -> dict[str, list[str]]:
    try:
        with open_db() as conn:
            rows = conn.execute(
                "SELECT username, client_code FROM user_portfolios ORDER BY username, client_code"
            ).fetchall()
        result: dict[str, list[str]] = {}
        for r in rows:
            result.setdefault(r["username"], []).append(r["client_code"])
        return result
    except Exception:
        return {}


def get_all_client_codes() -> list[str]:
    try:
        with open_db() as conn:
            rows = conn.execute(
                "SELECT DISTINCT client_code FROM documents WHERE client_code IS NOT NULL AND client_code != '' ORDER BY client_code"
            ).fetchall()
        return [r["client_code"] for r in rows]
    except Exception:
        return []


def assign_client_to_user(client_code: str, username: str, assigned_by: str) -> None:
    with open_db() as conn:
        conn.execute(
            """
            INSERT INTO user_portfolios (username, client_code, assigned_by, assigned_at)
            VALUES (?, ?, ?, ?)
            ON CONFLICT(username, client_code) DO UPDATE SET
                assigned_by = excluded.assigned_by, assigned_at = excluded.assigned_at
            """,
            (normalize_key(username), client_code, assigned_by, utc_now_iso()),
        )
        conn.commit()


def remove_client_from_user(client_code: str, username: str) -> None:
    with open_db() as conn:
        conn.execute(
            "DELETE FROM user_portfolios WHERE username = ? AND client_code = ?",
            (normalize_key(username), client_code),
        )
        conn.commit()


def move_client_to_user(client_code: str, from_user: str, to_user: str, assigned_by: str) -> None:
    remove_client_from_user(client_code, from_user)
    if normalize_key(to_user) != "unassigned":
        assign_client_to_user(client_code, to_user, assigned_by)


def build_user_context(user: dict[str, Any]) -> dict[str, Any]:
    role = normalize_key(user.get("role") or "employee")
    if role not in ROLE_CONFIG:
        role = "employee"
    base = ROLE_CONFIG[role]
    username = normalize_key(user.get("username") or "")
    # Hybrid assignment uses email as the assignee identifier (matches
    # review_workflow.assigned_to_email + clients.primary_employee_email).
    # Fall back to username when email is unset — many legacy installs
    # use the email as the username.
    email = normalize_text(user.get("email") or user.get("username") or "")
    firm_code = normalize_text(user.get("firm_code") or "OWNER") or "OWNER"

    if role == "employee":
        db_clients = get_portfolio_clients(username)
        # Hybrid: also include clients where this employee is the
        # primary or secondary, even if no portfolio row exists.
        # Union, preserve sort.
        hybrid_clients = get_hybrid_assigned_clients(firm_code, email)
        if hybrid_clients:
            merged = sorted({*db_clients, *hybrid_clients})
            db_clients = merged
    else:
        db_clients = []

    return {
        "username": username,
        "email": email,
        "display_name": normalize_text(user.get("display_name") or user.get("username")),
        "role": role,
        "firm_code": firm_code,
        "allowed_clients": db_clients,
        "can_view_all_clients": bool(base["can_view_all_clients"]),
        "can_view_all_assignments": bool(base["can_view_all_assignments"]),
        "can_assign": bool(base["can_assign"]),
        "can_post": bool(base["can_post"]),
        "can_manage_team": bool(base["can_manage_team"]),
        "can_post_qbo": bool(base.get("can_post_qbo", False)),
        "can_manage_journal_entries": bool(base.get("can_manage_journal_entries", False)),
        "can_export": bool(base.get("can_export", False)),
        "can_manage_users": bool(base.get("can_manage_users", False)),
    }


# ---------------------------------------------------------------------------
# Permission helpers — multi-tenant scoping and capability gating
# ---------------------------------------------------------------------------

def _require_client_in_firm(client_code: str | None, ctx: dict[str, Any]) -> bool:
    """Return True when ctx is allowed to act on client_code.

    Owner can access any client. Other roles must share a firm_code with the
    client. Unknown clients always fail.
    """
    if not client_code:
        return False
    if ctx.get("role") == "owner":
        return True
    user_firm = ctx.get("firm_code")
    if not user_firm:
        return False
    with open_db() as conn:
        row = conn.execute(
            "SELECT firm_code FROM clients WHERE client_code=?",
            (client_code,),
        ).fetchone()
    return bool(row and row.get("firm_code") == user_firm)


def _require_document_in_firm(document_id: str | None, ctx: dict[str, Any]) -> bool:
    """Return True when ctx's firm owns the client that owns the document."""
    if not document_id:
        return False
    if ctx.get("role") == "owner":
        return True
    user_firm = ctx.get("firm_code")
    if not user_firm:
        return False
    with open_db() as conn:
        row = conn.execute(
            "SELECT c.firm_code AS firm_code FROM documents d "
            "JOIN clients c ON c.client_code = d.client_code "
            "WHERE d.document_id=?",
            (document_id,),
        ).fetchone()
    return bool(row and row.get("firm_code") == user_firm)


def _can_do(ctx: dict[str, Any], capability: str) -> bool:
    """Check a ctx.can_<capability> flag from ROLE_CONFIG."""
    return bool(ctx.get(f"can_{capability}", False))


def _forbid(handler, message: str = "Forbidden") -> None:
    """Send a 403 JSON response; safe to embed short messages (no quotes in msg)."""
    handler.send_response(403)
    handler.send_header("Content-Type", "application/json")
    handler.end_headers()
    handler.wfile.write(json.dumps({"error": message}).encode("utf-8"))


def validate_role(role: str | None) -> str:
    """Return role lowercased if valid; raise ValueError otherwise."""
    normalized = normalize_key(role or "")
    if normalized not in VALID_ROLES:
        raise ValueError(f"invalid role: {role!r}")
    return normalized


def can_assign_role(actor_role: str | None, target_role: str | None) -> tuple[bool, str]:
    """Guard for /users/add and role-edit paths.

    Only owners may create or promote to owner or firm_admin. Anyone with
    manage_users (owner or firm_admin) may assign the manager / employee
    roles. Returns (allowed, reason). The reason is empty when allowed.
    """
    actor = (actor_role or "").strip().lower()
    target = (target_role or "").strip().lower()
    if actor == "owner":
        return True, ""
    if target == "owner":
        return False, "firm_admin cannot create owner accounts"
    if target == "firm_admin":
        return False, "firm_admin cannot create firm_admin accounts"
    return True, ""


# ---------------------------------------------------------------------------
# Public upload rate limiting (per client_code, per IP)
# ---------------------------------------------------------------------------

_PUBLIC_UPLOAD_MAX_PER_MIN = 20
_public_upload_log: dict[tuple[str, str], list[float]] = {}
_public_upload_lock = threading.Lock()

# Bulk upload safeguards so a single request can't starve the queue or
# blow past the HTTP body size we're willing to buffer.
MAX_UPLOAD_FILES = 50
MAX_UPLOAD_BYTES = 100 * 1024 * 1024  # 100 MB per request


def _batch_limit_error(files: list[tuple[str, bytes]]) -> str | None:
    """Return an error message if the batch violates size/count limits."""
    if len(files) > MAX_UPLOAD_FILES:
        return f"Too many files in one upload: {len(files)} (max {MAX_UPLOAD_FILES})"
    total = sum(len(b or b"") for _, b in files)
    if total > MAX_UPLOAD_BYTES:
        mb = total // (1024 * 1024)
        return f"Upload too large: {mb} MB (max {MAX_UPLOAD_BYTES // (1024 * 1024)} MB)"
    return None


def _wants_async_upload(handler) -> bool:
    """True when the client opted into the async JSON response.

    Browsers that still submit the HTML form (no JS) fall back to the
    classic redirect-with-flash flow for backwards compatibility.
    """
    return handler.headers.get("X-Async-Upload", "").strip() == "1"


def _public_upload_allowed(client_code: str, ip: str) -> bool:
    """Return False when this (client_code, ip) exceeds 20 uploads/minute."""
    import time as _time
    now = _time.time()
    cutoff = now - 60.0
    key = (client_code or "", ip or "")
    with _public_upload_lock:
        bucket = _public_upload_log.get(key, [])
        bucket = [ts for ts in bucket if ts >= cutoff]
        if len(bucket) >= _PUBLIC_UPLOAD_MAX_PER_MIN:
            _public_upload_log[key] = bucket
            return False
        bucket.append(now)
        _public_upload_log[key] = bucket
    return True


# ---------------------------------------------------------------------------
# Sprint 4: Client portal — tokens, access log, rate limits
# ---------------------------------------------------------------------------

_PORTAL_PER_TOKEN_MAX_PER_MIN = 100
_PORTAL_PER_IP_MAX_PER_MIN = 20
_portal_token_log: dict[str, list[float]] = {}
_portal_ip_log: dict[str, list[float]] = {}
_portal_rate_lock = threading.Lock()


def generate_portal_token() -> str:
    """Return a fresh URL-safe portal token (~43 chars)."""
    return secrets.token_urlsafe(32)


def resolve_portal_token(token: str | None) -> sqlite3.Row | None:
    """Return the client row for a valid portal token, else None.

    Rejects empty/short tokens early. Only resolves active clients.
    """
    if not token or len(token) < 30:
        return None
    with open_db() as conn:
        return conn.execute(
            "SELECT client_code, firm_code, client_name, portal_token, "
            "portal_token_created_at, portal_token_rotated_count "
            "FROM clients WHERE portal_token=? AND active=1",
            (token,),
        ).fetchone()


def log_portal_access(
    client_code: str,
    firm_code: str,
    token: str,
    request_handler: BaseHTTPRequestHandler,
    action: str,
) -> None:
    """Append a row to client_portal_access for audit trail."""
    try:
        ip = ""
        try:
            ip = _get_client_ip(request_handler)
        except Exception:
            ip = getattr(request_handler, "client_address", ("",))[0] or ""
        ua = (request_handler.headers.get("User-Agent", "") or "")[:200]
        with open_db() as conn:
            conn.execute(
                "INSERT INTO client_portal_access "
                "(client_code, firm_code, portal_token_prefix, ip, user_agent, action) "
                "VALUES (?,?,?,?,?,?)",
                (client_code, firm_code, (token or "")[:8], ip, ua, action),
            )
            conn.commit()
    except Exception:
        # Audit logging must never break the request.
        pass


def rotate_portal_token(client_code: str, ctx: dict[str, Any]) -> str | None:
    """Invalidate the old portal token and issue a new one. Firm-scoped.

    Returns the new token string, or None when the caller cannot act on the
    client (cross-firm attempt or unknown client).
    """
    if not _require_client_in_firm(client_code, ctx):
        return None
    new_token = generate_portal_token()
    with open_db() as conn:
        conn.execute(
            "UPDATE clients SET portal_token=?, portal_token_created_at=datetime('now'), "
            "portal_token_rotated_count=COALESCE(portal_token_rotated_count,0)+1 "
            "WHERE client_code=?",
            (new_token, client_code),
        )
        conn.commit()
    return new_token


def _portal_rate_allowed(token: str, ip: str) -> bool:
    """Per-token (100/min) and per-IP fallback (20/min) in-memory limiter."""
    import time as _time
    now = _time.time()
    cutoff = now - 60.0
    with _portal_rate_lock:
        if token:
            bucket = [ts for ts in _portal_token_log.get(token, []) if ts >= cutoff]
            if len(bucket) >= _PORTAL_PER_TOKEN_MAX_PER_MIN:
                _portal_token_log[token] = bucket
                return False
            bucket.append(now)
            _portal_token_log[token] = bucket
        else:
            bucket = [ts for ts in _portal_ip_log.get(ip or "", []) if ts >= cutoff]
            if len(bucket) >= _PORTAL_PER_IP_MAX_PER_MIN:
                _portal_ip_log[ip or ""] = bucket
                return False
            bucket.append(now)
            _portal_ip_log[ip or ""] = bucket
    return True


def insert_portal_system_message(
    client_code: str, firm_code: str, body: str,
    related_document_id: str | None = None,
) -> None:
    """Append a system-direction message to the client portal thread.

    Stub-only for Sprint 4: no email/WhatsApp fanout. The client sees it the
    next time they open /c/{token}/messages.
    """
    try:
        with open_db() as conn:
            conn.execute(
                "INSERT INTO client_messages "
                "(client_code, firm_code, direction, sender_name, sender_type, body, related_document_id) "
                "VALUES (?,?,?,?,?,?,?)",
                (client_code, firm_code or "OWNER", "system", "OtoCPA", "system",
                 body, related_document_id),
            )
            conn.commit()
    except Exception:
        # System messages must never break the caller flow.
        pass


def portal_url_for(base_url: str, client_code: str) -> str | None:
    """Return the /c/<token> URL for a client, or None if no token/client."""
    with open_db() as conn:
        row = conn.execute(
            "SELECT portal_token FROM clients WHERE client_code=? AND active=1",
            (client_code,),
        ).fetchone()
    if not row or not row["portal_token"]:
        return None
    base = (base_url or "").rstrip("/")
    return f"{base}/c/{row['portal_token']}"


# ---------------------------------------------------------------------------
# Badge helpers
# ---------------------------------------------------------------------------

def review_status_badge(status: str) -> str:
    s = normalize_text(status)
    css = "badge badge-muted"
    if s in {"Ready", "Ready to Post"}:         css = "badge badge-ready"
    elif s in {"NeedsReview", "Needs Review"}:  css = "badge badge-needsreview"
    elif s in {"On Hold", "Hold"}:              css = "badge badge-hold"
    elif s == "Ignored":                        css = "badge badge-ignored"
    elif s == "Posted":                         css = "badge badge-posted"
    elif s == "Exception":                      css = "badge badge-exception"
    return f'<span class="{css}">{esc(s or "Unknown")}</span>'


def posting_status_badge(status: str) -> str:
    s = normalize_text(status)
    css = "badge badge-muted"
    if s == "posted":         css = "badge badge-posted"
    elif s == "ready_to_post": css = "badge badge-ready"
    elif s == "post_failed":  css = "badge badge-exception"
    elif s == "draft":        css = "badge badge-hold"
    return f'<span class="{css}">{esc(s or "none")}</span>'


def approval_state_badge(status: str) -> str:
    s = normalize_text(status)
    css = "badge badge-muted"
    if s == "approved_for_posting":    css = "badge badge-ready"
    elif s == "pending_human_approval": css = "badge badge-needsreview"
    elif s == "rejected":               css = "badge badge-exception"
    return f'<span class="{css}">{esc(s or "none")}</span>'


def bool_badge(flag: bool, true_text: str = "Yes", false_text: str = "No") -> str:
    if flag:
        return f'<span class="badge badge-ready">{esc(true_text)}</span>'
    return f'<span class="badge badge-muted">{esc(false_text)}</span>'


def queue_fraud_badges(row: dict) -> str:
    """Return inline HTML badges for fraud/substance flags shown in the queue table."""
    badges: list[str] = []

    # --- Bank statement badge ---
    _cat = normalize_text(row.get("category", ""))
    _dtype = normalize_text(row.get("doc_type", ""))
    if _cat == "bank_statement" or _dtype == "bank_statement":
        badges.append(
            '<span class="badge" style="background:#dbeafe;color:#1e40af;">'
            'Relevé bancaire / Bank Statement</span>')
        return "".join(badges)  # No fraud badges for bank statements

    # --- Fraud flags ---
    raw_ff = row.get("fraud_flags") or ""
    if raw_ff and raw_ff not in ("{}", "[]", "null"):
        try:
            flags = json.loads(raw_ff) if isinstance(raw_ff, str) else raw_ff
        except Exception:
            flags = []
        if isinstance(flags, list) and flags:
            # flags can be list of dicts or list of plain strings
            severities: list[str] = []
            rules: list[str] = []
            for f in flags:
                if isinstance(f, dict):
                    severities.append(str(f.get("severity", "")).upper())
                    rules.append(str(f.get("rule", "")))
                elif isinstance(f, str):
                    rules.append(f)
            tooltip = esc(", ".join(r for r in rules if r))
            sev_set = set(severities)
            if "CRITICAL" in sev_set:
                badges.append(
                    f'<span class="badge" style="background:#fee2e2;color:#991b1b;" '
                    f'title="{tooltip}">\U0001f6a8 Fraude</span>')
            elif "HIGH" in sev_set:
                badges.append(
                    f'<span class="badge" style="background:#ffedd5;color:#9a3412;" '
                    f'title="{tooltip}">\u26a0\ufe0f Risque</span>')
            elif sev_set:
                badges.append(
                    f'<span class="badge" style="background:#fef9c3;color:#854d0e;" '
                    f'title="{tooltip}">\u26a1 Attention</span>')
            elif rules:
                # Plain string flags with no severity — show generic fraud badge
                badges.append(
                    f'<span class="badge" style="background:#fee2e2;color:#991b1b;" '
                    f'title="{tooltip}">\U0001f6a8 Fraude / Fraud</span>')

    # --- Substance flags (block_auto_approval) ---
    raw_sf = row.get("substance_flags") or ""
    if raw_sf and raw_sf not in ("{}", "[]", "null"):
        try:
            sf = json.loads(raw_sf) if isinstance(raw_sf, str) else raw_sf
        except Exception:
            sf = {}
        if isinstance(sf, dict) and sf.get("block_auto_approval"):
            badges.append(
                '<span class="badge" style="background:#dbeafe;color:#1e40af;">Substance</span>')

    # --- Uncertainty badge ---
    review_status = normalize_text(row.get("review_status", ""))
    confidence = row.get("confidence")
    if review_status in ("NeedsReview", "Needs Review") and not badges:
        try:
            conf_val = float(confidence) if confidence is not None else 1.0
        except (TypeError, ValueError):
            conf_val = 1.0
        if conf_val < 0.5:
            badges.append(
                '<span class="badge" style="background:#fef3c7;color:#92400e;">Incertain / Uncertain</span>')

    return " ".join(badges)


# ---------------------------------------------------------------------------
# Business logic
# ---------------------------------------------------------------------------

def compute_blocking_issues(row: sqlite3.Row) -> list[str]:
    required = ["vendor", "amount", "document_date", "gl_account", "tax_code", "category", "client_code"]
    return [f for f in required if row[f] is None or str(row[f]).strip() == ""]


def get_accounting_status(row: sqlite3.Row) -> str:
    review_status  = normalize_text(row["review_status"])
    posting_status = normalize_text(row["posting_status"])
    approval_state = normalize_text(row["approval_state"])
    external_id    = normalize_text(row["external_id"])
    hold_reason    = normalize_text(row["manual_hold_reason"])

    if review_status == "Ignored":                                              return "Ignored"
    if external_id or posting_status == "posted":                               return "Posted"
    if hold_reason or approval_state == "pending_human_approval":               return "On Hold"
    if posting_status == "ready_to_post" or approval_state == "approved_for_posting": return "Ready to Post"
    if review_status in {"NeedsReview", "Exception"}:                          return "Needs Review"
    if review_status == "Ready":                                                return "Ready"
    return review_status or "New"


def get_plain_review_reason(row: sqlite3.Row) -> str:
    raw = safe_json_loads(row["raw_result"])
    duplicate    = raw.get("duplicate_result", {})
    vendor_mem   = raw.get("vendor_memory_enrichment", {})
    exc_router   = raw.get("exception_router_result", {})
    auto_app     = raw.get("auto_approval_result", {})

    blocking = compute_blocking_issues(row)
    if blocking:
        return f"Missing required fields: {', '.join(blocking)}"
    if normalize_text(row["manual_hold_reason"]):
        return normalize_text(row["manual_hold_reason"])
    if isinstance(duplicate, dict) and normalize_key(duplicate.get("risk_level")) in {"medium", "high"}:
        return "Possible duplicate"
    if isinstance(exc_router, dict):
        reasons = exc_router.get("reasons", [])
        if "missing_vendor" in reasons:   return "Missing vendor"
        if "missing_amount" in reasons:   return "Missing amount"
        if "duplicate_medium_risk" in reasons: return "Possible duplicate"
    if isinstance(vendor_mem, dict) and vendor_mem.get("flagged_for_review"):
        rr = vendor_mem.get("review_reasons", [])
        if rr:
            first = normalize_text(rr[0])
            return "Unusual amount, review needed" if ("amount_above" in first or "amount_below" in first) else first.replace("_", " ")
    if isinstance(auto_app, dict) and normalize_text(auto_app.get("reason")) == "approve_but_hold":
        return "Approved by system but held for review"
    reviewer = normalize_text(row["posting_reviewer"])
    if reviewer == "ExceptionRouter":
        return "Waiting accounting review"
    if normalize_text(row["approval_state"]) == "pending_human_approval":
        return "Waiting approval"
    return "Review needed"


def get_next_action(row: sqlite3.Row, ctx: dict[str, Any]) -> str:
    status = get_accounting_status(row)
    assigned = normalize_text(row["assigned_to"])
    is_mine = normalize_key(assigned) == normalize_key(ctx["username"])

    if status == "Posted":                                        return "None"
    if not assigned:                                              return "Claim"
    if not is_mine and not ctx["can_assign"]:                     return "View"
    if status == "Needs Review":                                  return "Review"
    if status == "On Hold":                                       return "Resolve Hold"
    if status == "Ready to Post":   return "Post" if ctx["can_post"] else "Approve"
    if status == "Ready":                                         return "Approve"
    return "Review"


def get_status_counts(ctx: dict[str, Any]) -> dict[str, int]:
    where_sql, params = _build_documents_where(
        ctx=ctx, include_ignored=True,
    )
    if where_sql == "WHERE 1=0":
        return {"Needs Review": 0, "On Hold": 0, "Ready to Post": 0, "Posted": 0, "Ignored": 0}
    sql = f"""
        SELECT ({_ACCOUNTING_STATUS_CASE_SQL}) AS acct_status, COUNT(*) AS cnt
        {_DOCUMENTS_FROM_SQL}
        {where_sql}
        GROUP BY acct_status
    """
    counts = {"Needs Review": 0, "On Hold": 0, "Ready to Post": 0, "Posted": 0, "Ignored": 0}
    with open_db() as conn:
        for row in conn.execute(sql, tuple(params)).fetchall():
            s = row['acct_status']
            if s in counts:
                counts[s] = row['cnt']
    return counts


# ---------------------------------------------------------------------------
# DB queries
# ---------------------------------------------------------------------------

_ACCOUNTING_STATUS_CASE_SQL = """
    CASE
        WHEN TRIM(COALESCE(d.review_status, '')) = 'Ignored' THEN 'Ignored'
        WHEN TRIM(COALESCE(pj.external_id, '')) != '' OR TRIM(COALESCE(pj.posting_status, '')) = 'posted' THEN 'Posted'
        WHEN TRIM(COALESCE(d.manual_hold_reason, '')) != '' OR TRIM(COALESCE(pj.approval_state, '')) = 'pending_human_approval' THEN 'On Hold'
        WHEN TRIM(COALESCE(pj.posting_status, '')) = 'ready_to_post' OR TRIM(COALESCE(pj.approval_state, '')) = 'approved_for_posting' THEN 'Ready to Post'
        WHEN TRIM(COALESCE(d.review_status, '')) IN ('NeedsReview', 'Exception') THEN 'Needs Review'
        WHEN TRIM(COALESCE(d.review_status, '')) = 'Ready' THEN 'Ready'
        ELSE COALESCE(NULLIF(TRIM(COALESCE(d.review_status, '')), ''), 'New')
    END
"""


def _build_documents_where(
    *,
    ctx: dict[str, Any],
    status: str = "",
    q: str = "",
    include_ignored: bool = False,
    only_my_queue: bool = False,
    only_unassigned: bool = False,
    uploader_emails: list[str] | None = None,
) -> tuple[str, list[Any]]:
    """Build the shared WHERE clause for document queries."""
    where: list[str] = []
    params: list[Any] = []
    # Uploader filter (polish Item 1): caller supplies emails + the
    # magic '__anonymous__' sentinel for NULL/blank uploads.
    if uploader_emails:
        from src.integrations.queue_filters import (
            build_uploader_where_fragment as _uq_frag,
        )
        frag, frag_params = _uq_frag(uploader_emails)
        if frag:
            where.append(frag)
            params.extend(frag_params)

    if not include_ignored:
        where.append("(d.review_status IS NULL OR d.review_status != 'Ignored')")

    if q:
        like = f"%{q}%"
        where.append("(d.file_name LIKE ? OR d.vendor LIKE ? OR d.client_code LIKE ? OR d.gl_account LIKE ? OR d.category LIKE ?)")
        params.extend([like] * 5)

    if not ctx["can_view_all_clients"]:
        allowed = ctx.get("allowed_clients", [])
        # Hybrid: even when the employee has zero portfolio clients,
        # an explicit document-level override (review_workflow.
        # assigned_to_email = me) must still surface the document.
        # We OR a workflow-override clause with the in-portfolio clause.
        ctx_email = (ctx.get("email") or "").strip()
        client_clause: list[str] = []
        if allowed:
            placeholders = ",".join("?" for _ in allowed)
            client_clause.append(
                f"COALESCE(d.client_code, '') IN ({placeholders})"
            )
            params.extend(allowed)
        if ctx_email:
            client_clause.append(
                "EXISTS (SELECT 1 FROM review_workflow rw "
                " WHERE rw.entity_type='document' "
                "   AND rw.entity_id = d.document_id "
                "   AND LOWER(rw.assigned_to_email) = LOWER(?))"
            )
            params.append(ctx_email)
        if not client_clause:
            return "WHERE 1=0", []
        where.append("(" + " OR ".join(client_clause) + ")")

    # Firm-scoped isolation: non-owner roles only see documents belonging to
    # clients in their firm. Owner (and legacy OWNER firm) sees everything.
    if ctx.get("role") != "owner" and ctx.get("firm_code") and ctx["firm_code"] != "OWNER":
        where.append(
            "d.client_code IN (SELECT client_code FROM clients WHERE firm_code = ?)"
        )
        params.append(ctx["firm_code"])

    if only_my_queue:
        where.append("COALESCE(da.assigned_to, d.assigned_to, '') = ?")
        params.append(ctx["username"])
    elif only_unassigned:
        where.append("COALESCE(da.assigned_to, d.assigned_to, '') = ''")
    elif not ctx["can_view_all_assignments"]:
        # Hybrid assignment visibility for employees. Three layers, in
        # priority order; a document shows up if ANY layer matches:
        #
        #   1. Explicit document-level override:
        #        review_workflow.assigned_to_email == me
        #
        #   2. No doc-level override AND I'm primary/secondary on the
        #      client (hybrid client-level routing).
        #
        #   3. Legacy fallback (only when the client has NEITHER a
        #      primary NOR a secondary configured — i.e. the firm
        #      hasn't migrated this client to the hybrid model):
        #        - the doc has no override AND
        #        - it is unassigned at the document_assignments layer
        #          OR assigned to me by username.
        #
        # The legacy fallback prevents regression for firms that
        # haven't set up primary employees yet, while making sure
        # hybrid-configured clients route strictly through layers 1+2
        # (so employees don't see colleagues' explicitly assigned docs).
        ctx_email_lc = (ctx.get("email") or "").strip().lower()
        no_override_sql = (
            "NOT EXISTS (SELECT 1 FROM review_workflow rw_no "
            " WHERE rw_no.entity_type='document' "
            "   AND rw_no.entity_id = d.document_id "
            "   AND COALESCE(rw_no.assigned_to_email,'') <> '')"
        )
        no_hybrid_sql = (
            "NOT EXISTS (SELECT 1 FROM clients c_nohyb "
            " WHERE c_nohyb.client_code = d.client_code "
            "   AND (COALESCE(c_nohyb.primary_employee_email,'') <> '' "
            "     OR COALESCE(c_nohyb.secondary_employee_email,'') <> ''))"
        )
        clauses: list[str] = []
        if ctx_email_lc:
            clauses.append(
                "EXISTS (SELECT 1 FROM review_workflow rw "
                " WHERE rw.entity_type='document' "
                "   AND rw.entity_id = d.document_id "
                "   AND LOWER(rw.assigned_to_email) = ?)"
            )
            params.append(ctx_email_lc)
            clauses.append(
                "(" + no_override_sql + " AND "
                "EXISTS (SELECT 1 FROM clients c_hyb "
                " WHERE c_hyb.client_code = d.client_code "
                "   AND ("
                "     LOWER(c_hyb.primary_employee_email)   = ? "
                "  OR LOWER(c_hyb.secondary_employee_email) = ? "
                "   )))"
            )
            params.extend([ctx_email_lc, ctx_email_lc])
        # Legacy fallback (only when client has no hybrid configured).
        clauses.append(
            "(" + no_override_sql + " AND " + no_hybrid_sql + " AND ("
            "  COALESCE(da.assigned_to, d.assigned_to, '') = '' "
            "  OR COALESCE(da.assigned_to, d.assigned_to, '') = ?"
            "))"
        )
        params.append(ctx["username"])
        where.append("(" + " OR ".join(clauses) + ")")

    wanted = normalize_key(status)
    if wanted:
        where.append(f"({_ACCOUNTING_STATUS_CASE_SQL}) = ?")
        params.append(status)

    where_sql = ("WHERE " + " AND ".join(where)) if where else ""
    return where_sql, params


_DOCUMENTS_FROM_SQL = """
    FROM documents d
    LEFT JOIN document_assignments da ON da.document_id = d.document_id
    LEFT JOIN posting_jobs pj ON pj.document_id = d.document_id
        AND pj.rowid = (
            SELECT pj2.rowid FROM posting_jobs pj2
            WHERE pj2.document_id = d.document_id
            ORDER BY COALESCE(pj2.updated_at, pj2.created_at) DESC, pj2.rowid DESC LIMIT 1
        )
"""


def count_documents(
    *,
    ctx: dict[str, Any],
    status: str = "",
    q: str = "",
    include_ignored: bool = False,
    only_my_queue: bool = False,
    only_unassigned: bool = False,
    uploader_emails: list[str] | None = None,
) -> int:
    where_sql, params = _build_documents_where(
        ctx=ctx, status=status, q=q, include_ignored=include_ignored,
        only_my_queue=only_my_queue, only_unassigned=only_unassigned,
        uploader_emails=uploader_emails,
    )
    if where_sql == "WHERE 1=0":
        return 0
    sql = f"SELECT COUNT(*) AS cnt {_DOCUMENTS_FROM_SQL} {where_sql}"
    with open_db() as conn:
        row = conn.execute(sql, tuple(params)).fetchone()
        return row['cnt'] if row else 0


def get_documents(
    *,
    ctx: dict[str, Any],
    status: str = "",
    q: str = "",
    include_ignored: bool = False,
    only_my_queue: bool = False,
    only_unassigned: bool = False,
    limit: int = 500,
    per_page: int | None = None,
    offset: int = 0,
    uploader_emails: list[str] | None = None,
) -> list[dict]:
    where_sql, params = _build_documents_where(
        ctx=ctx, status=status, q=q, include_ignored=include_ignored,
        only_my_queue=only_my_queue, only_unassigned=only_unassigned,
        uploader_emails=uploader_emails,
    )
    if where_sql == "WHERE 1=0":
        return []

    effective_limit = per_page if per_page is not None else limit
    sql = f"""
        SELECT
            d.document_id, d.file_name, d.file_path, d.client_code, d.vendor,
            d.doc_type, d.amount, d.document_date, d.gl_account, d.tax_code,
            d.category, d.review_status, d.confidence, d.raw_result,
            d.created_at, d.updated_at,
            d.assigned_to AS document_assigned_to,
            d.manual_hold_reason, d.manual_hold_by, d.manual_hold_at,
            d.fraud_flags, d.substance_flags,
            d.uploaded_by_portal_user_id, d.uploader_name, d.uploader_email,
            COALESCE(d.uploaded_via_channel, 'portal') AS uploaded_via_channel,
            COALESCE(da.assigned_to, d.assigned_to, '') AS assigned_to,
            da.assigned_by, da.assigned_at, da.note AS assignment_note,
            pj.posting_id, pj.posting_status, pj.approval_state,
            pj.reviewer AS posting_reviewer, pj.external_id,
            pj.payload_json AS posting_payload_json,
            pj.error_text AS posting_error_text
        {_DOCUMENTS_FROM_SQL}
        {where_sql}
        ORDER BY COALESCE(d.updated_at, d.created_at) DESC, d.file_name ASC
        LIMIT ? OFFSET ?
    """
    params.append(effective_limit)
    params.append(offset)

    with open_db() as conn:
        return [dict(r) for r in conn.execute(sql, tuple(params)).fetchall()]


def _infer_entry_kind(doc_row) -> str:
    """FIX 2: Infer entry_kind from doc_type and amount."""
    doc_type = normalize_text(doc_row["doc_type"]).lower() if doc_row.get("doc_type") else ""
    amount = None
    try:
        amount = float(doc_row["amount"]) if doc_row.get("amount") is not None else None
    except (TypeError, ValueError):
        pass
    credit_doc_types = {"credit_note", "refund", "chargeback", "reversal"}
    if doc_type in credit_doc_types or (amount is not None and amount < 0):
        return "credit"
    return "expense"


def get_document(document_id: str) -> dict | None:
    with open_db() as conn:
        row = conn.execute(
            """
            SELECT
                d.document_id, d.file_name, d.file_path, d.client_code, d.vendor,
                d.doc_type, d.amount, d.document_date, d.gl_account, d.tax_code,
                d.category, d.review_status, d.confidence, d.raw_result,
                d.created_at, d.updated_at,
                d.assigned_to AS document_assigned_to,
                d.manual_hold_reason, d.manual_hold_by, d.manual_hold_at,
                COALESCE(d.hallucination_suspected, 0) AS hallucination_suspected,
                d.raw_ocr_text,
                COALESCE(d.correction_count, 0) AS correction_count,
                d.fraud_flags,
                COALESCE(d.has_line_items, 0) AS has_line_items,
                COALESCE(d.lines_reconciled, 0) AS lines_reconciled,
                d.line_total_sum,
                d.invoice_total_gap,
                COALESCE(d.deposit_allocated, 0) AS deposit_allocated,
                COALESCE(da.assigned_to, d.assigned_to, '') AS assigned_to,
                da.assigned_by, da.assigned_at, da.note AS assignment_note,
                d.uploader_name, d.uploader_email,
                COALESCE(d.uploaded_via_channel, 'portal') AS uploaded_via_channel,
                pj.posting_id, pj.posting_status, pj.approval_state,
                pj.reviewer AS posting_reviewer, pj.external_id,
                pj.payload_json AS posting_payload_json,
                pj.error_text AS posting_error_text
            FROM documents d
            LEFT JOIN document_assignments da ON da.document_id = d.document_id
            LEFT JOIN posting_jobs pj ON pj.document_id = d.document_id
                AND pj.rowid = (
                    SELECT pj2.rowid FROM posting_jobs pj2
                    WHERE pj2.document_id = d.document_id
                    ORDER BY COALESCE(pj2.updated_at, pj2.created_at) DESC, pj2.rowid DESC LIMIT 1
                )
            WHERE d.document_id = ?
            """,
            (document_id,),
        ).fetchone()
        return dict(row) if row else None


def update_document_fields(document_id: str, fields: dict[str, Any]) -> None:
    allowed = {"vendor","client_code","doc_type","amount","document_date","gl_account",
               "tax_code","category","review_status","manual_hold_reason","manual_hold_by","manual_hold_at"}
    updates, params = [], []
    for k, v in fields.items():
        if k not in allowed:
            continue
        params.append(normalize_amount_input(v) if k == "amount" else normalize_optional_text(v))
        updates.append(f"{k} = ?")
    if not updates:
        return
    updates.append("updated_at = ?")
    params.extend([utc_now_iso(), document_id])
    with open_db() as conn:
        conn.execute(f"UPDATE documents SET {', '.join(updates)} WHERE document_id = ?", tuple(params))
        # Bump the optimistic-concurrency version in lockstep so clients
        # reading via the versioned path see a fresh version number.
        try:
            conn.execute(
                "UPDATE documents SET version = COALESCE(version, 1) + 1 "
                "WHERE document_id = ?", (document_id,),
            )
        except sqlite3.OperationalError:
            pass
        conn.commit()


def update_document_fields_versioned(
    document_id: str,
    fields: dict[str, Any],
    body: dict[str, Any] | None,
    *, require_version: bool = False,
):
    """Versioned variant of update_document_fields.

    Returns a ``VersionedUpdateResult`` so callers can send 200/409 based
    on whether the caller's ``version`` in the request body matches the
    current row version. Wraps the same ``allowed`` filter /
    normalisation as the legacy path.
    """
    from src.db.version_handlers import versioned_update_from_request
    allowed = {"vendor","client_code","doc_type","amount","document_date","gl_account",
               "tax_code","category","review_status","manual_hold_reason","manual_hold_by","manual_hold_at"}
    normed: dict[str, Any] = {}
    for k, v in (fields or {}).items():
        if k not in allowed:
            continue
        normed[k] = normalize_amount_input(v) if k == "amount" else normalize_optional_text(v)
    if not normed:
        # Nothing to write — mirror legacy no-op but still read current
        # version so the caller can echo it back.
        from src.db.version_handlers import VersionedUpdateResult, _read_current_version
        with open_db() as conn:
            cur = _read_current_version(conn, "documents", "document_id", document_id)
        return VersionedUpdateResult(status=200, new_version=cur)
    normed["updated_at"] = utc_now_iso()
    with open_db() as conn:
        return versioned_update_from_request(
            conn, table="documents", pk_value=document_id,
            fields=normed, body=body, require_version=require_version,
        )


def _versioned_table_update(
    table: str,
    pk_value: Any,
    fields: dict[str, Any],
    body: dict[str, Any] | None,
    *,
    allowed: set[str],
    require_version: bool = False,
):
    """Generic thin wrapper around ``versioned_update_from_request`` for
    non-document versioned tables. Filters ``fields`` against the
    ``allowed`` allowlist, no normalization (callers pre-normalize for
    their own semantics), stamps ``updated_at`` when the column exists."""
    from src.db.version_handlers import (
        VersionedUpdateResult, _read_current_version,
        versioned_update_from_request,
    )
    from src.db.optimistic import VERSIONED_TABLES
    normed = {k: v for k, v in (fields or {}).items() if k in allowed}
    if table not in VERSIONED_TABLES:
        raise ValueError(f"table {table!r} not in VERSIONED_TABLES")
    pk_column = VERSIONED_TABLES[table]
    with open_db() as conn:
        # Filter to columns that actually exist (older DBs may lack some
        # of the optional fields listed in ``allowed``). Also stamp
        # updated_at when the column exists.
        try:
            cols = {r["name"] for r in conn.execute(f"PRAGMA table_info({table})").fetchall()}
        except (sqlite3.OperationalError, KeyError, TypeError):
            cols = set()
        if cols:
            normed = {k: v for k, v in normed.items() if k in cols}
            if "updated_at" in cols and "updated_at" not in normed:
                normed["updated_at"] = utc_now_iso()
        if not normed:
            cur = _read_current_version(conn, table, pk_column, pk_value)
            return VersionedUpdateResult(status=200, new_version=cur)
        return versioned_update_from_request(
            conn, table=table, pk_value=pk_value,
            fields=normed, body=body, require_version=require_version,
        )


def update_client_fields_versioned(
    client_code: str, fields: dict[str, Any], body: dict[str, Any] | None,
    *, require_version: bool = False,
):
    return _versioned_table_update(
        "clients", client_code, fields, body,
        allowed={"client_name", "contact_email", "language", "active",
                 "whatsapp_number", "firm_code"},
        require_version=require_version,
    )


