def set_document_status(document_id: str, review_status: str) -> None:
    with open_db() as conn:
        conn.execute("UPDATE documents SET review_status = ?, updated_at = ? WHERE document_id = ?",
                     (review_status, utc_now_iso(), document_id))
        conn.commit()


def set_document_status_versioned(
    document_id: str, review_status: str, body: dict[str, Any] | None,
    *, require_version: bool = False,
):
    """Versioned variant of ``set_document_status``. Returns a
    ``VersionedUpdateResult`` so the caller can emit 200 or 409."""
    from src.db.version_handlers import versioned_update_from_request
    with open_db() as conn:
        return versioned_update_from_request(
            conn, table="documents", pk_value=document_id,
            fields={"review_status": review_status, "updated_at": utc_now_iso()},
            body=body, require_version=require_version,
        )


def set_manual_hold_versioned(
    document_id: str, hold_reason: str, username: str,
    body: dict[str, Any] | None, *, require_version: bool = False,
):
    """Versioned variant of ``set_manual_hold``."""
    from src.db.version_handlers import versioned_update_from_request
    now = utc_now_iso()
    with open_db() as conn:
        return versioned_update_from_request(
            conn, table="documents", pk_value=document_id,
            fields={
                "review_status": "NeedsReview",
                "manual_hold_reason": normalize_optional_text(hold_reason),
                "manual_hold_by": normalize_optional_text(username),
                "manual_hold_at": now,
                "updated_at": now,
            },
            body=body, require_version=require_version,
        )


def assign_document_versioned(
    document_id: str, assigned_to: str, assigned_by: str, note: str = "",
    body: dict[str, Any] | None = None, *, require_version: bool = False,
):
    """Versioned variant of ``assign_document``. The version check runs
    against documents.version; the assignments-table upsert is not
    versioned (there's only one row per document and the ON CONFLICT
    upsert is already idempotent), but we still refuse to touch
    assignments when the documents-row version is stale — this ensures
    two concurrent reassigns with the same stale read can't both land."""
    from src.db.version_handlers import versioned_update_from_request
    clean = normalize_optional_text(assigned_to)
    now = utc_now_iso()
    with open_db() as conn:
        result = versioned_update_from_request(
            conn, table="documents", pk_value=document_id,
            fields={"assigned_to": clean, "updated_at": now},
            body=body, require_version=require_version,
        )
        if result.status != 200:
            return result
        conn.execute(
            """INSERT INTO document_assignments (document_id, assigned_to, assigned_by, assigned_at, updated_at, note)
               VALUES (?,?,?,?,?,?)
               ON CONFLICT(document_id) DO UPDATE SET
                   assigned_to=excluded.assigned_to, assigned_by=excluded.assigned_by,
                   assigned_at=excluded.assigned_at, updated_at=excluded.updated_at, note=excluded.note""",
            (document_id, clean, normalize_optional_text(assigned_by), now, now, normalize_optional_text(note)),
        )
        conn.commit()
    return result


def set_manual_hold(document_id: str, hold_reason: str, username: str) -> None:
    with open_db() as conn:
        conn.execute(
            "UPDATE documents SET review_status='NeedsReview', manual_hold_reason=?, manual_hold_by=?, manual_hold_at=?, updated_at=? WHERE document_id=?",
            (normalize_optional_text(hold_reason), normalize_optional_text(username), utc_now_iso(), utc_now_iso(), document_id),
        )
        conn.commit()


def clear_manual_hold(document_id: str) -> None:
    with open_db() as conn:
        conn.execute(
            "UPDATE documents SET manual_hold_reason=NULL, manual_hold_by=NULL, manual_hold_at=NULL, updated_at=? WHERE document_id=?",
            (utc_now_iso(), document_id),
        )
        conn.commit()


def assign_document(document_id: str, assigned_to: str, assigned_by: str, note: str = "") -> None:
    clean = normalize_optional_text(assigned_to)
    now = utc_now_iso()
    with open_db() as conn:
        conn.execute(
            """INSERT INTO document_assignments (document_id, assigned_to, assigned_by, assigned_at, updated_at, note)
               VALUES (?,?,?,?,?,?)
               ON CONFLICT(document_id) DO UPDATE SET
                   assigned_to=excluded.assigned_to, assigned_by=excluded.assigned_by,
                   assigned_at=excluded.assigned_at, updated_at=excluded.updated_at, note=excluded.note""",
            (document_id, clean, normalize_optional_text(assigned_by), now, now, normalize_optional_text(note)),
        )
        conn.execute("UPDATE documents SET assigned_to=?, updated_at=? WHERE document_id=?", (clean, now, document_id))
        conn.commit()


def get_qbo_posting_job(document_id: str) -> dict | None:
    with open_db() as conn:
        row = conn.execute(
            "SELECT * FROM posting_jobs WHERE document_id=? AND target_system='qbo' ORDER BY COALESCE(updated_at,created_at) DESC, rowid DESC LIMIT 1",
            (document_id,),
        ).fetchone()
        return dict(row) if row else None


def record_learning_corrections(
    document_id: str,
    before_row: dict,
    updated_fields: dict[str, Any],
    *,
    reviewer: str = "",
    firm_code: str = "",
) -> None:
    tracked = {"vendor","client_code","doc_type","amount","document_date","gl_account","tax_code","category","review_status"}
    vendor_after = None
    if "vendor" in updated_fields:
        vendor_after = normalize_optional_text(updated_fields["vendor"])
    elif before_row and "vendor" in before_row.keys():
        vendor_after = before_row["vendor"]
    for field, submitted in updated_fields.items():
        if field not in tracked:
            continue
        old = before_row[field] if field in before_row.keys() else None
        new = normalize_amount_input(submitted) if field == "amount" else normalize_optional_text(submitted)
        if (str(old) if old is not None else "") == (str(new) if new is not None else ""):
            continue
        try:
            learning_store.record_correction(
                document_id=document_id, field_name=field, old_value=old,
                new_value=new if new is not None else "",
                reviewer=reviewer or DEFAULT_REVIEWER,
                correction_context={"source": "review_dashboard", "document_id": document_id},
            )
        except Exception:
            pass
        # Sprint A: mirror the correction into the vendor/GL learning tables
        # so future extractions can auto-canonicalise vendors and suggest GL
        # codes. Never raise — learning must not block user edits.
        try:
            from src.engines.self_learning import record_correction as _sl_record  # noqa: PLC0415
            _sl_record(
                document_id=document_id,
                field=field,
                old_value=old,
                new_value=new,
                corrected_by=reviewer or DEFAULT_REVIEWER,
                firm_code=firm_code,
                vendor_hint=vendor_after,
            )
        except Exception:
            logging.exception("self_learning.record_correction failed")


# ---------------------------------------------------------------------------
# Learning history (safe fallback)
# ---------------------------------------------------------------------------

def get_learning_history(document_id: str) -> list[dict[str, Any]]:
    try:
        result = learning_store.get_document_learning_history(document_id)
        if isinstance(result, list):
            return result
    except Exception:
        pass
    for table in ("learning_corrections", "gl_corrections", "field_corrections", "corrections"):
        try:
            with open_db() as conn:
                rows = conn.execute(
                    f"SELECT field_name, old_value, new_value, reviewer, COALESCE(created_at, updated_at, '') AS created_at FROM {table} WHERE document_id=? ORDER BY created_at DESC LIMIT 50",
                    (document_id,),
                ).fetchall()
            return [dict(r) for r in rows]
        except Exception:
            continue
    return []


