def render_totp_challenge(flash_error: str = "", lang: str = "fr") -> str:
    err = f'<div class="flash error">{esc(flash_error)}</div>' if flash_error else ""
    heading = "Authentification à deux facteurs" if lang == "fr" else "Two-Factor Authentication"
    sub = ("Entrez le code à 6 chiffres de votre application d'authentification."
           if lang == "fr" else "Enter the 6-digit code from your authenticator app.")
    label = "Code"
    verify = "Vérifier" if lang == "fr" else "Verify"
    cancel = "Annuler" if lang == "fr" else "Cancel"
    return f"""<!doctype html>
<html lang="{lang}">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>{heading} — OtoCPA</title>
<style>{PUBLIC_CSS}
.field input[name=code]{{letter-spacing:10px;text-align:center;font-size:22px;font-weight:700}}
</style>
</head>
<body>
<div class="public-wrap">
    <div class="brand-top">{LOGO_SVG_LARGE}</div>
    <div class="auth-card">
        <h1>{heading}</h1>
        <p class="sub">{sub}</p>
        {err}
        <form method="POST" action="/login/totp">
            <div class="field">
                <label for="f-code">{label}</label>
                <input id="f-code" type="text" name="code" inputmode="numeric" pattern="[0-9]{{6}}"
                       maxlength="6" autofocus autocomplete="one-time-code" placeholder="123456">
            </div>
            <button class="btn-green" type="submit">{verify}</button>
        </form>
        <div class="auth-links">
            <a href="/logout">{cancel}</a>
        </div>
    </div>
    <div class="public-footer">
        &copy; 2026 OtoCPA Inc. &middot; Conforme Loi 25
    </div>
</div>
</body></html>"""


def render_2fa_settings(user: dict[str, Any], flash: str = "", flash_error: str = "",
                        setup_secret: str = "", lang: str = "fr") -> str:
    enabled = bool(user.get("totp_enabled"))
    flash_html = f'<div class="flash">{esc(flash)}</div>' if flash else ""
    err_html = f'<div class="flash error">{esc(flash_error)}</div>' if flash_error else ""
    if enabled and not setup_secret:
        body = f"""
        <p><strong>Status:</strong> <span style="color:#16a34a;">Enabled</span></p>
        <p>Two-factor authentication is active on your account.</p>
        <form method="POST" action="/settings/2fa/disable" style="margin-top:16px;">
            <button class="btn-primary" type="submit" style="background:#dc2626;">{ui_t('disable_2fa', lang)}</button>
        </form>
        """
    else:
        secret = setup_secret or user.get("totp_secret") or ""
        qr_b64 = generate_totp_qr_base64(secret, user.get("username", "user")) if secret else ""
        qr_b64 = "".join(qr_b64.split())
        body = f"""
        <p><strong>Status:</strong> <span style="color:#6b7280;">Not enabled</span></p>
        <p>Scan this QR code with Google Authenticator, Authy, or a similar app, then enter the 6-digit code to enable.</p>
        <div style="text-align:center;margin:18px 0;">
            <img src="data:image/png;base64,{qr_b64}" alt="TOTP QR code" style="width:250px;height:250px;display:block;margin:0 auto;">
        </div>
        <p style="font-size:12px;color:#6b7280;">Manual secret: <code>{esc(secret)}</code></p>
        <form method="POST" action="/settings/2fa/enable" style="margin-top:16px;">
            <input type="hidden" name="secret" value="{esc(secret)}">
            <div class="field"><label>Verification code</label>
                <input type="text" name="code" inputmode="numeric" pattern="[0-9]{{6}}"
                       maxlength="6" autofocus autocomplete="one-time-code"></div>
            <button class="btn-primary" type="submit">{ui_t('enable_2fa', lang)}</button>
        </form>
        """
    inner = f"""
    <div class="card">
        <h2>Two-Factor Authentication</h2>
        {flash_html}{err_html}
        {body}
        <p style="margin-top:20px;"><a href="/">&larr; Back</a></p>
    </div>
    """
    return page_layout("2FA Settings", inner, user=user, lang=lang)


def render_profile_page(user: dict[str, Any], flash: str = "", flash_error: str = "",
                        lang: str = "fr") -> str:
    flash_html = f'<div class="flash">{esc(flash)}</div>' if flash else ""
    err_html = f'<div class="flash error">{esc(flash_error)}</div>' if flash_error else ""
    totp_on = bool(user.get("totp_enabled"))
    totp_badge = ('<span style="color:#16a34a;font-weight:600;">Enabled</span>' if totp_on
                  else '<span style="color:#6b7280;">Disabled</span>')
    totp_btn_label = "Manage 2FA" if totp_on else "Enable 2FA"
    inner = f"""
    <div class="card">
        <h2>{ui_t("profile", lang)}</h2>
        {flash_html}{err_html}
        <form method="POST" action="/settings/profile/save">
            <div class="field"><label>Username (read-only)</label>
                <input type="text" value="{esc(user.get("username",""))}" disabled></div>
            <div class="field"><label>Role (read-only)</label>
                <input type="text" value="{esc(user.get("role",""))}" disabled></div>
            <div class="field"><label>Display name</label>
                <input type="text" name="display_name" value="{esc(user.get("display_name") or "")}"></div>
            <div class="field"><label>Email address</label>
                <input type="email" name="email" value="{esc(user.get("email") or "")}"></div>
            <div class="field"><label>Language</label>
                <select name="language">
                    <option value="fr"{' selected' if (user.get("language") or "fr") == "fr" else ''}>Français</option>
                    <option value="en"{' selected' if user.get("language") == "en" else ''}>English</option>
                </select></div>
            <div class="field"><label>WhatsApp number (for receiving documents)</label>
                <input type="tel" name="whatsapp_number" value="{esc(user.get("whatsapp_number") or "")}"
                       placeholder="+15145551234"></div>

            <h3 style="margin-top:24px;">Change password</h3>
            <p style="font-size:12px;color:#6b7280;">Leave blank to keep current password. Current password is required to save any change.</p>
            <div class="field"><label>Current password</label>
                <input type="password" name="current_password" autocomplete="current-password"></div>
            <div class="field"><label>New password</label>
                <input type="password" name="new_password" minlength="8" autocomplete="new-password"></div>
            <div class="field"><label>Confirm new password</label>
                <input type="password" name="confirm_password" minlength="8" autocomplete="new-password"></div>

            <button class="btn-primary" type="submit" style="margin-top:16px;">{ui_t("save_changes", lang)}</button>
        </form>
    </div>

    <div class="card" style="margin-top:16px;">
        <h3>Two-Factor Authentication</h3>
        <p><strong>Status:</strong> {totp_badge}</p>
        <p><a class="btn-primary" href="/settings/2fa" style="display:inline-block;text-decoration:none;">{totp_btn_label}</a></p>
    </div>

    <p style="margin-top:20px;"><a href="/">&larr; Back</a></p>
    """
    return page_layout("Profile", inner, user=user, lang=lang)


# ---------------------------------------------------------------------------
# Bank feed (Plaid) pages
# ---------------------------------------------------------------------------

def render_bank_connect(user: dict[str, Any], flash: str = "", flash_error: str = "",
                        lang: str = "fr", client_code: str = "",
                        plaid_configured: bool = True,
                        clients: list | None = None) -> str:
    flash_html = f'<div class="flash">{esc(flash)}</div>' if flash else ""
    err_html = f'<div class="flash error">{esc(flash_error)}</div>' if flash_error else ""
    cc_js = json.dumps(client_code)
    cc_qs = f"?client={urlquote(client_code)}" if client_code else ""
    client_label = f" for <strong>{esc(client_code)}</strong>" if client_code else ""
    back_link = (f'<a href="/clients/edit?code={urlquote(client_code)}">&larr; Back to client</a>'
                 if client_code else '<a href="/bank/feeds">View connected accounts &rarr;</a>')

    selector_html = ""
    if not client_code:
        opts = '<option value="">Select client...</option>'
        for cl in (clients or []):
            opts += (f'<option value="{esc(cl["client_code"])}">'
                     f'{esc(cl["client_code"])} - {esc(cl.get("client_name") or cl["client_code"])}</option>')
        selector_html = (
            '<div style="margin:12px 0;">'
            '<label for="client-select">Client: </label>'
            f'<select id="client-select" name="client_code" style="padding:4px 8px;">{opts}</select>'
            '</div>'
        )

    inner = f"""
    <div class="card">
        <h2>{ui_t("connect_bank", lang)}{client_label}</h2>
        {flash_html}{err_html}
        <p>Connect a bank account via Plaid to automatically import transactions.</p>
        {selector_html}
        <button id="connect-btn" class="btn-primary" style="margin-top:12px;">{ui_t("connect_bank", lang)}</button>
        <p style="margin-top:20px;">{back_link}</p>
    </div>
    <script src="https://cdn.plaid.com/link/v2/stable/link-initialize.js"></script>
    <script>
    let CLIENT_CODE = {cc_js};
    const sel = document.getElementById('client-select');
    if (sel) {{
      sel.addEventListener('change', () => {{ CLIENT_CODE = sel.value; }});
    }}
    fetch('/bank/link_token' + (CLIENT_CODE ? ('?client=' + encodeURIComponent(CLIENT_CODE)) : ''))
      .then(r => r.json())
      .then(data => {{
        if (!data.link_token) {{
          document.getElementById('connect-btn').disabled = true;
          document.getElementById('connect-btn').textContent = 'Plaid not configured';
          return;
        }}
        const handler = Plaid.create({{
          token: data.link_token,
          onSuccess: (public_token, metadata) => {{
            fetch('/bank/callback' + (CLIENT_CODE ? ('?client=' + encodeURIComponent(CLIENT_CODE)) : ''), {{
              method: 'POST',
              headers: {{'Content-Type': 'application/json'}},
              body: JSON.stringify({{public_token, metadata, client_code: CLIENT_CODE}})
            }}).then(() => {{
              window.location = CLIENT_CODE
                ? ('/clients/edit?code=' + encodeURIComponent(CLIENT_CODE))
                : '/bank/feeds';
            }});
          }},
        }});
        document.getElementById('connect-btn').onclick = () => handler.open();
      }})
      .catch(() => {{
        document.getElementById('connect-btn').disabled = true;
        document.getElementById('connect-btn').textContent = 'Plaid not configured';
      }});
    </script>
    """
    return page_layout("Bank", inner, user=user, lang=lang)


def render_bank_feeds(user: dict[str, Any], connections: list, tx_by_client: dict,
                       flash: str = "", flash_error: str = "", lang: str = "fr",
                       clients: list | None = None) -> str:
    flash_html = f'<div class="flash">{esc(flash)}</div>' if flash else ""
    err_html = f'<div class="flash error">{esc(flash_error)}</div>' if flash_error else ""
    clients = clients or []
    conn_rows = ""
    for c in connections:
        last_sync = c.get("last_sync") or "Never"
        cc = c.get("client_code") or ""
        client_options = '<option value="">— unassigned —</option>'
        for cl in clients:
            sel = " selected" if cl["client_code"] == cc else ""
            client_options += (
                f'<option value="{esc(cl["client_code"])}"{sel}>'
                f'{esc(cl["client_code"])} - {esc(cl.get("client_name") or cl["client_code"])}</option>'
            )
        assign_form = (
            f"<form method='POST' action='/bank/assign' style='display:flex;gap:4px;align-items:center;'>"
            f"<input type='hidden' name='connection_id' value='{esc(c.get('id',''))}'>"
            f"<select name='client_code' style='padding:2px 4px;font-size:12px;'>{client_options}</select>"
            f"<button type='submit' style='padding:2px 8px;'>{ui_t('assign', lang)}</button></form>"
        )
        conn_rows += (
            f"<tr><td>{esc(c.get('institution_name') or '')}</td>"
            f"<td>{esc(c.get('account_name') or '')}</td>"
            f"<td>{assign_form}</td>"
            f"<td>{esc(last_sync)}</td>"
            f"<td>"
            f"<form method='POST' action='/bank/sync?client={urlquote(cc)}' style='display:inline;'>"
            f"<input type='hidden' name='connection_id' value='{esc(c.get('id',''))}'>"
            f"<button type='submit'>{ui_t('sync', lang)}</button></form> "
            f"<form method='POST' action='/bank/disconnect' style='display:inline;' "
            f"onsubmit=\"return confirm('Disconnect this bank?');\">"
            f"<input type='hidden' name='connection_id' value='{esc(c.get('id',''))}'>"
            f"<button type='submit' style='background:#e74c3c;color:white;'>{ui_t('disconnect', lang)}</button></form>"
            f"</td></tr>"
        )

    grouped_html = ""
    for client_code, txs in sorted(tx_by_client.items()):
        matched = sum(1 for t in txs if t.get("reconciled"))
        unmatched = len(txs) - matched
        tx_rows = ""
        for tx in txs:
            if tx.get("reconciled"):
                status_html = f"<span style='color:#2ecc71;'>&#x2713; matched</span> " \
                              f"<span style='color:#888;font-size:11px;'>{esc(tx.get('matched_document_id') or '')}</span>"
            else:
                status_html = (
                    f"<form method='POST' action='/bank/match' style='display:inline;'>"
                    f"<input type='hidden' name='tx_id' value='{esc(tx.get('id',''))}'>"
                    f"<input type='text' name='document_id' placeholder='document_id' "
                    f"style='padding:2px 6px;width:120px;'>"
                    f"<button type='submit' style='padding:2px 8px;'>{ui_t('match', lang)}</button></form>"
                )
            try:
                amt_str = f"{float(tx.get('amount') or 0):.2f}"
            except (TypeError, ValueError):
                amt_str = str(tx.get("amount") or "")
            tx_rows += (
                f"<tr><td>{esc(str(tx.get('date','')))}</td>"
                f"<td>{esc(tx.get('description') or tx.get('merchant_name') or '')}</td>"
                f"<td style='text-align:right;'>{esc(amt_str)}</td>"
                f"<td>{status_html}</td></tr>"
            )
        grouped_html += f"""
        <div class="card" style="margin-top:16px;">
            <h3>{esc(client_code)} <span style="color:#888;font-size:13px;font-weight:normal;">
                {matched} matched &middot; {unmatched} unmatched</span></h3>
            <table><thead><tr><th>Date</th><th>Description</th>
                <th style="text-align:right;">Amount</th><th>Status</th></tr></thead>
            <tbody>{tx_rows or '<tr><td colspan="4" class="muted">No transactions.</td></tr>'}</tbody></table>
        </div>"""

    inner = f"""
    <div class="card">
        <h2>Bank Feeds</h2>
        {flash_html}{err_html}
        <p><a href="/bank/connect">+ Connect another account</a></p>
        <h3>Connected accounts</h3>
        <table><thead><tr><th>Institution</th><th>Account</th><th>Client</th><th>Last sync</th><th></th></tr></thead>
        <tbody>{conn_rows or '<tr><td colspan="5" class="muted">No connected accounts.</td></tr>'}</tbody></table>
    </div>
    {grouped_html}
    """
    return page_layout("Bank Feeds", inner, user=user, lang=lang)


