def render_billing_page(ctx: dict[str, Any], user: dict[str, Any],
                        flash: str = "", flash_error: str = "",
                        lang: str = "fr") -> str:
    firm_code = user.get("firm_code") or ctx.get("firm_code") or ""
    row = {}
    if firm_code:
        with open_db() as conn:
            r = conn.execute(
                "SELECT plan, subscription_status, trial_ends_at, stripe_customer_id, billing_email"
                " FROM firms WHERE firm_code=?",
                (firm_code,),
            ).fetchone()
            row = dict(r) if r else {}
    plan = html.escape(row.get("plan") or "trial")
    status = html.escape(row.get("subscription_status") or "trial")
    trial_end = html.escape(row.get("trial_ends_at") or "")
    has_customer = bool(row.get("stripe_customer_id"))
    portal_btn = (
        '<a href="/billing/portal" class="btn">Gérer mon abonnement / Manage billing</a>'
        if has_customer
        else '<a href="/signup" class="btn">Choisir un plan / Choose a plan</a>'
    )
    trial_html = f"<p><strong>Fin de l'essai:</strong> {trial_end}</p>" if trial_end else ""
    body = f"""
    <div style="padding:24px;max-width:720px;">
        <h2 style="color:white;">&#128179; Facturation / Billing</h2>
        <div class="card" style="background:#1a2e4a;border-radius:12px;padding:24px;margin-top:16px;">
            <p><strong>Cabinet:</strong> {html.escape(firm_code)}</p>
            <p><strong>Plan actuel:</strong> {plan}</p>
            <p><strong>Statut:</strong> {status}</p>
            {trial_html}
            <div style="margin-top:24px;">{portal_btn}</div>
        </div>
        <style>.btn{{display:inline-block;background:#2ecc71;color:#000;padding:12px 24px;border-radius:8px;text-decoration:none;font-weight:bold;}}</style>
    </div>
    """
    return page_layout("Billing", body, user=user, flash=flash, flash_error=flash_error, lang=lang)


# stripe-python >=8 dropped dict-subclassing on StripeObject, so `.get()` no
# longer works on objects returned by Session.retrieve / webhook events. This
# helper reads a field from either a StripeObject or a plain dict.
def _sv(obj: Any, key: str, default: Any = None) -> Any:
    if obj is None:
        return default
    try:
        return obj[key] if key in obj else default
    except Exception:
        return default


def _provision_firm_from_stripe(session: Any, base_url: str = "") -> dict[str, Any]:
    """Create firm + admin user from a Stripe checkout.

    Returns a dict with keys: firm_code, admin_username, set_password_url,
    email_sent, existing (bool), plan.
    """
    metadata = _sv(session, "metadata") or {}
    plan_key = _sv(metadata, "plan", "pro")
    email = (
        _sv(session, "customer_email")
        or _sv(_sv(session, "customer_details") or {}, "email")
        or ""
    )
    customer_id = _sv(session, "customer") or ""
    subscription_id = _sv(session, "subscription") or ""

    firm_code = _sv(metadata, "firm_code") or ""
    if not firm_code:
        firm_code = "CPA" + secrets.token_hex(3).upper()
    admin_username = email or f"admin_{firm_code.lower()}"
    firm_name = email.split("@")[0] if email else firm_code

    portal_base = (base_url or _get_portal_base_url()).rstrip("/")

    with open_db() as conn:
        existing = conn.execute(
            "SELECT firm_code FROM firms WHERE stripe_customer_id=?",
            (customer_id,),
        ).fetchone()
        if existing:
            firm_code = existing["firm_code"]
            admin_row = conn.execute(
                "SELECT username FROM dashboard_users WHERE firm_code=? AND role='firm_admin' LIMIT 1",
                (firm_code,),
            ).fetchone()
            admin_username = admin_row["username"] if admin_row else admin_username
            return {
                "firm_code": firm_code,
                "admin_username": admin_username,
                "set_password_url": "",
                "email_sent": False,
                "existing": True,
                "plan": plan_key,
                "email": email,
            }

        # Same email paying again with a different Stripe customer_id (common in
        # test mode): the username (= email) would collide with an earlier row.
        existing_user = conn.execute(
            "SELECT username, firm_code FROM dashboard_users WHERE username=? LIMIT 1",
            (admin_username,),
        ).fetchone()
        if existing_user:
            return {
                "firm_code": existing_user["firm_code"] or firm_code,
                "admin_username": existing_user["username"],
                "set_password_url": "",
                "email_sent": False,
                "existing": True,
                "plan": plan_key,
                "email": email,
            }

        # Defensive: avoid the rare firm_code PK collision when a caller passes
        # metadata.firm_code or the random token happens to clash.
        while conn.execute(
            "SELECT 1 FROM firms WHERE firm_code=? LIMIT 1", (firm_code,)
        ).fetchone():
            firm_code = "CPA" + secrets.token_hex(3).upper()

        # User never logs in with this; they must go through the set-password link.
        placeholder_pw = secrets.token_urlsafe(32)

        # Mint a per-firm ingest_api_key at provisioning time so
        # /ingest/openclaw can authenticate the very first request.
        # Fall back gracefully if the column doesn't exist (legacy
        # pre-bootstrap schema in some test fixtures).
        _ingest_key = secrets.token_urlsafe(32)
        try:
            conn.execute(
                "INSERT INTO firms (firm_code, firm_name, contact_email, billing_email, language, plan,"
                " active, stripe_customer_id, stripe_subscription_id, subscription_status, ingest_api_key)"
                " VALUES (?,?,?,?,?,?,1,?,?,?,?)",
                (firm_code, firm_name, email, email, "fr", plan_key,
                 customer_id, subscription_id, "active", _ingest_key),
            )
        except sqlite3.OperationalError:
            # Legacy schema without ingest_api_key. Insert without the
            # column; a later bootstrap_schema() run backfills the key.
            conn.execute(
                "INSERT INTO firms (firm_code, firm_name, contact_email, billing_email, language, plan,"
                " active, stripe_customer_id, stripe_subscription_id, subscription_status)"
                " VALUES (?,?,?,?,?,?,1,?,?,?)",
                (firm_code, firm_name, email, email, "fr", plan_key,
                 customer_id, subscription_id, "active"),
            )
        conn.execute(
            "INSERT INTO dashboard_users (username, password_hash, role, display_name, active,"
            " language, firm_code, email, must_reset_password, created_at)"
            " VALUES (?,?,?,?,1,?,?,?,1,?)",
            (admin_username, hash_password(placeholder_pw), "firm_admin",
             firm_name, "fr", firm_code, email, utc_now_iso()),
        )
        conn.commit()

    set_pw_token = _generate_password_link(admin_username, expires_hours=72)
    set_pw_url = f"{portal_base}/set-password?token={set_pw_token}"

    email_sent = False
    if email:
        try:
            from src.integrations.email_client import send_welcome_email
            email_sent = bool(send_welcome_email(
                to_email=email,
                firm_name=firm_name,
                username=admin_username,
                set_password_url=set_pw_url,
                plan=plan_key,
            ))
        except Exception:
            logging.exception("welcome email failed")
            email_sent = False

    return {
        "firm_code": firm_code,
        "admin_username": admin_username,
        "set_password_url": set_pw_url,
        "email_sent": email_sent,
        "existing": False,
        "plan": plan_key,
        "email": email,
    }


def _ensure_stripe_events_table(conn: sqlite3.Connection) -> None:
    """Idempotent schema bootstrap for the webhook dedup table."""
    conn.execute(
        "CREATE TABLE IF NOT EXISTS stripe_events_processed ("
        "  event_id     TEXT PRIMARY KEY,"
        "  event_type   TEXT,"
        "  processed_at TEXT NOT NULL DEFAULT (datetime('now'))"
        ")"
    )


def _stripe_event_id(event: Any) -> str:
    """Return the Stripe event ID from either a Stripe SDK object or a dict."""
    if event is None:
        return ""
    # Stripe SDK objects expose .id; dict payloads use 'id'.
    try:
        eid = getattr(event, "id", None) or event.get("id")  # type: ignore[union-attr]
    except Exception:
        eid = None
    return str(eid).strip() if eid else ""


def _stripe_event_type(event: Any) -> str:
    if event is None:
        return ""
    try:
        et = getattr(event, "type", None) or event.get("type")  # type: ignore[union-attr]
    except Exception:
        et = None
    return str(et).strip() if et else ""


def _stripe_event_already_processed(event_id: str) -> bool:
    """True if we've already processed this Stripe event.id."""
    if not event_id:
        return False
    try:
        with open_db() as conn:
            _ensure_stripe_events_table(conn)
            row = conn.execute(
                "SELECT 1 FROM stripe_events_processed WHERE event_id = ?",
                (event_id,),
            ).fetchone()
        return row is not None
    except Exception:
        logging.exception("stripe idempotency lookup failed")
        return False


def _stripe_event_mark_processed(event_id: str, event_type: str = "") -> None:
    """Record that we've processed this event. Swallows INSERT-conflict
    errors so a racing second delivery still ends cleanly."""
    if not event_id:
        return
    try:
        with open_db() as conn:
            _ensure_stripe_events_table(conn)
            conn.execute(
                "INSERT OR IGNORE INTO stripe_events_processed "
                "(event_id, event_type) VALUES (?, ?)",
                (event_id, event_type or ""),
            )
            conn.commit()
    except Exception:
        logging.exception("stripe idempotency insert failed")


def _handle_stripe_event(event: Any) -> None:
    etype = _sv(event, "type", "") or ""
    data = _sv(_sv(event, "data") or {}, "object") or {}
    customer_id = _sv(data, "customer") or ""
    if etype == "checkout.session.completed":
        try:
            _provision_firm_from_stripe(data)
        except Exception:
            logging.exception("provision firm failed in webhook")
    elif etype in ("customer.subscription.updated", "customer.subscription.created"):
        status = _sv(data, "status", "") or ""
        if customer_id:
            with open_db() as conn:
                conn.execute(
                    "UPDATE firms SET subscription_status=?, stripe_subscription_id=? WHERE stripe_customer_id=?",
                    (status, _sv(data, "id", "") or "", customer_id),
                )
                conn.commit()
    elif etype == "customer.subscription.deleted":
        if customer_id:
            with open_db() as conn:
                conn.execute(
                    "UPDATE firms SET subscription_status='canceled', active=0 WHERE stripe_customer_id=?",
                    (customer_id,),
                )
                conn.commit()
    elif etype == "invoice.payment_failed":
        if customer_id:
            with open_db() as conn:
                conn.execute(
                    "UPDATE firms SET subscription_status='past_due' WHERE stripe_customer_id=?",
                    (customer_id,),
                )
                conn.commit()


