def _get_firm_clients(firm_code: str | None) -> list[dict[str, Any]]:
    """Return all clients for a firm (or all clients when ``firm_code`` is
    None, used by the owner). Used by the QBO status page to enumerate the
    'not yet connected' rows alongside existing connections."""
    with open_db() as conn:
        if firm_code is None:
            rows = conn.execute(
                "SELECT client_code, client_name, firm_code FROM clients "
                "WHERE active=1 ORDER BY firm_code, client_code"
            ).fetchall()
        else:
            rows = conn.execute(
                "SELECT client_code, client_name, firm_code FROM clients "
                "WHERE active=1 AND firm_code=? ORDER BY client_code",
                (firm_code,),
            ).fetchall()
    return [dict(r) for r in rows]


def _qbo_connection_map(firm_code: str | None) -> dict[tuple[str, str], dict[str, Any]]:
    """Return {(firm_code, client_code): connection_row} for fast lookup."""
    from src.agents.tools.qbo_oauth import list_qbo_connections
    out: dict[tuple[str, str], dict[str, Any]] = {}
    for row in list_qbo_connections(firm_code):
        out[(row["firm_code"], row["client_code"])] = row
    return out


def render_qbo_status_page(ctx: dict[str, Any], user: dict[str, Any],
                           flash: str = '', flash_error: str = '',
                           lang: str = 'fr') -> str:
    """Per-client QuickBooks connection status.

    Owners see every firm's connections; firm_admin/manager see only their
    own firm. Employees don't get here — ``post_qbo`` gates the link in
    the navigation.
    """
    from src.agents.tools.qbo_oauth import legacy_config_exists

    role = ctx.get("role")
    firm_code = ctx.get("firm_code")
    firm_scope: str | None = None if role == "owner" else firm_code

    clients = _get_firm_clients(firm_scope)
    conn_map = _qbo_connection_map(firm_scope)

    legacy_banner = ''
    if legacy_config_exists() and not conn_map:
        legacy_banner = (
            '<div class="card" style="background:#3a2a0a;border:1px solid '
            '#d97706;color:#fde68a;padding:12px 16px;margin-bottom:16px;">'
            '<strong>Legacy QuickBooks connection detected.</strong> '
            'The previous single-realm connection has been retired. '
            'Please reconnect each client below.</div>'
        )

    rows_html = ''
    if not clients:
        rows_html = (
            '<tr><td colspan="6" style="color:#888;padding:16px;'
            'text-align:center;">No clients yet.</td></tr>'
        )
    for c in clients:
        key = (c["firm_code"], c["client_code"])
        conn_row = conn_map.get(key)
        client_label = esc(c["client_name"] or c["client_code"])
        client_code_enc = urlquote(c["client_code"])

        if conn_row is None:
            status_badge = ('<span style="color:#e74c3c;">'
                            '&#x1F534; Not connected</span>')
            realm_cell = '<span style="color:#888;">&mdash;</span>'
            connected_cell = '<span style="color:#888;">&mdash;</span>'
            refresh_cell = '<span style="color:#888;">&mdash;</span>'
            actions_cell = (
                f'<a href="/qbo/connect?client_code={client_code_enc}" '
                'style="background:#2CA01C;color:white;padding:6px 12px;'
                'border-radius:4px;text-decoration:none;">Connect &rarr;</a>'
            )
        else:
            status = conn_row.get("status") or "active"
            if status == "active":
                status_badge = ('<span style="color:#2ecc71;">'
                                '&#x2705; Active</span>')
            elif status == "expired":
                status_badge = ('<span style="color:#f39c12;">'
                                '&#x26A0;&#xFE0F; Expired</span>')
            else:
                status_badge = f'<span style="color:#aaa;">{esc(status)}</span>'
            realm_cell = esc(conn_row.get("realm_id") or "")
            connected_cell = esc(conn_row.get("connected_at") or "")
            refresh_cell = esc(conn_row.get("last_refreshed_at")
                               or conn_row.get("last_error") or "just now")
            actions_cell = (
                f'<form method="POST" action="/qbo/disconnect" '
                'style="display:inline;margin-right:6px;" '
                'onsubmit="return confirm(\'Disconnect this client?\');">'
                f'<input type="hidden" name="client_code" '
                f'value="{esc(c["client_code"])}">'
                '<button type="submit" style="background:#e74c3c;color:white;'
                'border:none;padding:6px 12px;border-radius:4px;cursor:pointer;">'
                'Disconnect</button></form>'
                f'<a href="/qbo/connect?client_code={client_code_enc}" '
                'style="background:#3498db;color:white;padding:6px 12px;'
                'border-radius:4px;text-decoration:none;">Reconnect</a>'
            )

        rows_html += (
            '<tr>'
            f'<td style="color:#2ecc71;font-weight:bold;padding:8px;">'
            f'{esc(c["client_code"])}</td>'
            f'<td style="color:#e0e0e0;padding:8px;">{client_label}</td>'
            f'<td style="padding:8px;">{status_badge}</td>'
            f'<td style="color:#aaa;padding:8px;">{realm_cell}</td>'
            f'<td style="color:#aaa;padding:8px;">{connected_cell}</td>'
            f'<td style="color:#aaa;padding:8px;">{refresh_cell}</td>'
            f'<td style="padding:8px;">{actions_cell}</td>'
            '</tr>'
        )

    firm_col = ''
    firm_hdr = ''
    if role == "owner":
        # Owner sees all firms — prepend a firm column so rows stay unambiguous.
        firm_hdr = ('<th style="color:#aaa;padding:12px;text-align:left;">'
                    'Firm</th>')
        # Rewrite rows to include firm_code in first column
        rebuilt = ''
        for c in clients:
            key = (c["firm_code"], c["client_code"])
            conn_row = conn_map.get(key)
            client_label = esc(c["client_name"] or c["client_code"])
            client_code_enc = urlquote(c["client_code"])
            if conn_row is None:
                status_badge = ('<span style="color:#e74c3c;">'
                                '&#x1F534; Not connected</span>')
                realm_cell = '<span style="color:#888;">&mdash;</span>'
                connected_cell = '<span style="color:#888;">&mdash;</span>'
                refresh_cell = '<span style="color:#888;">&mdash;</span>'
                actions_cell = (
                    f'<a href="/qbo/connect?client_code={client_code_enc}" '
                    'style="background:#2CA01C;color:white;padding:6px 12px;'
                    'border-radius:4px;text-decoration:none;">Connect &rarr;</a>'
                )
            else:
                status = conn_row.get("status") or "active"
                if status == "active":
                    status_badge = ('<span style="color:#2ecc71;">'
                                    '&#x2705; Active</span>')
                elif status == "expired":
                    status_badge = ('<span style="color:#f39c12;">'
                                    '&#x26A0;&#xFE0F; Expired</span>')
                else:
                    status_badge = f'<span style="color:#aaa;">{esc(status)}</span>'
                realm_cell = esc(conn_row.get("realm_id") or "")
                connected_cell = esc(conn_row.get("connected_at") or "")
                refresh_cell = esc(conn_row.get("last_refreshed_at")
                                   or conn_row.get("last_error") or "just now")
                actions_cell = (
                    f'<form method="POST" action="/qbo/disconnect" '
                    'style="display:inline;margin-right:6px;" '
                    'onsubmit="return confirm(\'Disconnect this client?\');">'
                    f'<input type="hidden" name="client_code" '
                    f'value="{esc(c["client_code"])}">'
                    '<button type="submit" style="background:#e74c3c;color:white;'
                    'border:none;padding:6px 12px;border-radius:4px;cursor:pointer;">'
                    'Disconnect</button></form>'
                    f'<a href="/qbo/connect?client_code={client_code_enc}" '
                    'style="background:#3498db;color:white;padding:6px 12px;'
                    'border-radius:4px;text-decoration:none;">Reconnect</a>'
                )
            rebuilt += (
                '<tr>'
                f'<td style="color:#aaa;padding:8px;">{esc(c["firm_code"] or "")}</td>'
                f'<td style="color:#2ecc71;font-weight:bold;padding:8px;">'
                f'{esc(c["client_code"])}</td>'
                f'<td style="color:#e0e0e0;padding:8px;">{client_label}</td>'
                f'<td style="padding:8px;">{status_badge}</td>'
                f'<td style="color:#aaa;padding:8px;">{realm_cell}</td>'
                f'<td style="color:#aaa;padding:8px;">{connected_cell}</td>'
                f'<td style="color:#aaa;padding:8px;">{refresh_cell}</td>'
                f'<td style="padding:8px;">{actions_cell}</td>'
                '</tr>'
            )
        if rebuilt:
            rows_html = rebuilt
        firm_col = '1'

    body = f'''
    <div style="padding:24px;">
        <a href="/" style="color:#aaa;text-decoration:none;">&larr; Back to queue</a>
        <h2 style="color:white;">&#x1F4D2; QuickBooks Connections</h2>
        {legacy_banner}
        <p style="color:#aaa;">Each client maps to its own QuickBooks Online
        company (realm). Connect below — tokens are stored per-client and
        refreshed automatically.</p>
        <table style="width:100%;border-collapse:collapse;background:#1a2e4a;
                      border-radius:8px;">
            <thead>
                <tr style="background:#0d1b2a;">
                    {firm_hdr}
                    <th style="color:#aaa;padding:12px;text-align:left;">Client</th>
                    <th style="color:#aaa;padding:12px;text-align:left;">Name</th>
                    <th style="color:#aaa;padding:12px;text-align:left;">Status</th>
                    <th style="color:#aaa;padding:12px;text-align:left;">Realm ID</th>
                    <th style="color:#aaa;padding:12px;text-align:left;">Connected</th>
                    <th style="color:#aaa;padding:12px;text-align:left;">Last refresh</th>
                    <th style="color:#aaa;padding:12px;text-align:left;">Actions</th>
                </tr>
            </thead>
            <tbody>{rows_html}</tbody>
        </table>
    </div>
    '''
    return page_layout("QBO Status", body, user=user, flash=flash,
                       flash_error=flash_error, lang=lang)


def render_learning_page(ctx: dict[str, Any], user: dict[str, Any],
                          lang: str = "fr") -> str:
    """Owner-only self-learning metrics page.

    Shows the top vendor aliases and top vendor→GL corrections the system
    has learned from CPA edits. The numbers come straight from
    self_learning.top_vendor_corrections / top_gl_corrections so there's no
    duplicated counting logic.
    """
    from src.engines.self_learning import (
        top_vendor_corrections,
        top_gl_corrections,
        learning_summary,
    )
    summary = learning_summary()
    vendor_rows = top_vendor_corrections(limit=50)
    gl_rows = top_gl_corrections(limit=50)

    vendor_table = "".join(
        f"<tr><td>{esc(r['extracted_vendor'])}</td>"
        f"<td>→ <strong>{esc(r['canonical_vendor'])}</strong></td>"
        f"<td class='num'>{r['correction_count']}</td>"
        f"<td class='num'>{(r['confidence'] or 0):.2f}</td>"
        f"<td class='muted'>{esc(r['last_seen'] or '')}</td></tr>"
        for r in vendor_rows
    ) or "<tr><td colspan='5' class='muted'>No vendor corrections learned yet.</td></tr>"

    gl_table = "".join(
        f"<tr><td>{esc(r['canonical_vendor'])}</td>"
        f"<td><code>{esc(r['gl_account'])}</code></td>"
        f"<td>{esc(r['tax_code'] or '')}</td>"
        f"<td class='num'>{r['correction_count']}</td>"
        f"<td class='num'>{(r['confidence'] or 0):.2f}</td>"
        f"<td class='muted'>{esc(r['last_seen'] or '')}</td></tr>"
        for r in gl_rows
    ) or "<tr><td colspan='6' class='muted'>No GL corrections learned yet.</td></tr>"

    recent = summary.get("recent_by_field", {}) or {}
    recent_html = " · ".join(
        f"<span><strong>{n}</strong> {esc(k)}</span>" for k, n in recent.items()
    ) or "<span class='muted'>no edits in the last 7 days</span>"

    body = f"""
    <div class="card">
      <h2>&#129504; Learning — Self-correction log</h2>
      <div class="stats">
        <div><span class='label'>Vendor aliases learned</span>
             <strong>{summary['vendor_aliases']['distinct']}</strong>
             <span class='muted'>({summary['vendor_aliases']['total_corrections']} corrections)</span></div>
        <div><span class='label'>Vendor→GL pairs learned</span>
             <strong>{summary['vendor_gl']['distinct']}</strong>
             <span class='muted'>({summary['vendor_gl']['total_corrections']} corrections)</span></div>
        <div><span class='label'>All corrections logged</span>
             <strong>{summary['corrections_all']}</strong></div>
        <div><span class='label'>Last 7 days</span> {recent_html}</div>
      </div>
    </div>

    <div class="card">
      <h3>Top 50 vendor alias corrections</h3>
      <table>
        <thead><tr><th>Extracted (OCR)</th><th>Canonical (CPA fix)</th>
               <th class='num'>Count</th><th class='num'>Conf</th><th>Last seen</th></tr></thead>
        <tbody>{vendor_table}</tbody>
      </table>
    </div>

    <div class="card">
      <h3>Top 50 vendor→GL corrections</h3>
      <table>
        <thead><tr><th>Canonical vendor</th><th>GL</th><th>Tax code</th>
               <th class='num'>Count</th><th class='num'>Conf</th><th>Last seen</th></tr></thead>
        <tbody>{gl_table}</tbody>
      </table>
    </div>

    <style>
      .stats {{ display: grid; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr));
                gap: 12px; margin-top: 10px; }}
      .stats > div {{ background: rgba(255,255,255,0.04); padding: 10px 12px;
                       border-radius: 8px; }}
      .stats .label {{ display: block; font-size: 11px; text-transform: uppercase;
                        letter-spacing: 0.4px; opacity: 0.7; margin-bottom: 4px; }}
      .num {{ text-align: right; font-family: monospace; }}
      .muted {{ opacity: 0.6; font-size: 12px; }}
      table {{ width: 100%; border-collapse: collapse; }}
      table th, table td {{ padding: 6px 10px; border-bottom: 1px solid rgba(255,255,255,0.08); }}
      table th {{ text-align: left; font-size: 12px; text-transform: uppercase; opacity: 0.7; }}
      code {{ font-family: monospace; background: rgba(255,255,255,0.05); padding: 1px 6px;
              border-radius: 4px; }}
    </style>
    """
    return page_layout("Learning", body, user=user, lang=lang)


def render_clients_page(ctx: dict[str, Any], user: dict[str, Any],
                        flash: str = '', flash_error: str = '',
                        lang: str = 'fr',
                        assignee_filter: str = '') -> str:
    """Clients list. assignee_filter values:
      ''            -> no filter
      '__mine__'    -> only clients where current user is primary or secondary
      '__pool__'    -> only clients with no primary AND no secondary
      '<email>'     -> only clients where that employee is primary or secondary
    """
    firm_filter = ctx.get("firm_code") if ctx.get("role") != "owner" else None
    extra_where: str = ''
    extra_params: list[Any] = []
    if assignee_filter == '__mine__':
        my_email = (ctx.get('email') or '').strip().lower()
        if my_email:
            extra_where = (" AND (LOWER(primary_employee_email) = ? "
                            "  OR LOWER(secondary_employee_email) = ?)")
            extra_params = [my_email, my_email]
    elif assignee_filter == '__pool__':
        extra_where = (" AND COALESCE(primary_employee_email,'') = '' "
                        " AND COALESCE(secondary_employee_email,'') = ''")
    elif assignee_filter:
        extra_where = (" AND (LOWER(primary_employee_email) = ? "
                        "  OR LOWER(secondary_employee_email) = ?)")
        extra_params = [assignee_filter.lower(), assignee_filter.lower()]
    with open_db() as conn:
        base_select = (
            "SELECT client_code, client_name, contact_email, "
            "       language, active, whatsapp_number, "
            "       primary_employee_email, secondary_employee_email "
            "FROM clients"
        )
        if firm_filter and firm_filter != "OWNER":
            sql = f"{base_select} WHERE firm_code = ?{extra_where} ORDER BY client_code"
            clients = conn.execute(sql, (firm_filter, *extra_params)).fetchall()
        else:
            sql = f"{base_select} WHERE 1=1{extra_where} ORDER BY client_code"
            clients = conn.execute(sql, tuple(extra_params)).fetchall()
        # Employees: hard-restrict to clients in their allowed list
        # (their portfolio + clients where they are primary/secondary,
        # built in build_user_context).
        if not ctx.get("can_view_all_clients"):
            allowed = {normalize_key(c) for c in ctx.get("allowed_clients", [])}
            clients = [c for c in clients
                       if normalize_key(c["client_code"]) in allowed]
        # Fetch all WhatsApp numbers in one query, group by client_code.
        wa_by_client: dict[str, list[sqlite3.Row]] = {}
        try:
            wa_rows = conn.execute('''
                SELECT client_code, whatsapp_number, contact_name, active
                FROM client_whatsapp_numbers
                WHERE active = 1
                ORDER BY contact_name
            ''').fetchall()
            for wr in wa_rows:
                wa_by_client.setdefault(wr['client_code'], []).append(wr)
        except sqlite3.OperationalError:
            pass
        bank_by_client: dict[str, list[sqlite3.Row]] = {}
        try:
            bank_rows = conn.execute('''
                SELECT client_code, institution_name, account_name, last_sync
                FROM bank_connections
                WHERE active = 1
                ORDER BY created_at DESC
            ''').fetchall()
            for br in bank_rows:
                bank_by_client.setdefault(br['client_code'], []).append(br)
        except sqlite3.OperationalError:
            pass

        # Sprint 3: per-client QBO connection badge on the client list
        qbo_by_client: dict[str, dict[str, Any]] = {}
        try:
            qbo_rows = conn.execute('''
                SELECT client_code, status, realm_id
                FROM qbo_connections
            ''').fetchall()
            for qr in qbo_rows:
                qbo_by_client[qr['client_code']] = dict(qr)
        except sqlite3.OperationalError:
            pass

        # Sprint 4: portal access counts + last access + unread message count
        access_by_client: dict[str, dict[str, Any]] = {}
        try:
            access_rows = conn.execute('''
                SELECT client_code, COUNT(*) AS n, MAX(created_at) AS last_at
                FROM client_portal_access
                GROUP BY client_code
            ''').fetchall()
            for ar in access_rows:
                access_by_client[ar['client_code']] = {
                    'n': int(ar['n'] or 0),
                    'last_at': ar['last_at'] or '',
                }
        except sqlite3.OperationalError:
            pass
        unread_by_client: dict[str, int] = {}
        try:
            unread_rows = conn.execute('''
                SELECT client_code, COUNT(*) AS n
                FROM client_messages
                WHERE direction='inbound' AND read_at IS NULL
                GROUP BY client_code
            ''').fetchall()
            for ur in unread_rows:
                unread_by_client[ur['client_code']] = int(ur['n'] or 0)
        except sqlite3.OperationalError:
            pass

    rows = ''
    for c in clients:
        wa_list = wa_by_client.get(c['client_code'], [])
        wa_html_parts: list[str] = []
        if c['whatsapp_number']:
            wa_html_parts.append(
                f'<div style="color:#e0e0e0;">{esc(c["whatsapp_number"])} '
                f'<span style="color:#888;font-size:11px;">(legacy)</span></div>'
            )
        for wr in wa_list:
            label = wr['contact_name'] or ''
            label_html = (
                f' <span style="color:#888;font-size:11px;">({esc(label)})</span>'
                if label else ''
            )
            wa_html_parts.append(
                f'<div style="color:#e0e0e0;">{esc(wr["whatsapp_number"])}{label_html}</div>'
            )
        wa_cell = ''.join(wa_html_parts) or '<span style="color:#888;">&#x2014;</span>'

        bank_list = bank_by_client.get(c['client_code'], [])
        bank_parts: list[str] = []
        for br in bank_list:
            bank_parts.append(
                f'<div style="color:#e0e0e0;">{esc(br["institution_name"] or "")} '
                f'<span style="color:#888;font-size:11px;">{esc(br["account_name"] or "")}</span></div>'
            )
        bank_parts.append(
            f'<a href="/bank/connect?client={urlquote(c["client_code"])}" '
            f'style="color:#2ecc71;font-size:12px;text-decoration:none;">+ Connect</a>'
        )
        bank_cell = ''.join(bank_parts)

        qbo_row = qbo_by_client.get(c['client_code'])
        if qbo_row and qbo_row.get('status') == 'active':
            qbo_cell = (
                '<div style="color:#2ecc71;">&#x2705; Connected</div>'
                f'<div style="color:#888;font-size:11px;">realm '
                f'{esc(qbo_row.get("realm_id") or "")}</div>'
            )
        elif qbo_row and qbo_row.get('status') == 'expired':
            qbo_cell = (
                '<div style="color:#f39c12;">&#x26A0;&#xFE0F; Expired</div>'
                f'<a href="/qbo/connect?client_code={urlquote(c["client_code"])}" '
                'style="color:#3498db;font-size:12px;text-decoration:none;">'
                'Reconnect</a>'
            )
        else:
            qbo_cell = (
                '<div style="color:#aaa;">Not connected</div>'
                f'<a href="/qbo/connect?client_code={urlquote(c["client_code"])}" '
                'style="color:#2ecc71;font-size:12px;text-decoration:none;">'
                'Connect &rarr;</a>'
            )

        pa = access_by_client.get(c['client_code'], {'n': 0, 'last_at': ''})
        unread = unread_by_client.get(c['client_code'], 0)
        last_access = (pa['last_at'] or '—')[:10] if pa['last_at'] else '—'
        portal_cell = (
            f'<div style="color:#e0e0e0;">Accessed <strong>{pa["n"]}</strong>&times;</div>'
            f'<div style="color:#888;font-size:11px;">Last: {esc(last_access)}</div>'
        )
        if unread:
            portal_cell += (
                f'<div style="background:#e74c3c;color:white;border-radius:10px;'
                f'padding:1px 8px;display:inline-block;font-size:11px;margin-top:4px;">'
                f'&#128172; {unread} new</div>'
            )
        # Hybrid assignment "Lead" badge
        primary_email = (c['primary_employee_email']
                          if 'primary_employee_email' in c.keys() else '') or ''
        secondary_email = (c['secondary_employee_email']
                            if 'secondary_employee_email' in c.keys() else '') or ''
        if primary_email:
            lead_cell = (
                f'<div style="color:#e0e0e0;">{esc(primary_email)}</div>'
            )
            if secondary_email:
                lead_cell += (
                    f'<div style="color:#888;font-size:11px;">'
                    f'2nd: {esc(secondary_email)}</div>'
                )
        else:
            lead_cell = (
                '<div style="color:#aaa;">'
                '&#x1F465; Pool (unassigned)</div>'
            )
        rows += f"""
        <tr>
            <td style="color:#2ecc71;font-weight:bold;vertical-align:top;">{esc(c['client_code'])}</td>
            <td style="color:#e0e0e0;vertical-align:top;">{esc(c['client_name'] or '')}</td>
            <td style="color:#aaa;vertical-align:top;">{esc(c['contact_email'] or '')}</td>
            <td style="color:#e0e0e0;vertical-align:top;">{esc(c['language'] or 'fr')}</td>
            <td style="vertical-align:top;">{'&#x2705;' if c['active'] else '&#x274C;'}</td>
            <td style="vertical-align:top;">{lead_cell}</td>
            <td style="vertical-align:top;">{wa_cell}</td>
            <td style="vertical-align:top;">{bank_cell}</td>
            <td style="vertical-align:top;">{qbo_cell}</td>
            <td style="vertical-align:top;">{portal_cell}</td>
            <td style="vertical-align:top;">
                <a href="/clients/edit?code={urlquote(c['client_code'])}"
                   style="background:#3498db;color:white;padding:4px 8px;border-radius:4px;text-decoration:none;">
                   &#x270F;&#xFE0F; Edit
                </a>
            </td>
        </tr>"""

    return page_layout("Clients", f"""
    <div style="padding:24px;">
        <a href="/" style="color:#aaa;text-decoration:none;margin-bottom:16px;display:inline-block;">
            &larr; Retour à la file / Back to queue
        </a>
        <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:16px;">
            <h2 style="color:white;">&#x1F465; Clients</h2>
            <a href="/clients/new" style="background:#2ecc71;color:white;padding:8px 16px;border-radius:6px;text-decoration:none;">
                + Nouveau client / New client
            </a>
        </div>
        {_render_assignee_filter_html(ctx, assignee_filter)}

        <table style="width:100%;border-collapse:collapse;background:#1a2e4a;border-radius:8px;">
            <thead>
                <tr style="background:#0d1b2a;">
                    <th style="color:#aaa;padding:12px;text-align:left;">Code</th>
                    <th style="color:#aaa;padding:12px;text-align:left;">Nom / Name</th>
                    <th style="color:#aaa;padding:12px;text-align:left;">Email</th>
                    <th style="color:#aaa;padding:12px;text-align:left;">Langue</th>
                    <th style="color:#aaa;padding:12px;text-align:left;">Actif</th>
                    <th style="color:#aaa;padding:12px;text-align:left;">&#x1F465; Lead</th>
                    <th style="color:#aaa;padding:12px;text-align:left;">&#x1F4F1; WhatsApp</th>
                    <th style="color:#aaa;padding:12px;text-align:left;">&#x1F3E6; Bank</th>
                    <th style="color:#aaa;padding:12px;text-align:left;">&#x1F4D2; QBO</th>
                    <th style="color:#aaa;padding:12px;text-align:left;">&#128241; Portal</th>
                    <th style="color:#aaa;padding:12px;text-align:left;">Actions</th>
                </tr>
            </thead>
            <tbody>{rows}</tbody>
        </table>
    </div>
    """, user=user, flash=flash, flash_error=flash_error, lang=lang)


def _render_assignee_filter_html(
    ctx: dict[str, Any], current: str = '',
) -> str:
    """Filter dropdown for /clients page (owner / firm_admin only).

    Lets admins narrow the list to: All / Mine / Pool / a specific
    employee. Posts via GET so the URL is shareable.
    """
    if ctx.get("role") not in ("owner", "firm_admin"):
        return ''
    from src.integrations.client_assignment import get_firm_employees  # noqa: PLC0415
    firm_code = ctx.get("firm_code") or "OWNER"
    employees = get_firm_employees(DB_PATH, firm_code)
    options = [
        ('',          'All clients'),
        ('__mine__',  'Only mine'),
        ('__pool__',  'Pool (unassigned)'),
    ]
    for e in employees:
        options.append((e['email'], f"{e['display_name']} ({e['email']})"))
    sel_html = ''.join(
        f'<option value="{esc(v)}" {"selected" if v == current else ""}>'
        f'{esc(label)}</option>'
        for v, label in options
    )
    return (
        '<form method="GET" action="/clients" '
        ' style="margin:12px 0;display:flex;gap:8px;align-items:center;">'
        '<label style="color:#aaa;">Show clients assigned to:</label>'
        f'<select name="assignee" style="background:#0d1b2a;color:white;'
        f'border:1px solid #2c3e50;padding:6px;border-radius:4px;'
        f'min-width:280px;">{sel_html}</select>'
        '<button type="submit" style="background:#3498db;color:white;'
        ' border:none;padding:6px 14px;border-radius:4px;cursor:pointer;">'
        'Apply</button>'
        '</form>'
    )


def render_client_form(ctx: dict[str, Any], user: dict[str, Any],
                       client: dict[str, Any] | None = None,
                       flash: str = '', flash_error: str = '',
                       lang: str = 'fr') -> str:
    is_edit = client is not None
    title = "Modifier client / Edit client" if is_edit else "Nouveau client / New client"
    code_val = esc(client['client_code']) if is_edit else ''
    name_val = esc(client['client_name'] or '') if is_edit else ''
    email_val = esc(client['contact_email'] or '') if is_edit else ''
    lang_val = (client['language'] or 'fr') if is_edit else 'fr'
    whatsapp_val = esc(client['whatsapp_number'] or '') if is_edit else ''
    active_checked = 'checked' if (not is_edit or client['active']) else ''
    code_readonly = 'readonly style="background:#334155;"' if is_edit else ''

    # Hybrid assignment: owner / firm_admin sees a Team Assignment
    # section (primary + secondary employee dropdowns + history). Other
    # roles see a read-only badge of the current assignment so they
    # know who's on the file.
    assignment_section = ''
    if is_edit:
        assignment_section = _render_client_assignment_section(
            client, ctx, lang=lang,
        )

    # Bank connections (edit mode only — needs an existing client_code).
    bank_section = ''
    if is_edit:
        bank_conns: list[dict] = []
        try:
            with open_db() as _bk_conn:
                bank_conns = [dict(r) for r in _bk_conn.execute('''
                    SELECT id, institution_name, account_name, last_sync
                    FROM bank_connections
                    WHERE client_code = ? AND active = 1
                    ORDER BY created_at DESC
                ''', (client['client_code'],)).fetchall()]
                # tx counts per connection/client
                tx_count_row = _bk_conn.execute(
                    'SELECT COUNT(*) AS n, SUM(reconciled) AS r FROM bank_transactions WHERE client_code=?',
                    (client['client_code'],)
                ).fetchone()
                tx_total = (tx_count_row['n'] if tx_count_row else 0) or 0
                tx_reconciled = (tx_count_row['r'] if tx_count_row else 0) or 0
        except sqlite3.OperationalError:
            tx_total = 0
            tx_reconciled = 0

        bank_items_html = ''
        for bc in bank_conns:
            last_sync = bc.get('last_sync') or 'Jamais / Never'
            bank_items_html += f"""
            <div style="display:flex;align-items:center;gap:8px;padding:6px 0;border-bottom:1px solid #2c3e50;">
                <div style="flex:1;color:#e0e0e0;">
                    <strong>{esc(bc.get('institution_name') or '')}</strong>
                    <span style="color:#888;margin-left:8px;">{esc(bc.get('account_name') or '')}</span>
                    <div style="color:#888;font-size:12px;">Last sync: {esc(last_sync)}</div>
                </div>
                <form method="POST" action="/bank/sync?client={urlquote(client['client_code'])}" style="margin:0;">
                    <input type="hidden" name="connection_id" value="{esc(bc.get('id',''))}">
                    <button type="submit"
                            style="background:#3498db;color:white;border:none;padding:4px 10px;border-radius:4px;cursor:pointer;font-size:12px;">
                        {ui_t("sync", lang)}
                    </button>
                </form>
                <form method="POST" action="/bank/disconnect" style="margin:0;"
                      onsubmit="return confirm('Disconnect this bank account?');">
                    <input type="hidden" name="connection_id" value="{esc(bc.get('id',''))}">
                    <input type="hidden" name="client_code" value="{esc(client['client_code'])}">
                    <button type="submit"
                            style="background:#e74c3c;color:white;border:none;padding:4px 10px;border-radius:4px;cursor:pointer;font-size:12px;">
                        {ui_t("disconnect", lang)}
                    </button>
                </form>
            </div>"""
        if not bank_items_html:
            bank_items_html = '<div style="color:#888;padding:6px 0;">Aucune connexion / No connections</div>'

        bank_section = f"""
        <div style="margin-top:24px;padding:16px;background:#0d1b2a;border-radius:6px;border:1px solid #2c3e50;">
            <h3 style="color:white;margin-top:0;">&#x1F3E6; Comptes bancaires / Bank accounts</h3>
            <p style="color:#888;font-size:12px;margin:0 0 12px 0;">
                Transactions: <strong style="color:#e0e0e0;">{tx_total}</strong>
                &middot; Reconciled: <strong style="color:#2ecc71;">{tx_reconciled}</strong>
            </p>
            {bank_items_html}
            <a href="/bank/connect?client={urlquote(client['client_code'])}"
               style="display:inline-block;margin-top:12px;background:#2ecc71;color:white;padding:8px 16px;border-radius:4px;text-decoration:none;">
                + Connect bank account
            </a>
        </div>"""

    # WhatsApp numbers management (edit mode only — needs an existing client_code).
    wa_section = ''
    if is_edit:
        wa_rows: list[sqlite3.Row] = []
        try:
            with open_db() as _wa_conn:
                wa_rows = _wa_conn.execute('''
                    SELECT id, whatsapp_number, contact_name, active
                    FROM client_whatsapp_numbers
                    WHERE client_code = ?
                    ORDER BY contact_name
                ''', (client['client_code'],)).fetchall()
        except sqlite3.OperationalError:
            pass

        wa_items_html = ''
        for wr in wa_rows:
            label = wr['contact_name'] or ''
            wa_items_html += f"""
            <div style="display:flex;align-items:center;gap:8px;padding:6px 0;border-bottom:1px solid #2c3e50;">
                <div style="flex:1;color:#e0e0e0;">
                    <strong>{esc(wr['whatsapp_number'])}</strong>
                    {f'<span style="color:#888;margin-left:8px;">{esc(label)}</span>' if label else ''}
                    {'' if wr['active'] else '<span style="color:#e74c3c;margin-left:8px;">(inactive)</span>'}
                </div>
                <form method="POST" action="/clients/whatsapp/delete" style="margin:0;"
                      onsubmit="return confirm('Delete this number?');">
                    <input type="hidden" name="id" value="{wr['id']}">
                    <input type="hidden" name="client_code" value="{esc(client['client_code'])}">
                    <button type="submit"
                            style="background:#e74c3c;color:white;border:none;padding:4px 10px;border-radius:4px;cursor:pointer;font-size:12px;">
                        &#x1F5D1; Delete
                    </button>
                </form>
            </div>"""
        if not wa_items_html:
            wa_items_html = '<div style="color:#888;padding:6px 0;">Aucun numéro / No numbers</div>'

        wa_section = f"""
        <div style="margin-top:24px;padding:16px;background:#0d1b2a;border-radius:6px;border:1px solid #2c3e50;">
            <h3 style="color:white;margin-top:0;">&#x1F4F1; Numéros WhatsApp / WhatsApp Numbers</h3>
            <p style="color:#888;font-size:12px;margin:0 0 12px 0;">
                Plusieurs numéros peuvent être associés à ce client.
                / Multiple numbers can be linked to this client.
            </p>
            {wa_items_html}
            <form method="POST" action="/clients/whatsapp/add" style="margin-top:12px;display:flex;gap:8px;flex-wrap:wrap;">
                <input type="hidden" name="client_code" value="{esc(client['client_code'])}">
                <input type="text" name="whatsapp_number" placeholder="+15145551234" required
                       style="flex:1;min-width:160px;background:#1a2e4a;color:white;border:1px solid #2c3e50;padding:8px;border-radius:4px;">
                <input type="text" name="contact_name" placeholder="Nom du contact / Contact name"
                       style="flex:1;min-width:160px;background:#1a2e4a;color:white;border:1px solid #2c3e50;padding:8px;border-radius:4px;">
                <button type="submit"
                        style="background:#2ecc71;color:white;border:none;padding:8px 16px;border-radius:4px;cursor:pointer;">
                    + Ajouter / Add
                </button>
            </form>
        </div>"""

    # Sprint 3: per-client QBO section (edit mode only).
    qbo_section = ''
    if is_edit:
        qbo_row = None
        try:
            with open_db() as _qb_conn:
                qr = _qb_conn.execute(
                    "SELECT realm_id, status, connected_at, last_refreshed_at, "
                    "last_error FROM qbo_connections WHERE client_code=?",
                    (client['client_code'],),
                ).fetchone()
                qbo_row = dict(qr) if qr else None
        except sqlite3.OperationalError:
            pass

        if qbo_row is None:
            qbo_body = (
                '<div style="color:#aaa;">Not connected to QuickBooks.</div>'
                f'<a href="/qbo/connect?client_code={urlquote(client["client_code"])}" '
                'style="display:inline-block;margin-top:12px;background:#2CA01C;'
                'color:white;padding:8px 16px;border-radius:4px;'
                'text-decoration:none;">Connect &rarr;</a>'
            )
        else:
            status = qbo_row.get("status") or "active"
            badge = ('<span style="color:#2ecc71;">&#x2705; Active</span>'
                     if status == "active"
                     else '<span style="color:#f39c12;">&#x26A0;&#xFE0F; '
                          f'{esc(status)}</span>')
            qbo_body = (
                f'<div style="color:#e0e0e0;">Status: {badge}</div>'
                f'<div style="color:#888;font-size:12px;">Realm: '
                f'{esc(qbo_row.get("realm_id") or "")} &middot; Connected: '
                f'{esc(qbo_row.get("connected_at") or "")}</div>'
                '<div style="margin-top:12px;display:flex;gap:8px;">'
                f'<form method="POST" action="/qbo/disconnect" '
                'style="margin:0;" '
                'onsubmit="return confirm(\'Disconnect QBO for this client?\');">'
                f'<input type="hidden" name="client_code" '
                f'value="{esc(client["client_code"])}">'
                '<button type="submit" style="background:#e74c3c;color:white;'
                'border:none;padding:6px 14px;border-radius:4px;cursor:pointer;">'
                'Disconnect</button></form>'
                f'<a href="/qbo/connect?client_code={urlquote(client["client_code"])}" '
                'style="background:#3498db;color:white;padding:6px 14px;'
                'border-radius:4px;text-decoration:none;">Reconnect</a>'
                '</div>'
            )

        qbo_section = f"""
        <div style="margin-top:24px;padding:16px;background:#0d1b2a;border-radius:6px;border:1px solid #2c3e50;">
            <h3 style="color:white;margin-top:0;">&#x1F4D2; QuickBooks Online</h3>
            {qbo_body}
        </div>"""

    # Sprint 4: Client portal link section (edit mode only).
    portal_section = ''
    if is_edit:
        portal_base = _get_portal_base_url()
        pt_token = client.get('portal_token') or ''
        pt_created = client.get('portal_token_created_at') or ''
        pt_rotated = client.get('portal_token_rotated_count') or 0
        # Access count + last access
        try:
            with open_db() as _pa_conn:
                pa_row = _pa_conn.execute(
                    "SELECT COUNT(*) AS n, MAX(created_at) AS last_at "
                    "FROM client_portal_access WHERE client_code=?",
                    (client['client_code'],),
                ).fetchone()
                pa_count = int(pa_row['n'] or 0) if pa_row else 0
                pa_last = (pa_row['last_at'] or '—') if pa_row else '—'
        except sqlite3.OperationalError:
            pa_count = 0
            pa_last = '—'
        portal_url = f"{portal_base.rstrip('/')}/c/{pt_token}" if pt_token else ''
        import base64 as _b64
        qr_img_html = ''
        if pt_token and qrcode is not None:
            try:
                qr_png = generate_client_qr_png(
                    client['client_code'],
                    client.get('client_name') or client['client_code'],
                    portal_url,
                )
                qr_b64 = _b64.b64encode(qr_png).decode('ascii')
                qr_img_html = (
                    f'<img src="data:image/png;base64,{qr_b64}" alt="Portal QR" '
                    f'style="width:200px;height:auto;background:white;padding:8px;border-radius:6px;">'
                )
            except Exception:
                qr_img_html = ''
        portal_section = f"""
        <div style="margin-top:24px;padding:16px;background:#0d1b2a;border-radius:6px;border:1px solid #2c3e50;">
            <h3 style="color:white;margin-top:0;">&#128241; Portail client / Client portal</h3>
            <div style="display:flex;gap:16px;flex-wrap:wrap;align-items:flex-start;">
                <div>{qr_img_html}</div>
                <div style="flex:1;min-width:260px;color:#e0e0e0;">
                    <div style="font-size:12px;color:#888;">URL</div>
                    <div style="word-break:break-all;background:#1a2e4a;padding:6px 8px;border-radius:4px;font-family:monospace;font-size:12px;">
                        {esc(portal_url) or '<em>no token</em>'}
                    </div>
                    <div style="font-size:12px;color:#888;margin-top:10px;">
                        Created: {esc(pt_created or '—')} &middot; Rotated: {int(pt_rotated)}&times;<br>
                        Access events: <strong>{pa_count}</strong> &middot; Last: {esc(pa_last)}
                    </div>
                    <div style="margin-top:12px;display:flex;gap:8px;flex-wrap:wrap;">
                        <button type="button" onclick="navigator.clipboard.writeText('{esc(portal_url)}');this.textContent='Copied!';"
                                style="background:#3498db;color:white;border:none;padding:6px 14px;border-radius:4px;cursor:pointer;">
                            &#128203; Copy link
                        </button>
                        <form method="POST" action="/clients/rotate-token" style="margin:0;"
                              onsubmit="return confirm('Rotate token? The old QR code will stop working.');">
                            <input type="hidden" name="client_code" value="{esc(client['client_code'])}">
                            <button type="submit"
                                    style="background:#e67e22;color:white;border:none;padding:6px 14px;border-radius:4px;cursor:pointer;">
                                &#128260; Rotate token
                            </button>
                        </form>
                        <form method="POST" action="/clients/send-portal-link" style="margin:0;">
                            <input type="hidden" name="client_code" value="{esc(client['client_code'])}">
                            <button type="submit"
                                    style="background:#2ecc71;color:white;border:none;padding:6px 14px;border-radius:4px;cursor:pointer;">
                                &#128231; Send by email
                            </button>
                        </form>
                        <a href="/clients/messages?code={urlquote(client['client_code'])}"
                           style="background:#9b59b6;color:white;padding:6px 14px;border-radius:4px;text-decoration:none;">
                            &#128172; Messages
                        </a>
                    </div>
                    <p style="color:#f39c12;font-size:11px;margin-top:10px;">
                        &#9888; Ce lien donne accès direct au portail &mdash; gardez-le confidentiel.
                    </p>
                </div>
            </div>
        </div>"""

    return page_layout(title, f"""
    <div style="padding:24px;max-width:600px;">
        <h2 style="color:white;">{esc(title)}</h2>
        <form method="POST" action="/clients/save" style="display:flex;flex-direction:column;gap:12px;">
            <label style="color:#e0e0e0;">Code client / Client code *
                <input type="text" name="client_code" value="{code_val}" required
                       {code_readonly}
                       style="background:#0d1b2a;color:white;border:1px solid #2c3e50;padding:8px;border-radius:4px;width:100%;">
            </label>
            <label style="color:#e0e0e0;">Nom / Name
                <input type="text" name="client_name" value="{name_val}"
                       style="background:#0d1b2a;color:white;border:1px solid #2c3e50;padding:8px;border-radius:4px;width:100%;">
            </label>
            <label style="color:#e0e0e0;">Email
                <input type="email" name="contact_email" value="{email_val}"
                       style="background:#0d1b2a;color:white;border:1px solid #2c3e50;padding:8px;border-radius:4px;width:100%;">
            </label>
            <label style="color:#e0e0e0;">Langue / Language
                <select name="language" style="background:#0d1b2a;color:white;border:1px solid #2c3e50;padding:8px;border-radius:4px;width:100%;">
                    <option value="fr" {"selected" if lang_val == "fr" else ""}>Fran&#xe7;ais</option>
                    <option value="en" {"selected" if lang_val == "en" else ""}>English</option>
                </select>
            </label>
            <label style="color:#e0e0e0;">&#x1F4F1; WhatsApp
                <input type="text" name="whatsapp_number" value="{whatsapp_val}"
                       placeholder="+15145551234"
                       style="background:#0d1b2a;color:white;border:1px solid #2c3e50;padding:8px;border-radius:4px;width:100%;">
            </label>
            <label style="color:#e0e0e0;display:flex;align-items:center;gap:8px;">
                <input type="checkbox" name="active" value="1" {active_checked}>
                Actif / Active
            </label>
            <div style="display:flex;gap:12px;margin-top:8px;">
                <button type="submit" style="background:#2ecc71;color:white;border:none;padding:10px 24px;border-radius:6px;cursor:pointer;">
                    &#x2705; Sauvegarder / Save
                </button>
                <a href="/clients" style="background:#64748b;color:white;padding:10px 24px;border-radius:6px;text-decoration:none;">
                    Annuler / Cancel
                </a>
            </div>
        </form>
        {assignment_section}
        {portal_section}
        {wa_section}
        {bank_section}
        {qbo_section}
    </div>
    """, user=user, flash=flash, flash_error=flash_error, lang=lang)


def _render_client_assignment_section(
    client: dict[str, Any], ctx: dict[str, Any], *, lang: str = 'fr',
) -> str:
    """Team-assignment block for the client edit page.

    Owner / firm_admin: editable primary + secondary dropdowns plus the
    last few entries of client_assignment_history.

    Employees: read-only badge showing who's primary / secondary so they
    know the current assignment without being able to change it.
    """
    code = client.get('client_code') or ''
    primary = (client.get('primary_employee_email') or '').strip()
    secondary = (client.get('secondary_employee_email') or '').strip()
    role = ctx.get('role') or ''
    can_edit = role in ('owner', 'firm_admin')

    # firm_code: owner sees clients across firms, scope by client row.
    firm_code = client.get('firm_code') or ctx.get('firm_code') or 'OWNER'
    from src.integrations.client_assignment import (  # noqa: PLC0415
        get_firm_employees, get_assignment_history,
    )
    employees = get_firm_employees(DB_PATH, firm_code)

    def _opt_select(selected: str) -> str:
        out = ['<option value="">&mdash; (unassigned / non assigné) &mdash;</option>']
        for e in employees:
            sel = 'selected' if e['email'].lower() == selected.lower() else ''
            label = esc(f"{e['display_name']} ({e['email']}) [{e['role']}]")
            out.append(f'<option value="{esc(e["email"])}" {sel}>{label}</option>')
        return ''.join(out)

    if not can_edit:
        # Read-only view for employees.
        primary_label = esc(primary) or '<em>unassigned</em>'
        secondary_label = esc(secondary) or '<em>none</em>'
        return f"""
        <div style="margin-top:24px;padding:16px;background:#0d1b2a;border-radius:6px;border:1px solid #2c3e50;">
            <h3 style="color:white;margin-top:0;">&#x1F465; Team assignment</h3>
            <div style="color:#e0e0e0;">Primary: <strong>{primary_label}</strong></div>
            <div style="color:#e0e0e0;">Secondary: <strong>{secondary_label}</strong></div>
            <p style="color:#888;font-size:12px;margin:8px 0 0 0;">
                Only owner or firm admin can change team assignment.
            </p>
        </div>"""

    history = get_assignment_history(DB_PATH, firm_code=firm_code,
                                       client_code=code, limit=5)
    history_html = ''
    if history:
        items = []
        for h in history:
            stamp = esc((h.get('changed_at') or '')[:19])
            who = esc(h.get('changed_by') or '')
            action = esc(h.get('action') or '')
            new_p = esc(h.get('new_primary') or '—')
            new_s = esc(h.get('new_secondary') or '—')
            reason = esc(h.get('reason') or '')
            reason_html = (f' &mdash; <em>{reason}</em>') if reason else ''
            items.append(
                f'<li style="color:#aaa;">'
                f'<span style="color:#e0e0e0;">{stamp}</span>'
                f' &middot; {action} by {who} &middot; '
                f'primary={new_p}, secondary={new_s}{reason_html}'
                f'</li>'
            )
        history_html = (
            '<details style="margin-top:12px;">'
            '<summary style="color:#aaa;cursor:pointer;">'
            'Recent assignment changes</summary>'
            f'<ul style="margin:8px 0 0 16px;">{"".join(items)}</ul>'
            '</details>'
        )

    return f"""
    <div style="margin-top:24px;padding:16px;background:#0d1b2a;border-radius:6px;border:1px solid #2c3e50;">
        <h3 style="color:white;margin-top:0;">&#x1F465; Team assignment</h3>
        <p style="color:#888;font-size:12px;margin:0 0 12px 0;">
            New documents on this client are auto-routed to the primary employee.
            If primary is inactive the secondary takes over.
        </p>
        <form method="POST" action="/clients/assignment" style="display:flex;flex-direction:column;gap:10px;">
            <input type="hidden" name="client_code" value="{esc(code)}">
            <label style="color:#e0e0e0;">Primary
                <select name="primary_email" style="background:#0d1b2a;color:white;border:1px solid #2c3e50;padding:8px;border-radius:4px;width:100%;">
                    {_opt_select(primary)}
                </select>
            </label>
            <label style="color:#e0e0e0;">Secondary (coverage)
                <select name="secondary_email" style="background:#0d1b2a;color:white;border:1px solid #2c3e50;padding:8px;border-radius:4px;width:100%;">
                    {_opt_select(secondary)}
                </select>
            </label>
            <label style="color:#e0e0e0;">Reason (optional)
                <input type="text" name="reason" placeholder="e.g. Sophie covering for Jean while on leave"
                       style="background:#0d1b2a;color:white;border:1px solid #2c3e50;padding:8px;border-radius:4px;width:100%;">
            </label>
            <button type="submit" style="background:#2ecc71;color:white;border:none;padding:8px 16px;border-radius:4px;cursor:pointer;align-self:flex-start;">
                &#x1F4BE; Save assignment
            </button>
        </form>
        {history_html}
    </div>"""


def render_home(ctx: dict[str, Any], user: dict[str, Any], status: str, q: str,
                flash: str, flash_error: str, include_ignored: bool,
                only_my_queue: bool, only_unassigned: bool, lang: str = "fr",
                page: int = 1, per_page: int = 50,
                uploader_emails: list[str] | None = None) -> str:
    # Hybrid assignment: surface unassigned-client nudge to owner /
    # firm_admin. Backward compatible — existing clients start with
    # NULL primary so a fresh upgrade may show a lot of pool clients;
    # the banner gives one-click access to filter them.
    unassigned_banner = _render_unassigned_clients_banner(ctx, lang=lang)

    # SQL-level pagination — fetch only the rows needed for this page
    total_rows = count_documents(ctx=ctx, status=status, q=q,
                                 include_ignored=include_ignored,
                                 only_my_queue=only_my_queue,
                                 only_unassigned=only_unassigned,
                                 uploader_emails=uploader_emails)
    total_pages = max(1, (total_rows + per_page - 1) // per_page)
    page = max(1, min(page, total_pages))
    offset = (page - 1) * per_page
    rows = get_documents(ctx=ctx, status=status, q=q, include_ignored=include_ignored,
                         only_my_queue=only_my_queue, only_unassigned=only_unassigned,
                         per_page=per_page, offset=offset,
                         uploader_emails=uploader_emails)
    counts = get_status_counts(ctx)

    # Item 1: uploader filter dropdown. Scoped to the user's firm so
    # an owner sees every uploader across all firms; firm_admin sees
    # only their own firm's counts.
    uploader_filter_html = ''
    try:
        from src.integrations.queue_filters import (
            uploader_filter_options as _upl_options,
            render_uploader_filter_dropdown as _upl_dropdown,
        )
        _scope_firm = (ctx.get('firm_code')
                       if ctx.get('role') != 'owner' else None)
        options = _upl_options(DB_PATH, firm_code=_scope_firm)
        preserve = {'status': status, 'q': q, 'queue_mode': (
            'mine' if only_my_queue else 'unassigned' if only_unassigned else 'all'
        ), 'page': '1'}
        if include_ignored:
            preserve['include_ignored'] = '1'
        uploader_filter_html = _upl_dropdown(
            options, selected_keys=uploader_emails or [],
            form_action='/', preserve_params=preserve,
        )
    except Exception:
        logging.exception("uploader filter render failed")

    portfolio_btn = (
        f'<a class="button-link btn-dark" href="/portfolios">{esc(t("btn_manage_portfolios", lang))}</a>'
        if ctx["can_manage_team"] else ""
    )
    users_btn = (
        f'<a class="button-link btn-secondary" href="/users">{esc(t("btn_users", lang))}</a>'
        if ctx["role"] == "owner" else ""
    )
    period_close_btn = (
        f'<a class="button-link btn-secondary" href="/period_close">{esc(t("pc_nav_link", lang))}</a>'
        if ctx["can_manage_team"] else ""
    )
    time_btn = (
        f'<a class="button-link btn-secondary" href="/time">{esc(t("time_nav_link", lang))}</a>'
        if ctx["can_manage_team"] else ""
    )
    comms_btn = (
        f'<a class="button-link btn-secondary" href="/communications">{esc(t("comm_nav_link", lang))}</a>'
        if ctx["can_manage_team"] else ""
    )
    wp_btn = (
        f'<a class="button-link btn-secondary" href="/working_papers">{esc(t("wp_nav_link", lang))}</a>'
        if ctx["can_manage_team"] else ""
    )
    engagements_btn = (
        f'<a class="button-link btn-secondary" href="/engagements">{esc(t("eng_title", lang))}</a>'
        if ctx["can_manage_team"] else ""
    )

    header_html = f"""
    <div class="queue-header">
        <div>
            <h1>{esc(t("queue_title", lang))}</h1>
            <p>{esc(t("stat_visible", lang))}: {total_rows}</p>
        </div>
        <div class="queue-header-actions">{portfolio_btn}{users_btn}{period_close_btn}{time_btn}{comms_btn}{wp_btn}{engagements_btn}
            <button type="button" class="button-link btn-primary" onclick="toggleCollapsible('uploadCard')">\U0001f4e4 T\u00e9l\u00e9verser / Upload</button>
            <a class="button-link btn-secondary" href="/">{esc(t("btn_reset", lang))}</a>
        </div>
    </div>
    <div class="queue-kpis">
        <div class="kpi-card kpi-needs"><div class="kpi-label">{esc(t("stat_needs_review", lang))}</div><div class="kpi-value">{counts.get("Needs Review",0)}</div></div>
        <div class="kpi-card kpi-hold"><div class="kpi-label">{esc(t("stat_on_hold", lang))}</div><div class="kpi-value">{counts.get("On Hold",0)}</div></div>
        <div class="kpi-card kpi-ready"><div class="kpi-label">{esc(t("stat_ready_to_post", lang))}</div><div class="kpi-value">{counts.get("Ready to Post",0)}</div></div>
        <div class="kpi-card kpi-posted"><div class="kpi-label">{esc(t("stat_posted", lang))}</div><div class="kpi-value">{counts.get("Posted",0)}</div></div>
        <div class="kpi-card kpi-visible"><div class="kpi-label">{esc(t("stat_visible", lang))}</div><div class="kpi-value">{total_rows}</div></div>
    </div>"""

    # Learning stats
    _learning_stats_html = ""
    try:
        from src.engines.client_mismatch_engine import get_learning_stats
        _lstats = get_learning_stats()
        if _lstats.get("total", 0) > 0:
            _pct_auto = round(100 * _lstats["auto_approved"] / _lstats["total"]) if _lstats["total"] else 0
            _pct_suggested = round(100 * _lstats["suggested_correctly"] / _lstats["total"]) if _lstats["total"] else 0
            _pct_correction = round(100 * _lstats["needed_correction"] / _lstats["total"]) if _lstats["total"] else 0
            _pct_fraud = round(100 * _lstats["fraud_caught"] / _lstats["total"]) if _lstats["total"] else 0
            _learning_stats_html = f"""
    <div class="collapsible-card" id="aiCard" data-open="false">
        <div class="collapsible-head" onclick="toggleCollapsible('aiCard')">
            <div>
                <h3>\U0001f4ca Apprentissage ce mois / Learning this month</h3>
                <p>{_lstats["total"]} documents \u00b7 ~{_lstats["time_saved_hours"]}h \u00e9conomis\u00e9es</p>
            </div>
            <svg class="collapsible-chevron" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><polyline points="6 9 12 15 18 9"/></svg>
        </div>
        <div class="collapsible-body">
            <div class="ai-mini-grid">
                <div class="ai-mini"><div class="ai-mini-label">Auto-approuv\u00e9s</div><div class="ai-mini-value">{_lstats["auto_approved"]} <small style="font-size:12px;color:#64748b;">({_pct_auto}%)</small></div></div>
                <div class="ai-mini"><div class="ai-mini-label">Sugg\u00e9r\u00e9 correctement</div><div class="ai-mini-value">{_lstats["suggested_correctly"]} <small style="font-size:12px;color:#64748b;">({_pct_suggested}%)</small></div></div>
                <div class="ai-mini"><div class="ai-mini-label">Correction n\u00e9cessaire</div><div class="ai-mini-value">{_lstats["needed_correction"]} <small style="font-size:12px;color:#64748b;">({_pct_correction}%)</small></div></div>
                <div class="ai-mini"><div class="ai-mini-label">Fraude d\u00e9tect\u00e9e</div><div class="ai-mini-value">{_lstats["fraud_caught"]} <small style="font-size:12px;color:#64748b;">({_pct_fraud}%)</small></div></div>
            </div>
            <div class="ai-footnote">Temps \u00e9conomis\u00e9 / Time saved: ~{_lstats["time_saved_hours"]} heures</div>
        </div>
    </div>"""
    except Exception:
        pass

    # Upload section — client options
    _upload_client_options = ""
    try:
        with open_db() as _uconn:
            _upload_clients = _uconn.execute('SELECT client_code, client_name FROM clients ORDER BY client_code').fetchall()
            _upload_client_options = '\n'.join([f'<option value="{esc(c["client_code"])}">{esc(c["client_code"])} - {esc(c["client_name"])}</option>' for c in _upload_clients])
    except Exception:
        pass

    upload_html = f"""
    <div class="collapsible-card" id="uploadCard" data-open="false">
        <div class="collapsible-head" onclick="toggleCollapsible('uploadCard')">
            <div>
                <h3>\U0001f4e4 T\u00e9l\u00e9verser des documents / Upload Documents</h3>
                <p>Glissez-d\u00e9posez ou s\u00e9lectionnez des fichiers PDF/images</p>
            </div>
            <svg class="collapsible-chevron" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><polyline points="6 9 12 15 18 9"/></svg>
        </div>
        <div class="collapsible-body">
            <div class="upload-panel">
                <form method="POST" action="/upload" enctype="multipart/form-data">
                    <div id="drop-zone" class="upload-drop">
                        <div><strong>\U0001f4c1 Glissez-d\u00e9posez ici / Drag &amp; drop here</strong><span>PDF, JPG, PNG, TIFF, HEIC, WEBP</span></div>
                    </div>
                    <input type="file" id="upload-file-input" name="files" multiple accept=".pdf,.jpg,.jpeg,.png,.tiff,.heic,.webp"
                           style="color:#fff;margin-bottom:10px;display:block;width:100%;">
                    <select name="client_code" style="width:100%;padding:10px;margin-bottom:10px;border-radius:8px;border:1px solid rgba(255,255,255,0.15);background:rgba(255,255,255,0.05);color:#fff;">
                        <option value="" style="color:#0f172a;">-- S\u00e9lectionner client / Select client --</option>
                        {_upload_client_options}
                    </select>
                    <button id="upload-btn" type="submit" style="background:#18c37e;color:#041220;border:none;padding:12px 24px;border-radius:10px;font-size:14px;font-weight:800;cursor:pointer;width:100%;">
                        \u2705 T\u00e9l\u00e9verser / Upload
                    </button>
                    <div id="upload-spinner" style="display:none;text-align:center;padding:12px;color:rgba(255,255,255,0.7);">
                        \u23f3 Traitement en cours... / Processing...
                    </div>
                </form>
            </div>
        </div>
    </div>
    <div id="upload-progress" style="display:none;padding:14px;margin-top:12px;border-radius:10px;background:rgba(24,195,126,0.08);border:1px solid rgba(24,195,126,0.3);color:#fff;">
        <div id="upload-progress-text" style="font-weight:700;font-size:14px;">Processing...</div>
        <div id="upload-progress-details" style="font-size:12px;opacity:0.8;margin-top:4px;"></div>
    </div>
    <script>
    (function() {{
        var uploadForm = document.querySelector('form[action="/upload"]');
        if (!uploadForm) return;
        var btn = document.getElementById('upload-btn');
        var spinner = document.getElementById('upload-spinner');
        var progress = document.getElementById('upload-progress');
        var progressText = document.getElementById('upload-progress-text');
        var progressDetails = document.getElementById('upload-progress-details');
        var pollTimer = null;

        function showProgress(msg, detail) {{
            if (progress) progress.style.display = 'block';
            if (progressText) progressText.textContent = msg;
            if (progressDetails) progressDetails.textContent = detail || '';
        }}

        function resetButton() {{
            if (btn) {{ btn.disabled = false; btn.innerText = '\u2705 T\u00e9l\u00e9verser / Upload'; }}
            if (spinner) spinner.style.display = 'none';
        }}

        function pollStatus(ids) {{
            if (!ids.length) return;
            fetch('/upload/status?document_ids=' + encodeURIComponent(ids.join(',')))
                .then(function(r) {{ return r.json(); }})
                .then(function(j) {{
                    if (!j.ok) return;
                    var c = j.counts || {{}};
                    var ready = c.ready || 0, proc = c.processing || 0, q = c.queued || 0, err = c.error || 0;
                    showProgress(
                        'Processing ' + ids.length + ' document(s)...',
                        ready + ' ready, ' + proc + ' processing, ' + q + ' queued' + (err ? (', ' + err + ' failed') : '')
                    );
                    var done = (ready + err) >= ids.length;
                    if (done) {{
                        clearInterval(pollTimer);
                        showProgress('\u2705 All ' + ids.length + ' document(s) processed (' + err + ' failed).',
                            'Refreshing dashboard...');
                        setTimeout(function() {{ window.location.reload(); }}, 1500);
                    }}
                }})
                .catch(function() {{ /* keep polling */ }});
        }}

        uploadForm.addEventListener('submit', function(ev) {{
            ev.preventDefault();
            if (btn) {{ btn.disabled = true; btn.innerText = 'T\u00e9l\u00e9versement... / Uploading...'; }}
            if (spinner) spinner.style.display = 'block';
            var fd = new FormData(uploadForm);
            fetch('/upload', {{ method: 'POST', body: fd, headers: {{ 'X-Async-Upload': '1' }} }})
                .then(function(r) {{ return r.json().then(function(j) {{ return [r.status, j]; }}); }})
                .then(function(pair) {{
                    var status = pair[0], j = pair[1];
                    if (!j.ok) {{
                        showProgress('\u274c Upload failed', j.error || ('HTTP ' + status));
                        resetButton();
                        return;
                    }}
                    var ids = j.document_ids || [];
                    if (!ids.length) {{
                        showProgress('\u26a0\ufe0f Nothing queued',
                            (j.skipped ? (j.skipped + ' duplicate(s) skipped') : ''));
                        resetButton();
                        return;
                    }}
                    showProgress('Uploaded ' + ids.length + ' document(s). Processing in background...', '');
                    resetButton();
                    pollStatus(ids);
                    pollTimer = setInterval(function() {{ pollStatus(ids); }}, 5000);
                }})
                .catch(function(e) {{
                    showProgress('\u274c Upload error', String(e));
                    resetButton();
                }});
        }});
    }})();
    </script>
    <script>
    (function() {{
        var dz = document.getElementById('drop-zone');
        var fi = document.getElementById('upload-file-input');
        if (!dz || !fi) return;
        ['dragenter','dragover'].forEach(function(e) {{
            dz.addEventListener(e, function(ev) {{ ev.preventDefault(); ev.stopPropagation(); dz.style.borderColor='#27ae60'; dz.style.background='#1a3a5c'; }});
        }});
        ['dragleave','drop'].forEach(function(e) {{
            dz.addEventListener(e, function(ev) {{ ev.preventDefault(); ev.stopPropagation(); dz.style.borderColor='#2ecc71'; dz.style.background='#0d1b2a'; }});
        }});
        dz.addEventListener('drop', function(ev) {{
            ev.preventDefault();
            fi.files = ev.dataTransfer.files;
            dz.textContent = ev.dataTransfer.files.length + ' fichier(s) / file(s) selected';
        }});
        dz.addEventListener('click', function() {{ fi.click(); }});
        fi.addEventListener('change', function() {{
            if (fi.files.length > 0) dz.textContent = fi.files.length + ' fichier(s) / file(s) selected';
        }});
    }})();
    </script>"""

    status_opts = "".join(
        f'<option value="{v}" {"selected" if status==v else ""}>'
        f'{esc(t(_STATUS_LABEL_KEYS.get(v, v), lang))}</option>'
        for v in ["Needs Review", "On Hold", "Ready to Post", "Posted", "Ignored"]
    )
    filters_html = f"""
    {uploader_filter_html}
    <form method="GET" action="/">
        <div class="action-bar">
            <div class="search-wrap"><input type="text" name="q" value="{esc(q)}" placeholder="{esc(t("filter_search_ph", lang))}"></div>
            <button type="button" class="button-link btn-secondary" onclick="toggleCollapsible('filterCard')">\u2699\ufe0f More Filters</button>
            <button class="button-link btn-primary" type="submit">{esc(t("btn_filter", lang))}</button>
        </div>
        <div class="collapsible-card" id="filterCard" data-open="false">
            <div class="collapsible-head" onclick="toggleCollapsible('filterCard')">
                <div>
                    <h3>\u2699\ufe0f {esc(t("btn_filter", lang))}</h3>
                    <p>{esc(t("filter_status", lang))} \u00b7 {esc(t("filter_queue_view", lang))} \u00b7 {esc(t("filter_ignored", lang))}</p>
                </div>
                <svg class="collapsible-chevron" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><polyline points="6 9 12 15 18 9"/></svg>
            </div>
            <div class="collapsible-body">
                <div class="filter-grid">
                    <div class="filter-field"><label>{esc(t("filter_status", lang))}</label><select name="status">
                        <option value="">{esc(t("queue_all_visible", lang))}</option>
                        {status_opts}
                    </select></div>
                    <div class="filter-field"><label>{esc(t("filter_queue_view", lang))}</label><select name="queue_mode">
                        <option value="all" {"selected" if not only_my_queue and not only_unassigned else ""}>{esc(t("queue_all_visible", lang))}</option>
                        <option value="mine" {"selected" if only_my_queue else ""}>{esc(t("queue_mine", lang))}</option>
                        <option value="unassigned" {"selected" if only_unassigned else ""}>{esc(t("queue_unassigned", lang))}</option>
                    </select></div>
                    <div class="filter-field"><label>{esc(t("filter_ignored", lang))}</label><select name="include_ignored">
                        <option value="0" {"selected" if not include_ignored else ""}>{esc(t("ignored_hide", lang))}</option>
                        <option value="1" {"selected" if include_ignored else ""}>{esc(t("ignored_show", lang))}</option>
                    </select></div>
                    <div class="filter-field" style="align-self:end;"><button class="button-link btn-primary" type="submit">{esc(t("btn_filter", lang))}</button></div>
                </div>
            </div>
        </div>
    </form>"""

    all_usernames = get_available_usernames()
    _unassigned_badge = '<span class="badge badge-needsreview">\U0001F4C1 Non assign\u00e9</span>'
    # Pre-import learning status icon function once (not per-row)
    _get_learning_icon = None
    try:
        from src.engines.client_mismatch_engine import get_learning_status_icon as _get_learning_icon
    except Exception:
        pass
    row_html: list[str] = []
    card_html: list[str] = []
    for _row_idx, row in enumerate(rows):
        assigned = normalize_text(row["assigned_to"])
        is_mine = normalize_key(assigned) == normalize_key(ctx["username"])
        status_display = get_accounting_status(row)
        reason = get_plain_review_reason(row)
        next_action = get_next_action(row, ctx)
        next_action_display = esc(t(_NEXT_ACTION_KEYS.get(next_action, next_action), lang))
        _detail_id = f"row{_row_idx}"

        if ctx["can_assign"]:
            opts = "".join(f'<option value="{esc(u)}" {"selected" if normalize_key(assigned)==normalize_key(u) else ""}>{esc(u)}</option>' for u in all_usernames)
            assign_ctrl = f"""<form method="POST" action="/assign" class="inline-form" onclick="event.stopPropagation()">
                <input type="hidden" name="document_id" value="{esc(row["document_id"])}">
                <input type="hidden" name="redirect_to" value="home">
                <select name="assigned_to" class="inline-select" style="min-width:110px;"><option value="">{esc(t("option_unassigned", lang))}</option>{opts}</select>
                <button class="claim-btn" type="submit">{esc(t("btn_assign", lang))}</button></form>"""
        elif not assigned:
            assign_ctrl = f"""<form method="POST" action="/claim" class="inline-form" onclick="event.stopPropagation()">
                <input type="hidden" name="document_id" value="{esc(row["document_id"])}">
                <input type="hidden" name="redirect_to" value="home">
                <button class="claim-btn" type="submit">{esc(t("btn_claim", lang))}</button></form>"""
        else:
            assign_ctrl = esc(assigned or t("unassigned_label", lang))

        # Learning status icon
        _ls_badge = ""
        if _get_learning_icon:
            try:
                _ls = _get_learning_icon(row)
                _ls_badge = (
                    f'<span class="badge {_ls["css_class"]}" title="{esc(_ls["label_fr"])}">'
                    f'{_ls["icon"]}</span> '
                )
            except Exception:
                pass

        _doc_url = f"/document?id={urlquote(row['document_id'])}"
        # Item 1: small coloured chip for the uploader.
        try:
            from src.integrations.queue_filters import (
                render_uploader_badge as _render_upl_badge,
                render_channel_badge as _render_chan_badge,
            )
            _uploader_badge_html = _render_upl_badge(
                row.get("uploader_name"), row.get("uploader_email"),
            )
            # Channel chip next to the uploader so the queue shows
            # at a glance whether a doc arrived via portal or WhatsApp.
            # Suppress the 'portal' chip — it's the default and
            # would add noise on every row.
            _channel_val = (row.get("uploaded_via_channel") or "").lower()
            if _channel_val and _channel_val != 'portal':
                _uploader_badge_html += _render_chan_badge(
                    _channel_val, lang=lang,
                )
        except Exception:
            _uploader_badge_html = ""
        row_html.append(f"""<tr class="data-row" onclick="toggleRowDetail('{_detail_id}')">
            <td class="file-cell"><a class="doc-link" href="{_doc_url}" onclick="event.stopPropagation()">{esc(row["file_name"])}</a>
                <div class="doc-sub">{esc(row["document_id"])} {_uploader_badge_html}</div></td>
            <td>{ _unassigned_badge if row["client_code"] == "UNASSIGNED" else esc(row["client_code"])}</td>
            <td class="vendor-cell">{esc(row["vendor"])}</td>
            <td class="amount-cell">{esc(row["amount"])}</td><td>{esc(row["document_date"])}</td>
            <td>{esc(row["category"])}</td><td>{esc(row["gl_account"])}</td>
            <td>{review_status_badge(status_display)}</td>
            <td>{assign_ctrl}</td>
            <td class="reason-cell">{_ls_badge}{queue_fraud_badges(row)} {esc(reason)}</td>
            <td>{next_action_display}</td></tr>
<tr id="{_detail_id}" class="row-detail-tr"><td colspan="11">
    <div class="detail-box">
        <div style="display:flex;justify-content:space-between;align-items:flex-start;gap:16px;flex-wrap:wrap;">
            <div style="flex:1;min-width:240px;">
                <div style="font-size:11px;text-transform:uppercase;letter-spacing:0.05em;color:#64748b;font-weight:700;margin-bottom:4px;">{esc(t("col_reason", lang))}</div>
                <div style="color:#334155;">{_ls_badge}{queue_fraud_badges(row)} {esc(reason) or '&mdash;'}</div>
            </div>
            <div style="flex:1;min-width:240px;">
                <div style="font-size:11px;text-transform:uppercase;letter-spacing:0.05em;color:#64748b;font-weight:700;margin-bottom:4px;">{esc(t("col_action", lang))}</div>
                <div style="color:#334155;">{next_action_display}</div>
            </div>
            <div>
                <a href="{_doc_url}" class="button-link btn-primary">{esc(t("btn_open", lang)) if t("btn_open", lang) != "btn_open" else "Ouvrir / Open"}</a>
            </div>
        </div>
    </div>
</td></tr>""")

        _fraud_badge_mobile = queue_fraud_badges(row)
        _status_class = "badge-needsreview" if "needs" in status_display.lower() else (
            "badge-hold" if "hold" in status_display.lower() else (
            "badge-ready" if "ready" in status_display.lower() else (
            "badge-posted" if "posted" in status_display.lower() else "badge-muted")))
        card_html.append(f"""<div class="queue-card" onclick="window.location='/document?id={urlquote(row["document_id"])}'">
            <div class="queue-card-header">
                <span class="vendor-name">{esc(row["vendor"])}</span>
                <span class="amount">${esc(row["amount"])}</span>
            </div>
            <div class="queue-card-meta">
                <span class="client-code">{esc(row["client_code"])}</span>
                <span class="doc-date">{esc(row["document_date"])}</span>
            </div>
            <div class="queue-card-footer">
                <span class="badge {_status_class}">{esc(status_display)}</span>
                {_fraud_badge_mobile}
                <a href="/document?id={urlquote(row["document_id"])}" class="btn-sm">Ouvrir</a>
            </div>
        </div>""")

    no_docs_cell = f'<tr><td colspan=11 class=muted>{esc(t("no_documents_found", lang))}</td></tr>'
    table_html = f"""<div class="table-shell">
        <div class="table-top">
            <div>
                <h3>{esc(t("queue_title", lang))}</h3>
                <p>{total_rows} documents \u00b7 Page {page} / {total_pages}</p>
            </div>
        </div>
        <div style="overflow-x:auto;"><table class="queue-table">
            <thead><tr>
                <th>{esc(t("col_document", lang))}</th><th>{esc(t("col_client", lang))}</th>
                <th>{esc(t("col_vendor", lang))}</th><th>{esc(t("col_amount", lang))}</th>
                <th>{esc(t("col_date", lang))}</th><th>{esc(t("col_category", lang))}</th>
                <th>{esc(t("col_gl_account", lang))}</th><th>{esc(t("col_status", lang))}</th>
                <th>{esc(t("col_assigned", lang))}</th><th>{esc(t("col_reason", lang))}</th>
                <th>{esc(t("col_action", lang))}</th>
            </tr></thead>
            <tbody>{"".join(row_html) if row_html else no_docs_cell}</tbody>
        </table></div>
        <div class="queue-cards" style="padding:0 16px 16px;">{"".join(card_html) if card_html else '<p class="muted">' + esc(t("no_documents_found", lang)) + '</p>'}</div>
    </div>"""

    # Pagination controls
    pagination_html = ""
    if total_pages > 1:
        # Build base query string preserving existing filters
        import urllib.parse as _up
        pq = {}
        if status:
            pq["status"] = status
        if q:
            pq["q"] = q
        if include_ignored:
            pq["include_ignored"] = "1"
        if only_my_queue:
            pq["queue_mode"] = "mine"
        elif only_unassigned:
            pq["queue_mode"] = "unassigned"

        def _page_url(p: int) -> str:
            pq["page"] = str(p)
            return "/?" + _up.urlencode(pq)

        page_links: list[str] = []
        if page > 1:
            page_links.append(f'<a class="btn-secondary" href="{esc(_page_url(1))}">&laquo; 1</a>')
            page_links.append(f'<a class="btn-secondary" href="{esc(_page_url(page - 1))}">&lsaquo; Prev</a>')

        # Show window of pages around current
        window_start = max(1, page - 3)
        window_end = min(total_pages, page + 3)
        for p in range(window_start, window_end + 1):
            if p == page:
                page_links.append(f'<strong style="padding:6px 12px;background:#0d6efd;color:#fff;border-radius:4px;">{p}</strong>')
            else:
                page_links.append(f'<a class="btn-secondary" href="{esc(_page_url(p))}">{p}</a>')

        if page < total_pages:
            page_links.append(f'<a class="btn-secondary" href="{esc(_page_url(page + 1))}">Next &rsaquo;</a>')
            page_links.append(f'<a class="btn-secondary" href="{esc(_page_url(total_pages))}">{total_pages} &raquo;</a>')

        pagination_html = f"""<div class="card" style="text-align:center;">
            <div style="display:flex;justify-content:center;align-items:center;gap:6px;flex-wrap:wrap;">
                {" ".join(page_links)}
            </div>
            <div class="small muted" style="margin-top:6px;">
                Page {page} of {total_pages} &middot; {total_rows} documents
            </div>
        </div>"""

    body_html = (
        '<div class="queue-page">'
        + header_html
        + _learning_stats_html
        + unassigned_banner
        + upload_html
        + filters_html
        + table_html
        + pagination_html
        + '</div>'
    )
    return page_layout(t("dashboard_title", lang), body_html,
                       user=user, flash=flash, flash_error=flash_error, lang=lang)


def render_team_workload(
    ctx: dict[str, Any], user: dict[str, Any],
    rows: list[dict[str, Any]],
    flash: str = '', flash_error: str = '', lang: str = 'fr',
) -> str:
    """Team workload report table — per-employee summary of who's
    carrying what."""
    if not rows:
        body = (
            '<div class="card"><h2>&#x1F4CA; Team workload</h2>'
            '<p>No active team members to report on yet.</p>'
            '</div>'
        )
        return page_layout("Team workload", body, user=user,
                            flash=flash, flash_error=flash_error, lang=lang)
    def _cell(v):
        if v is None:
            return '<span style="color:#888;">—</span>'
        return esc(str(v))
    tr = []
    for r in rows:
        avg_h = r['avg_resolution_hours']
        avg_cell = (f'{avg_h:.1f}h' if avg_h is not None else '—')
        tr.append(
            '<tr>'
            f'<td style="padding:8px;color:#e0e0e0;">'
            f'<strong>{esc(r["display_name"])}</strong>'
            f'<div style="color:#888;font-size:11px;">{esc(r["email"])}'
            f' &middot; {esc(r["role"])}</div></td>'
            f'<td style="padding:8px;text-align:right;color:#e0e0e0;">'
            f'{_cell(r["primary_clients"])}</td>'
            f'<td style="padding:8px;text-align:right;color:#888;">'
            f'{_cell(r["secondary_clients"])}</td>'
            f'<td style="padding:8px;text-align:right;'
            f'color:{"#e74c3c" if r["open_docs"] >= 25 else "#e0e0e0"};">'
            f'<strong>{_cell(r["open_docs"])}</strong></td>'
            f'<td style="padding:8px;text-align:right;color:#2ecc71;">'
            f'{_cell(r["completed_this_week"])}</td>'
            f'<td style="padding:8px;text-align:right;color:#aaa;">'
            f'{esc(avg_cell)}</td>'
            '</tr>'
        )
    body = f"""
    <div style="padding:24px;">
        <h2 style="color:white;">&#x1F4CA; Team workload</h2>
        <p style="color:#888;font-size:13px;">
            Per-employee breakdown of client leadership and open document load.
            Open docs include assigned + in-progress + rejected-awaiting-fix.
            Avg resolution covers the last 90 days.
        </p>
        <table style="width:100%;border-collapse:collapse;background:#1a2e4a;border-radius:8px;">
            <thead>
                <tr style="background:#0d1b2a;">
                    <th style="color:#aaa;padding:8px;text-align:left;">Employee</th>
                    <th style="color:#aaa;padding:8px;text-align:right;">Primary clients</th>
                    <th style="color:#aaa;padding:8px;text-align:right;">Secondary</th>
                    <th style="color:#aaa;padding:8px;text-align:right;">Open docs</th>
                    <th style="color:#aaa;padding:8px;text-align:right;">Done (7d)</th>
                    <th style="color:#aaa;padding:8px;text-align:right;">Avg resolve</th>
                </tr>
            </thead>
            <tbody>
                {''.join(tr)}
            </tbody>
        </table>
    </div>"""
    return page_layout("Team workload", body, user=user,
                        flash=flash, flash_error=flash_error, lang=lang)


def _render_unassigned_clients_banner(
    ctx: dict[str, Any], *, lang: str = 'fr',
) -> str:
    """Phase 6 migration nudge.

    Show owner / firm_admin how many clients still have no primary
    employee assigned. Silent when count is 0 so it doesn't nag a
    firm that's fully set up.
    """
    if ctx.get('role') not in ('owner', 'firm_admin'):
        return ''
    firm_code = ctx.get('firm_code') or 'OWNER'
    try:
        with open_db() as conn:
            if ctx.get('role') == 'owner':
                # Owner sees across all firms they administer.
                row = conn.execute(
                    "SELECT COUNT(*) AS n FROM clients "
                    "WHERE COALESCE(primary_employee_email, '') = ''"
                ).fetchone()
            else:
                row = conn.execute(
                    "SELECT COUNT(*) AS n FROM clients "
                    "WHERE firm_code = ? "
                    "  AND COALESCE(primary_employee_email, '') = ''",
                    (firm_code,),
                ).fetchone()
    except sqlite3.OperationalError:
        return ''
    n = int(row['n'] or 0) if row else 0
    if n <= 0:
        return ''
    # Bilingual copy matches the rest of the dashboard.
    msg_fr = (
        f"Vous avez <strong>{n}</strong> client(s) sans employé responsable."
    )
    msg_en = (
        f"You have <strong>{n}</strong> client(s) with no primary employee."
    )
    return (
        '<div style="margin:16px 0;padding:14px 16px;background:#fff7e6;'
        'border:1px solid #f5c16c;border-radius:6px;color:#4a2a00;'
        'display:flex;gap:12px;align-items:center;flex-wrap:wrap;">'
        '<div style="font-size:18px;">&#128681;</div>'
        '<div style="flex:1;min-width:240px;">'
        f'<div>{msg_fr}</div>'
        f'<div style="color:#6b4a00;font-size:12px;">{msg_en}</div>'
        '</div>'
        '<a href="/clients?assignee=__pool__" '
        ' style="background:#d97706;color:white;padding:8px 14px;'
        ' border-radius:4px;text-decoration:none;">'
        'Assigner / Assign &rarr;</a>'
        '</div>'
    )


# ---------------------------------------------------------------------------
# Decision cards — structured decision workflow for flagged documents
# ---------------------------------------------------------------------------

_GST_RATE = 0.05
_QST_RATE = 0.09975


def _build_decision_cards(row: sqlite3.Row, raw_result: dict[str, Any],
                          document_id: str, lang: str = "fr") -> list[dict[str, Any]]:
    """Detect up to 10 blocked/uncertain scenarios and return decision card dicts.

    Each card: icon, title_fr, title_en, severity ('red'|'amber'|'blue'),
    issue_fr, issue_en, why_fr, why_en, recommended_action (dict with
    label_fr, label_en, form_action, form_fields), alternatives (list of
    similar dicts).
    """
    cards: list[dict[str, Any]] = []
    doc_type = normalize_text(row["doc_type"]).lower() if row.get("doc_type") else ""
    amount_str = normalize_text(row["amount"])
    try:
        amount_val = float(amount_str.replace(",", "").replace("$", "").strip()) if amount_str else 0.0
    except (ValueError, TypeError):
        amount_val = 0.0
    abs_amount = abs(amount_val)
    vendor = normalize_text(row["vendor"])
    gst = raw_result.get("gst_amount")
    qst = raw_result.get("qst_amount")
    tax_code = normalize_text(row["tax_code"])
    fraud_flags_raw: list[dict[str, Any]] = []
    try:
        ff = row["fraud_flags"]
        if ff:
            parsed = json.loads(ff) if isinstance(ff, str) else ff
            if isinstance(parsed, list):
                fraud_flags_raw = parsed
    except Exception:
        pass
    fraud_keys = {str(f.get("i18n_key", "")) for f in fraud_flags_raw}
    fraud_keys.update(str(f.get("type", "")) for f in fraud_flags_raw)
    fraud_keys.update(str(f.get("rule", "")) for f in fraud_flags_raw)

    duplicate = raw_result.get("duplicate_result") or {}
    vendor_mem = raw_result.get("vendor_memory_enrichment") or {}
    exc_router = raw_result.get("exception_router_result") or {}
    client_code = normalize_text(row["client_code"])
    doc_date = normalize_text(row["document_date"])

    # --- SCENARIO 1: Credit memo with no GST/QST breakdown ---
    is_credit = doc_type in {"credit_note", "credit_memo", "refund", "chargeback",
                             "reversal", "note de crédit"} or amount_val < 0
    has_no_tax_breakdown = (gst is None or gst == "" or gst == 0) and (
        qst is None or qst == "" or qst == 0)
    if is_credit and abs_amount > 0 and has_no_tax_breakdown:
        pretax = round(abs_amount / (1 + _GST_RATE + _QST_RATE), 2)
        est_gst = round(pretax * _GST_RATE, 2)
        est_qst = round(pretax * _QST_RATE, 2)
        cards.append({
            "icon": "\U0001f4cb", "severity": "amber",
            "title_fr": "NOTE DE CR\u00c9DIT \u2014 TAXE NON VENTIL\u00c9E",
            "title_en": "Credit Memo \u2014 Tax Not Itemized",
            "issue_fr": f"La note de cr\u00e9dit de {money(abs_amount, lang)} ne montre pas la TPS/TVQ s\u00e9par\u00e9ment.",
            "issue_en": f"Credit memo of {money(abs_amount, lang)} does not show GST/QST separately.",
            "why_fr": f"Sans ventilation, vous ne pouvez pas r\u00e9cup\u00e9rer vos CTI/RTI. Perte potentielle: {money(est_gst + est_qst, lang)}.",
            "why_en": f"Without breakdown you cannot claim your ITC/ITR. Potential loss: {money(est_gst + est_qst, lang)}.",
            "recommended": {
                "label_fr": f"Appliquer allocation proportionnelle \u2014 TPS: ${est_gst} | TVQ: ${est_qst} | Avant taxes: ${pretax}",
                "label_en": "Apply proportional allocation",
                "action": "/document/update", "method": "POST",
                "fields": {"document_id": document_id, "tax_code": "H",
                            "amount": str(amount_str)},
            },
            "alternatives": [
                {"label_fr": "Entrer manuellement", "label_en": "Enter manually",
                 "action": f"/document/{urlquote(document_id)}#edit", "method": "GET", "fields": {}},
                {"label_fr": "Demander au fournisseur", "label_en": "Ask supplier",
                 "action": "/document/hold", "method": "POST",
                 "fields": {"document_id": document_id,
                             "hold_reason": "Demander ventilation TPS/TVQ au fournisseur"}},
                {"label_fr": "Traiter sans taxes", "label_en": "Process without tax",
                 "action": "/document/update", "method": "POST",
                 "fields": {"document_id": document_id, "tax_code": "E"}},
            ],
        })

    # --- SCENARIO 2: New vendor, large amount ---
    is_new_vendor = vendor_mem.get("is_new_vendor", False) or vendor_mem.get("invoice_count", 999) <= 1
    _new_vendor_threshold = 3000.0
    if is_new_vendor and abs_amount >= _new_vendor_threshold:
        cards.append({
            "icon": "\U0001f6a8", "severity": "red",
            "title_fr": f"NOUVEAU FOURNISSEUR \u2014 MONTANT \u00c9LEV\u00c9",
            "title_en": "New Vendor \u2014 Large Amount",
            "issue_fr": f"{vendor} \u2014 premi\u00e8re facture {money(abs_amount, lang)}",
            "issue_en": f"{vendor} \u2014 first invoice {money(abs_amount, lang)}",
            "why_fr": "Factures importantes de nouveaux fournisseurs sont une m\u00e9thode de fraude courante.",
            "why_en": "Large invoices from new vendors are a common fraud method.",
            "recommended": {
                "label_fr": "Approuver \u2014 fournisseur v\u00e9rifi\u00e9",
                "label_en": "Approve \u2014 verified vendor",
                "action": "/qbo/approve", "method": "POST",
                "fields": {"document_id": document_id},
            },
            "alternatives": [
                {"label_fr": "Mettre en attente", "label_en": "Put on hold",
                 "action": "/document/hold", "method": "POST",
                 "fields": {"document_id": document_id,
                             "hold_reason": "Nouveau fournisseur \u2014 v\u00e9rification requise"}},
                {"label_fr": "Signaler \u00e0 la direction", "label_en": "Flag for management",
                 "action": "/document/hold", "method": "POST",
                 "fields": {"document_id": document_id,
                             "hold_reason": "Signal\u00e9 \u00e0 la direction \u2014 nouveau fournisseur montant \u00e9lev\u00e9"}},
                {"label_fr": "Rejeter", "label_en": "Reject",
                 "action": "/document/update", "method": "POST",
                 "fields": {"document_id": document_id, "review_status": "Ignored"}},
            ],
        })

    # --- SCENARIO 3: Payment recipient differs from invoice vendor ---
    payment_to = normalize_text(raw_result.get("payment_recipient") or raw_result.get("payee") or "")
    _recipient_mismatch = any("recipient" in k or "payee_mismatch" in k or "vendor_mismatch" in k
                              for k in fraud_keys)
    if not _recipient_mismatch and payment_to and vendor:
        _sim = _simple_similarity(vendor.lower(), payment_to.lower())
        if 0 < _sim < 0.90 and payment_to.lower() != vendor.lower():
            _recipient_mismatch = True
    if _recipient_mismatch and payment_to:
        _sim_pct = int(_simple_similarity(vendor.lower(), payment_to.lower()) * 100) if vendor and payment_to else 0
        cards.append({
            "icon": "\u26a0\ufe0f", "severity": "red",
            "title_fr": "B\u00c9N\u00c9FICIAIRE DIFF\u00c9RENT DU FOURNISSEUR",
            "title_en": "Payment Recipient Differs from Invoice Vendor",
            "issue_fr": f"Facture de: {vendor}. Paiement \u00e0: {payment_to} (similarit\u00e9 {_sim_pct}%)",
            "issue_en": f"Invoice from: {vendor}. Payment to: {payment_to} (similarity {_sim_pct}%)",
            "why_fr": "Le paiement va \u00e0 une entit\u00e9 diff\u00e9rente. Peut indiquer une fraude ou soci\u00e9t\u00e9 affili\u00e9e.",
            "why_en": "Payment goes to a different entity. May indicate fraud or affiliated company.",
            "recommended": {
                "label_fr": "C'est une filiale \u2014 m\u00eame fournisseur",
                "label_en": "Affiliate \u2014 same vendor",
                "action": "/qbo/approve", "method": "POST",
                "fields": {"document_id": document_id},
            },
            "alternatives": [
                {"label_fr": "Mettre en attente \u2014 v\u00e9rifier", "label_en": "Hold \u2014 verify",
                 "action": "/document/hold", "method": "POST",
                 "fields": {"document_id": document_id,
                             "hold_reason": "V\u00e9rifier b\u00e9n\u00e9ficiaire vs fournisseur"}},
                {"label_fr": "Signaler comme suspect", "label_en": "Flag as suspicious",
                 "action": "/document/hold", "method": "POST",
                 "fields": {"document_id": document_id,
                             "hold_reason": "Suspect \u2014 b\u00e9n\u00e9ficiaire diff\u00e9rent du fournisseur"}},
            ],
        })

    # --- SCENARIO 4: CapEx detected disguised as expense ---
    _capex_keywords = {"remplacement complet", "complete replacement", "hvac", "toiture",
                       "roof", "syst\u00e8me", "system", "\u00e9quipement", "equipment",
                       "machinerie", "machinery", "v\u00e9hicule", "vehicle",
                       "b\u00e2timent", "building", "construction", "renovation"}
    _capex_threshold = 5000.0
    _desc_lower = (normalize_text(raw_result.get("description") or "") + " " + normalize_text(row.get("file_name") or "")).lower()
    _is_capex_candidate = abs_amount >= _capex_threshold and any(kw in _desc_lower for kw in _capex_keywords)
    _is_expense_gl = normalize_text(row["gl_account"]).startswith(("5", "6")) if row.get("gl_account") else False
    if _is_capex_candidate and _is_expense_gl:
        _cca_rate = 0.20
        _cca_deduction = round(abs_amount * _cca_rate * 0.5, 2)  # half-year rule
        _nbv = round(abs_amount - _cca_deduction, 2)
        cards.append({
            "icon": "\U0001f3d7\ufe0f", "severity": "amber",
            "title_fr": "IMMOBILISATION POSSIBLE",
            "title_en": "Possible Capital Asset",
            "issue_fr": f"Facture: {_desc_lower[:60].strip()} {money(abs_amount, lang)}. Classifi\u00e9 comme: d\u00e9pense.",
            "issue_en": f"Invoice: {money(abs_amount, lang)} classified as operating expense.",
            "why_fr": f"Si pass\u00e9 en d\u00e9pense: actifs sous-\u00e9valu\u00e9s de {money(abs_amount, lang)}, charges sur\u00e9valu\u00e9es.",
            "why_en": f"If expensed: assets understated by {money(abs_amount, lang)}, expenses overstated.",
            "recommended": {
                "label_fr": f"Cr\u00e9er immobilisation Classe 8 (20%) \u2014 DPA: {money(_cca_deduction, lang)} | VNI: {money(_nbv, lang)}",
                "label_en": "Create capital asset Class 8 (20%)",
                "action": "/document/update", "method": "POST",
                "fields": {"document_id": document_id, "gl_account": "1500",
                            "category": "Capital Asset"},
            },
            "alternatives": [
                {"label_fr": "C'est une r\u00e9paration \u2014 d\u00e9pense", "label_en": "It is a repair \u2014 expense",
                 "action": "/qbo/approve", "method": "POST",
                 "fields": {"document_id": document_id}},
                {"label_fr": "D\u00e9cider plus tard", "label_en": "Decide later",
                 "action": "/document/hold", "method": "POST",
                 "fields": {"document_id": document_id,
                             "hold_reason": "D\u00e9cision CapEx vs OpEx en attente"}},
            ],
        })

    # --- SCENARIO 5: Date ambiguous Q1 vs Q2 ---
    _date_ambiguous = False
    _interp_a = _interp_b = ""
    if doc_date:
        import re as _re
        _dm = _re.match(r"^(\d{1,2})[/\-.](\d{1,2})[/\-.](\d{4})$", doc_date.strip())
        if _dm:
            _p1, _p2, _yr = int(_dm.group(1)), int(_dm.group(2)), _dm.group(3)
            if 1 <= _p1 <= 12 and 1 <= _p2 <= 12 and _p1 != _p2:
                _date_ambiguous = True
                _q_a = (_p2 - 1) // 3 + 1
                _q_b = (_p1 - 1) // 3 + 1
                _month_names_dc = ["janvier", "f\u00e9vrier", "mars", "avril", "mai", "juin",
                                   "juillet", "ao\u00fbt", "septembre", "octobre", "novembre", "d\u00e9cembre"]
                _interp_a = f"{_p1} {_month_names_dc[_p2 - 1]} {_yr} (T{_q_a})"
                _interp_b = f"{_p2} {_month_names_dc[_p1 - 1]} {_yr} (T{_q_b})"
    if _date_ambiguous:
        cards.append({
            "icon": "\U0001f4c5", "severity": "amber",
            "title_fr": "DATE AMBIGU\u00cb \u2014 P\u00c9RIODE \u00c0 CONFIRMER",
            "title_en": "Ambiguous Date \u2014 Period to Confirm",
            "issue_fr": f"Date sur la facture: {doc_date}",
            "issue_en": f"Date on invoice: {doc_date}",
            "why_fr": "Affecte la p\u00e9riode TPS/TVQ et l'exercice.",
            "why_en": "Affects GST/QST period and fiscal year.",
            "recommended": {
                "label_fr": f"Interpr\u00e9tation A: {_interp_a}",
                "label_en": f"Interpretation A: {_interp_a}",
                "action": "/document/update", "method": "POST",
                "fields": {"document_id": document_id, "document_date": doc_date},
            },
            "alternatives": [
                {"label_fr": f"Interpr\u00e9tation B: {_interp_b}", "label_en": f"Interpretation B: {_interp_b}",
                 "action": "/document/update", "method": "POST",
                 "fields": {"document_id": document_id, "document_date": doc_date}},
                {"label_fr": "Demander au client", "label_en": "Ask client",
                 "action": "/document/hold", "method": "POST",
                 "fields": {"document_id": document_id,
                             "hold_reason": "Date ambigu\u00eb \u2014 confirmer avec le client"}},
            ],
        })

    # --- SCENARIO 6: Loan payment not split ---
    _loan_keywords = {"pr\u00eat", "loan", "hypoth\u00e8que", "mortgage", "emprunt",
                      "financement", "financing", "desjardins", "banque nationale",
                      "caisse", "versement"}
    _is_loan = any(kw in _desc_lower or kw in vendor.lower() for kw in _loan_keywords)
    _gl_is_single = row.get("gl_account") and not raw_result.get("line_items")
    if _is_loan and abs_amount > 500 and _gl_is_single:
        _est_interest = round(abs_amount * 0.21, 2)  # rough estimate
        _est_principal = round(abs_amount - _est_interest, 2)
        cards.append({
            "icon": "\U0001f4b3", "severity": "blue",
            "title_fr": "PAIEMENT DE PR\u00caT \u2014 VENTILATION REQUISE",
            "title_en": "Loan Payment \u2014 Split Required",
            "issue_fr": f"Paiement: {money(abs_amount, lang)} \u00e0 {vendor}. D\u00e9tect\u00e9 comme paiement de pr\u00eat.",
            "issue_en": f"Payment: {money(abs_amount, lang)} to {vendor}. Detected as loan payment.",
            "why_fr": "Capital (GL 2500) et int\u00e9r\u00eats (GL 5480) doivent \u00eatre s\u00e9par\u00e9s. Les int\u00e9r\u00eats sont d\u00e9ductibles.",
            "why_en": "Principal (GL 2500) and interest (GL 5480) must be separated. Interest is deductible.",
            "recommended": {
                "label_fr": f"Confirmer: Capital {money(_est_principal, lang)} \u2192 GL 2500 | Int\u00e9r\u00eats {money(_est_interest, lang)} \u2192 GL 5480",
                "label_en": "Confirm estimated split",
                "action": "/document/update", "method": "POST",
                "fields": {"document_id": document_id, "gl_account": "2500",
                            "category": "Loan Payment"},
            },
            "alternatives": [
                {"label_fr": "Entrer les vrais montants", "label_en": "Enter actual amounts",
                 "action": f"/document/{urlquote(document_id)}#edit", "method": "GET", "fields": {}},
                {"label_fr": "Tout au capital", "label_en": "All to principal",
                 "action": "/document/update", "method": "POST",
                 "fields": {"document_id": document_id, "gl_account": "2500"}},
            ],
        })

    # --- SCENARIO 7: GST/QST from unregistered supplier ---
    _gst_number = normalize_text(raw_result.get("gst_number") or raw_result.get("tax_registration") or "")
    _has_tax_charged = (gst and float(str(gst).replace(",", "").replace("$", "") or "0") > 0) or (
        qst and float(str(qst).replace(",", "").replace("$", "") or "0") > 0)
    _unregistered = any("unregistered" in k or "non_inscrit" in k or "missing_gst" in k
                        for k in fraud_keys)
    if not _gst_number and _has_tax_charged or _unregistered:
        _tax_gst = float(str(gst).replace(",", "").replace("$", "") or "0") if gst else 0
        _tax_qst = float(str(qst).replace(",", "").replace("$", "") or "0") if qst else 0
        cards.append({
            "icon": "\u274c", "severity": "red",
            "title_fr": "FOURNISSEUR NON INSCRIT \u2014 TPS/TVQ INVALIDE",
            "title_en": "Unregistered Supplier \u2014 GST/QST Invalid",
            "issue_fr": f"{vendor}: TPS factur\u00e9e {money(_tax_gst, lang)} | TVQ factur\u00e9e {money(_tax_qst, lang)}. Num\u00e9ro TPS: Absent.",
            "issue_en": f"{vendor}: GST charged {money(_tax_gst, lang)} | QST charged {money(_tax_qst, lang)}. GST number: Missing.",
            "why_fr": "Un fournisseur non inscrit ne peut pas facturer la TPS/TVQ. CTI/RTI non r\u00e9clamables.",
            "why_en": "Unregistered supplier cannot charge GST/QST. ITC/ITR not claimable. CRA/RQ audit risk.",
            "recommended": {
                "label_fr": "Traiter \u2014 aucun CTI/RTI",
                "label_en": "Process \u2014 no ITC/ITR",
                "action": "/document/update", "method": "POST",
                "fields": {"document_id": document_id, "tax_code": "E"},
            },
            "alternatives": [
                {"label_fr": "Demander num\u00e9ro TPS au fournisseur", "label_en": "Request GST number",
                 "action": "/document/hold", "method": "POST",
                 "fields": {"document_id": document_id,
                             "hold_reason": "Demander num\u00e9ro TPS/TVQ au fournisseur"}},
                {"label_fr": "Fournisseur inscrit \u2014 entrer num\u00e9ro", "label_en": "Is registered \u2014 enter number",
                 "action": f"/document/{urlquote(document_id)}#edit", "method": "GET", "fields": {}},
            ],
        })

    # --- SCENARIO 8: Personal expense flagged ---
    _personal_keywords = {"cottage", "personnel", "personal", "maison", "r\u00e9sidence",
                          "vacances", "vacation", "familial", "family", "priv\u00e9"}
    _is_personal = any(kw in _desc_lower for kw in _personal_keywords) or any(
        "personal" in k for k in fraud_keys)
    if _is_personal:
        cards.append({
            "icon": "\U0001f3e0", "severity": "amber",
            "title_fr": "D\u00c9PENSE PERSONNELLE POSSIBLE",
            "title_en": "Possible Personal Expense",
            "issue_fr": f"Facture: {_desc_lower[:50].strip()} {money(abs_amount, lang)}. Usage personnel probable.",
            "issue_en": f"Invoice: {money(abs_amount, lang)}. Likely personal use detected.",
            "why_fr": "Les d\u00e9penses personnelles ne sont pas d\u00e9ductibles. CTI/RTI non r\u00e9clamables.",
            "why_en": "Personal expenses are not deductible. ITC/ITR not claimable.",
            "recommended": {
                "label_fr": "D\u00e9pense personnelle \u2014 retirer",
                "label_en": "Personal \u2014 remove",
                "action": "/document/update", "method": "POST",
                "fields": {"document_id": document_id, "review_status": "Ignored",
                            "category": "Personal"},
            },
            "alternatives": [
                {"label_fr": "Usage mixte \u2014 quelle proportion?", "label_en": "Mixed use \u2014 what %?",
                 "action": f"/document/{urlquote(document_id)}#edit", "method": "GET", "fields": {}},
                {"label_fr": "C'est une d\u00e9pense d'entreprise", "label_en": "Business expense",
                 "action": "/qbo/approve", "method": "POST",
                 "fields": {"document_id": document_id}},
            ],
        })

    # --- SCENARIO 9: Duplicate invoice suspected ---
    _dup_risk = normalize_key(duplicate.get("risk_level", ""))
    _dup_match_id = normalize_text(duplicate.get("matched_document_id") or duplicate.get("match_id") or "")
    _dup_score = duplicate.get("similarity_score") or duplicate.get("score") or 0
    if _dup_risk in {"medium", "high"} or _dup_match_id:
        _sim_display = int(float(_dup_score) * 100) if isinstance(_dup_score, (int, float)) and _dup_score <= 1 else int(_dup_score)
        cards.append({
            "icon": "\U0001f504", "severity": "red",
            "title_fr": "FACTURE EN DOUBLE POSSIBLE",
            "title_en": "Possible Duplicate Invoice",
            "issue_fr": f"{vendor} {money(abs_amount, lang)}. Facture similaire: {_dup_match_id} (similarit\u00e9 {_sim_display}%)",
            "issue_en": f"{vendor} {money(abs_amount, lang)}. Similar invoice: {_dup_match_id} (similarity {_sim_display}%)",
            "why_fr": "Payer deux fois la m\u00eame facture = perte directe pour le client.",
            "why_en": "Paying the same invoice twice = direct loss for the client.",
            "recommended": {
                "label_fr": "Voir la facture originale",
                "label_en": "View original",
                "action": f"/document/{urlquote(_dup_match_id)}", "method": "GET",
                "fields": {},
            },
            "alternatives": [
                {"label_fr": "C'est un doublon \u2014 rejeter", "label_en": "Duplicate \u2014 reject",
                 "action": "/document/update", "method": "POST",
                 "fields": {"document_id": document_id, "review_status": "Ignored"}},
                {"label_fr": "Factures diff\u00e9rentes \u2014 approuver", "label_en": "Different \u2014 approve",
                 "action": "/qbo/approve", "method": "POST",
                 "fields": {"document_id": document_id}},
            ],
        })

    # --- SCENARIO 10: Period locked ---
    if client_code and doc_date:
        _period = get_document_period(doc_date)
        if _period:
            try:
                with open_db() as _conn:
                    if is_period_locked(_conn, client_code, _period):
                        _lock_info = get_lock_info(_conn, client_code, _period)
                        _locked_date = _lock_info.get("locked_at", "") if _lock_info else ""
                        # Suggest next open period
                        import re as _re2
                        _pm = _re2.match(r"(\d{4})-(\d{2})", _period)
                        if _pm:
                            _yr, _mo = int(_pm.group(1)), int(_pm.group(2))
                            _next_mo = _mo + 1 if _mo < 12 else 1
                            _next_yr = _yr if _mo < 12 else _yr + 1
                            _next_period = f"{_next_yr}-{_next_mo:02d}"
                        else:
                            _next_period = ""
                        _month_names = "janvier f\u00e9vrier mars avril mai juin juillet ao\u00fbt septembre octobre novembre d\u00e9cembre".split()
                        _period_label = _period
                        if _pm:
                            _period_label = f"{_month_names[int(_pm.group(2)) - 1]} {_pm.group(1)}"
                        cards.append({
                            "icon": "\U0001f512", "severity": "blue",
                            "title_fr": "P\u00c9RIODE VERROUILL\u00c9E",
                            "title_en": "Period is Locked",
                            "issue_fr": f"Document dat\u00e9: {_period_label}. P\u00e9riode verrouill\u00e9e{(' le ' + _locked_date) if _locked_date else ''}.",
                            "issue_en": f"Document dated: {_period_label}. Period locked{(' on ' + _locked_date) if _locked_date else ''}.",
                            "why_fr": "Modifier des p\u00e9riodes ferm\u00e9es cr\u00e9e des \u00e9carts dans les rapprochements.",
                            "why_en": "Modifying closed periods creates discrepancies in reconciliations.",
                            "recommended": {
                                "label_fr": f"Reporter en {_next_period}",
                                "label_en": f"Post to {_next_period}",
                                "action": "/document/update", "method": "POST",
                                "fields": {"document_id": document_id,
                                            "document_date": f"{_next_period}-01" if _next_period else doc_date},
                            },
                            "alternatives": [
                                {"label_fr": "D\u00e9verrouiller \u2014 gestionnaire requis", "label_en": "Unlock \u2014 manager required",
                                 "action": "/document/hold", "method": "POST",
                                 "fields": {"document_id": document_id,
                                             "hold_reason": f"Demande d\u00e9verrouillage p\u00e9riode {_period}"}},
                                {"label_fr": "Mettre en attente", "label_en": "Hold",
                                 "action": "/document/hold", "method": "POST",
                                 "fields": {"document_id": document_id,
                                             "hold_reason": f"P\u00e9riode {_period} verrouill\u00e9e"}},
                            ],
                        })
            except Exception:
                pass

    # --- SCENARIO 11: Cross-client mismatch ---
    try:
        from src.engines.client_mismatch_engine import detect_client_mismatch
        _mismatch_data = {
            "raw_ocr_text": normalize_text(raw_result.get("raw_ocr_text") or raw_result.get("extracted_text", "")),
            "bill_to": normalize_text(raw_result.get("bill_to", "")),
            "billing_email": normalize_text(raw_result.get("billing_email", "")),
            "gst_number": normalize_text(raw_result.get("recipient_gst", "")),
            "qst_number": normalize_text(raw_result.get("recipient_qst", "")),
        }
        if client_code:
            with open_db() as _mc:
                _mismatch = detect_client_mismatch(_mismatch_data, client_code, _mc)
            if _mismatch.get("mismatch_detected"):
                _sugg_code = _mismatch.get("suggested_client_code", "")
                _sugg_name = _mismatch.get("suggested_client_name", "")
                _sub_name = _mismatch.get("submitted_client_name", client_code)
                _check_detail = _mismatch["checks"][0] if _mismatch.get("checks") else {}
                cards.append({
                    "icon": "\u26a0\ufe0f", "severity": "red",
                    "title_fr": "MAUVAIS CLIENT / WRONG CLIENT",
                    "title_en": "Document may belong to another client",
                    "issue_fr": f"Soumis par: {_sub_name or client_code}. Factur\u00e9 \u00e0: {_sugg_name or _sugg_code}.",
                    "issue_en": f"Submitted by: {_sub_name or client_code}. Billed to: {_sugg_name or _sugg_code}.",
                    "why_fr": "Ce document semble appartenir \u00e0 un autre client. V\u00e9rifiez avant d\u2019approuver.",
                    "why_en": "This document appears to belong to another client. Verify before approving.",
                    "recommended": {
                        "label_fr": f"D\u00e9placer vers {_sugg_code} / Move to {_sugg_code}",
                        "label_en": f"Move to {_sugg_code}",
                        "action": "/document/update", "method": "POST",
                        "fields": {"document_id": document_id, "client_code": _sugg_code},
                    },
                    "alternatives": [
                        {"label_fr": f"Garder dans {client_code} / Keep in {client_code}",
                         "label_en": f"Keep in {client_code}",
                         "action": f"/document/{urlquote(document_id)}#edit", "method": "GET", "fields": {}},
                        {"label_fr": "Demander confirmation / Ask for confirmation",
                         "label_en": "Ask for confirmation",
                         "action": "/document/hold", "method": "POST",
                         "fields": {"document_id": document_id,
                                     "hold_reason": f"V\u00e9rifier si ce document appartient \u00e0 {_sugg_code}"}},
                    ],
                })
                # Update document mismatch columns
                try:
                    with open_db() as _mc2:
                        from src.engines.client_mismatch_engine import ensure_mismatch_columns
                        ensure_mismatch_columns(_mc2)
                        _mc2.execute(
                            "UPDATE documents SET suspected_client_mismatch = 1, suggested_client_code = ? WHERE document_id = ?",
                            (_sugg_code, document_id),
                        )
                        _mc2.commit()
                except Exception:
                    pass
    except Exception:
        pass

    return cards


def _simple_similarity(a: str, b: str) -> float:
    """Quick bigram similarity (Dice coefficient) for vendor name matching."""
    if not a or not b:
        return 0.0
    if a == b:
        return 1.0

    def _bigrams(s: str) -> set[str]:
        return {s[i:i+2] for i in range(len(s) - 1)} if len(s) > 1 else {s}

    ba, bb = _bigrams(a), _bigrams(b)
    if not ba or not bb:
        return 0.0
    return 2.0 * len(ba & bb) / (len(ba) + len(bb))


def _render_decision_cards(cards: list[dict[str, Any]], document_id: str) -> str:
    """Render decision cards as HTML, placed at the top of the document page."""
    if not cards:
        return ""
    parts: list[str] = []
    for card in cards:
        severity = card.get("severity", "amber")
        icon = card.get("icon", "")
        # Header
        header = (
            f'<div class="decision-card-header">'
            f'<span class="dc-icon">{icon}</span>'
            f'<span class="dc-title-fr">{esc(card["title_fr"])}</span>'
            f'<span class="dc-title-en">\u2014 {esc(card["title_en"])}</span>'
            f'</div>'
        )
        # Body
        body_parts = []
        # Issue
        body_parts.append(
            f'<div class="dc-section">'
            f'<div class="dc-label">Probl\u00e8me / Issue</div>'
            f'<div class="dc-text">{esc(card["issue_fr"])}</div>'
            f'<div class="dc-text-en">{esc(card["issue_en"])}</div>'
            f'</div>'
        )
        # Why
        body_parts.append(
            f'<div class="dc-section">'
            f'<div class="dc-label">Pourquoi / Why it matters</div>'
            f'<div class="dc-text">{esc(card["why_fr"])}</div>'
            f'<div class="dc-text-en">{esc(card["why_en"])}</div>'
            f'</div>'
        )
        body = f'<div class="decision-card-body">{"".join(body_parts)}</div>'

        # Actions
        rec = card.get("recommended", {})
        alts = card.get("alternatives", [])
        action_parts = []

        # Recommended action button
        if rec:
            if rec.get("method", "POST") == "GET":
                action_parts.append(
                    f'<a class="dc-btn-primary" href="{esc(rec["action"])}">'
                    f'\u2705 {esc(rec["label_fr"])}</a>'
                )
            else:
                fields_html = "".join(
                    f'<input type="hidden" name="{esc(k)}" value="{esc(v)}">'
                    for k, v in rec.get("fields", {}).items()
                )
                action_parts.append(
                    f'<form method="POST" action="{esc(rec["action"])}" style="display:inline;">'
                    f'{fields_html}'
                    f'<button class="dc-btn-primary" type="submit">'
                    f'\u2705 {esc(rec["label_fr"])}</button></form>'
                )

        # Alternative buttons
        for alt in alts:
            if alt.get("method", "POST") == "GET":
                action_parts.append(
                    f'<a class="dc-btn-alt" href="{esc(alt["action"])}">'
                    f'{esc(alt["label_fr"])}</a>'
                )
            else:
                fields_html = "".join(
                    f'<input type="hidden" name="{esc(k)}" value="{esc(v)}">'
                    for k, v in alt.get("fields", {}).items()
                )
                action_parts.append(
                    f'<form method="POST" action="{esc(alt["action"])}" style="display:inline;">'
                    f'{fields_html}'
                    f'<button class="dc-btn-alt" type="submit">'
                    f'{esc(alt["label_fr"])}</button></form>'
                )

        actions = f'<div class="dc-actions">{"".join(action_parts)}</div>'

        parts.append(
            f'<div class="decision-card dc-severity-{severity}">'
            f'{header}{body}{actions}</div>'
        )

    return "".join(parts)


